#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OsNotificationKind {
    Permission,
    TurnComplete,
    SessionError,
}

#[derive(Debug, Clone)]
struct PendingOsNotification {
    terminal_id: u64,
    tool: Option<AiCliTool>,
    kind: OsNotificationKind,
}

fn notification_title_and_body(
    tool: Option<AiCliTool>,
    kind: OsNotificationKind,
) -> (String, String) {
    let agent = match tool {
        Some(AiCliTool::FactoryDroid) => "Factory Droid",
        Some(AiCliTool::CodexCli) => "Codex CLI",
        Some(AiCliTool::OpenCode) => "OpenCode",
        Some(AiCliTool::Claude) => "Claude",
        None => "AI Agent",
    };
    match kind {
        OsNotificationKind::Permission => (
            format!("{} needs your input", agent),
            "The agent is waiting for approval or a reply.".to_owned(),
        ),
        OsNotificationKind::TurnComplete => (
            format!("{} finished", agent),
            "The agent completed its turn and is ready for your next prompt.".to_owned(),
        ),
        OsNotificationKind::SessionError => (
            format!("{} error", agent),
            "An error occurred. Please review the terminal output.".to_owned(),
        ),
    }
}

#[cfg(target_os = "windows")]
fn is_tray_balloon_user_click_message(message: u32, icon_id: usize, event: isize) -> bool {
    message == MERGEN_TRAY_CALLBACK_MESSAGE
        && icon_id == MERGEN_TRAY_ICON_ID as usize
        && event as u32 == windows::Win32::UI::Shell::NIN_BALLOONUSERCLICK
}

#[cfg(target_os = "windows")]
unsafe extern "system" fn mergen_tray_window_proc(
    hwnd: HWND,
    message: u32,
    wparam: usize,
    lparam: isize,
) -> isize {
    use windows_sys::Win32::UI::WindowsAndMessaging::{CallWindowProcW, DefWindowProcW, WNDPROC};

    if is_tray_balloon_user_click_message(message, wparam, lparam) {
        MERGEN_TRAY_BALLOON_CLICKED.store(true, Ordering::SeqCst);
        return 0;
    }

    let previous = MERGEN_TRAY_PREVIOUS_WNDPROC.load(Ordering::SeqCst);
    if previous != 0 {
        let previous_proc: WNDPROC = std::mem::transmute(previous);
        CallWindowProcW(previous_proc, hwnd, message, wparam, lparam)
    } else {
        DefWindowProcW(hwnd, message, wparam, lparam)
    }
}

