impl Default for SmartInputState {
    fn default() -> Self {
        Self {
            draft: String::new(),
            draft_attachments: Vec::new(),
            draft_return_target: None,
            expanded: true,
            tasks: Vec::new(),
            next_task_id: 1,
            editing_task_id: None,
            edit_draft: String::new(),
            edit_attachments: Vec::new(),
            dragging_task_id: None,
            drag_hover_index: None,
            user_height: None,
            draft_user_height: None,
            history_nav_index: None,
            history_nav_stash: String::new(),
            history_nav_stash_attachments: Vec::new(),
            next_attachment_id: 1,
            draft_context_menu_selection_range: None,
            draft_context_menu_was_open: false,
            edit_context_menu_selection_range: None,
            edit_context_menu_was_open: false,
            queue_scroll_to_end: false,
        }
    }
}

impl SmartInputState {
    fn enqueue_draft(&mut self) -> Option<u64> {
        if self.draft.trim().is_empty() && self.draft_attachments.is_empty() {
            return None;
        }

        let return_target = self.draft_return_target.take();
        let id = if let Some(target) = return_target {
            target.task_id
        } else {
            let id = self.next_task_id;
            self.next_task_id = self.next_task_id.saturating_add(1).max(1);
            id
        };
        let attachments = std::mem::take(&mut self.draft_attachments);
        let task = SmartInputTask {
            id,
            text: self.draft.clone(),
            attachments,
        };
        if let Some(target) = return_target {
            let insert_index = target.index.min(self.tasks.len());
            self.tasks.insert(insert_index, task);
            self.queue_scroll_to_end = false;
        } else {
            self.tasks.push(task);
            self.queue_scroll_to_end = true;
        }
        self.draft.clear();
        self.history_nav_reset();
        self.draft_context_menu_selection_range = None;
        self.draft_context_menu_was_open = false;
        Some(id)
    }

    fn move_task_to_draft_for_edit(&mut self, task_id: u64) -> SmartInputDraftEditResult {
        let Some(index) = self.tasks.iter().position(|task| task.id == task_id) else {
            return SmartInputDraftEditResult::Missing;
        };
        if !self.draft.is_empty() || !self.draft_attachments.is_empty() {
            return SmartInputDraftEditResult::DraftOccupied;
        }

        self.clear_drag_for_task(task_id);
        if self.editing_task_id.is_some() {
            self.cancel_edit();
        }
        let task = self.tasks.remove(index);
        self.draft = task.text;
        self.draft_attachments = task.attachments;
        self.draft_return_target = Some(SmartInputDraftReturnTarget { index, task_id });
        self.history_nav_reset();
        self.draft_context_menu_selection_range = None;
        self.draft_context_menu_was_open = false;
        SmartInputDraftEditResult::Moved
    }

    fn remove_task(&mut self, task_id: u64) -> Option<String> {
        let index = self.tasks.iter().position(|task| task.id == task_id)?;
        if self.editing_task_id == Some(task_id) {
            self.cancel_edit();
        }
        self.clear_drag_for_task(task_id);
        Some(self.tasks.remove(index).text)
    }

    fn move_task(&mut self, task_id: u64, offset: isize) -> bool {
        let Some(index) = self.tasks.iter().position(|task| task.id == task_id) else {
            return false;
        };
        let next_index = if offset.is_negative() {
            index.saturating_sub(offset.unsigned_abs())
        } else {
            index
                .saturating_add(offset as usize)
                .min(self.tasks.len().saturating_sub(1))
        };
        if next_index == index {
            return false;
        }
        self.tasks.swap(index, next_index);
        true
    }

    fn reorder_task_to_index(&mut self, task_id: u64, target_index: usize) -> bool {
        let current_index = match self.tasks.iter().position(|task| task.id == task_id) {
            Some(i) => i,
            None => return false,
        };
        let target_index = target_index.min(self.tasks.len());
        if current_index == target_index {
            return false;
        }
        let task = self.tasks.remove(current_index);
        let insert_index = if target_index > current_index {
            target_index - 1
        } else {
            target_index
        };
        self.tasks.insert(insert_index, task);
        true
    }

    fn start_edit(&mut self, task_id: u64) -> bool {
        let Some(task) = self.tasks.iter().find(|task| task.id == task_id) else {
            return false;
        };
        let text = task.text.clone();
        let attachments = task.attachments.clone();
        self.clear_drag_for_task(task_id);
        self.editing_task_id = Some(task_id);
        self.edit_draft = text;
        self.edit_attachments = attachments;
        self.edit_context_menu_selection_range = None;
        self.edit_context_menu_was_open = false;
        true
    }

    fn save_edit(&mut self, task_id: u64) -> bool {
        if self.edit_draft.trim().is_empty() && self.edit_attachments.is_empty() {
            return false;
        }
        let Some(task) = self.tasks.iter_mut().find(|task| task.id == task_id) else {
            return false;
        };
        task.text = self.edit_draft.clone();
        task.attachments = std::mem::take(&mut self.edit_attachments);
        self.cancel_edit();
        true
    }

    fn cancel_edit(&mut self) {
        self.editing_task_id = None;
        self.edit_draft.clear();
        self.edit_attachments.clear();
        self.edit_context_menu_selection_range = None;
        self.edit_context_menu_was_open = false;
    }

    fn queue_command_task(&mut self, command: String) {
        let id = self.next_task_id;
        self.next_task_id = self.next_task_id.saturating_add(1).max(1);
        self.tasks.push(SmartInputTask {
            id,
            text: command,
            attachments: Vec::new(),
        });
        self.queue_scroll_to_end = true;
    }

    fn clear_drag_state(&mut self) {
        self.dragging_task_id = None;
        self.drag_hover_index = None;
    }

    fn clear_drag_for_task(&mut self, task_id: u64) {
        if self.dragging_task_id == Some(task_id) {
            self.clear_drag_state();
        }
    }

    /// Navigate up in combined history (newest queued tasks first, then older terminal inputs).
    fn history_navigate_up(
        &mut self,
        recent_inputs: &VecDeque<String>,
        queued_tasks: &[SmartInputTask],
    ) {
        let pool_len = queued_tasks.len() + recent_inputs.len();
        if pool_len == 0 {
            return;
        }
        if self.history_nav_index.is_none() {
            self.history_nav_stash = self.draft.clone();
            self.history_nav_stash_attachments = self.draft_attachments.clone();
            self.history_nav_index = Some(0);
        } else {
            let current = self.history_nav_index.unwrap();
            if current + 1 < pool_len {
                self.history_nav_index = Some(current + 1);
            }
        }
        if let Some(index) = self.history_nav_index {
            let text = if index < queued_tasks.len() {
                // Reverse task order so newest queued task appears first
                let rev_index = queued_tasks.len() - 1 - index;
                queued_tasks.get(rev_index).map(|t| t.text.clone())
            } else {
                recent_inputs
                    .get(index - queued_tasks.len())
                    .map(|t| t.clone())
            };
            if let Some(text) = text {
                self.draft = text;
                self.draft_attachments = if index < queued_tasks.len() {
                    let rev_index = queued_tasks.len() - 1 - index;
                    queued_tasks
                        .get(rev_index)
                        .map(|t| t.attachments.clone())
                        .unwrap_or_default()
                } else {
                    Vec::new()
                };
            }
        }
    }

    /// Navigate down in combined history (newer entries).
    /// When moving past the newest entry, restore the original stash.
    fn history_navigate_down(
        &mut self,
        recent_inputs: &VecDeque<String>,
        queued_tasks: &[SmartInputTask],
    ) {
        let pool_len = queued_tasks.len() + recent_inputs.len();
        if pool_len == 0 {
            return;
        }
        let Some(current) = self.history_nav_index else {
            return;
        };
        if current == 0 {
            self.draft = self.history_nav_stash.clone();
            self.draft_attachments = std::mem::take(&mut self.history_nav_stash_attachments);
            self.history_nav_index = None;
        } else {
            let new_index = current - 1;
            self.history_nav_index = Some(new_index);
            let text = if new_index < queued_tasks.len() {
                // Reverse task order so newest queued task appears first
                let rev_index = queued_tasks.len() - 1 - new_index;
                queued_tasks.get(rev_index).map(|t| t.text.clone())
            } else {
                recent_inputs
                    .get(new_index - queued_tasks.len())
                    .map(|t| t.clone())
            };
            if let Some(text) = text {
                self.draft = text;
                self.draft_attachments = if new_index < queued_tasks.len() {
                    let rev_index = queued_tasks.len() - 1 - new_index;
                    queued_tasks
                        .get(rev_index)
                        .map(|t| t.attachments.clone())
                        .unwrap_or_default()
                } else {
                    Vec::new()
                };
            }
        }
    }

    /// Reset history navigation state, preserving current draft.
    fn history_nav_reset(&mut self) {
        self.history_nav_index = None;
        self.history_nav_stash.clear();
        self.history_nav_stash_attachments.clear();
    }
}

