fn browser_video_frame_request_id(project_id: u64, frame_index: u64) -> String {
    format!("{BROWSER_VIDEO_FRAME_REQUEST_PREFIX}:{project_id}:{frame_index}")
}

fn parse_browser_video_frame_request_id(request_id: &str) -> Option<(u64, u64)> {
    let mut parts = request_id.split(':');
    if parts.next()? != BROWSER_VIDEO_FRAME_REQUEST_PREFIX {
        return None;
    }
    let project_id = parts.next()?.parse::<u64>().ok()?;
    let frame_index = parts.next()?.parse::<u64>().ok()?;
    if parts.next().is_some() {
        return None;
    }
    Some((project_id, frame_index))
}

fn browser_tab_title_from_url(url: &str) -> Option<&str> {
    let trimmed = url.trim();
    if trimmed.is_empty() {
        return None;
    }
    if trimmed.starts_with("file://") {
        return trimmed
            .rsplit('/')
            .next()
            .filter(|name| !name.trim().is_empty());
    }
    let without_scheme = trimmed
        .strip_prefix("https://")
        .or_else(|| trimmed.strip_prefix("http://"))
        .unwrap_or(trimmed);
    without_scheme
        .split(['/', '?', '#'])
        .next()
        .filter(|host| !host.trim().is_empty())
}

fn browser_recording_file_url(path: &Path) -> String {
    let mut normalized = path.display().to_string().replace('\\', "/");
    if !normalized.starts_with('/') {
        normalized = format!("/{normalized}");
    }
    format!("file://{}", percent_encode_file_url_path(&normalized))
}

fn browser_tab_close_rect(tab_rect: egui::Rect) -> egui::Rect {
    let size = BROWSER_TAB_CLOSE_SIZE
        .min(tab_rect.width())
        .min(tab_rect.height());
    let top = tab_rect.top() + ((tab_rect.height() - size) / 2.0).max(0.0);
    egui::Rect::from_min_size(
        egui::pos2(tab_rect.right() - BROWSER_TAB_CLOSE_MARGIN - size, top),
        egui::vec2(size, size),
    )
}

fn clamp_rect_to_bounds(rect: egui::Rect, bounds: egui::Rect) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(rect.left().max(bounds.left()), rect.top().max(bounds.top())),
        egui::pos2(
            rect.right().min(bounds.right()),
            rect.bottom().min(bounds.bottom()),
        ),
    )
}

fn browser_tab_close_hover_rect(tab_rect: egui::Rect) -> egui::Rect {
    clamp_rect_to_bounds(
        browser_tab_close_rect(tab_rect).expand(BROWSER_TAB_ACTION_HOVER_EXPANSION),
        tab_rect,
    )
}

fn browser_tab_close_interaction(
    ui: &mut Ui,
    project_id: u64,
    tab_id: u64,
    close_rect: egui::Rect,
) -> egui::Response {
    ui.interact(
        close_rect,
        ui.make_persistent_id(("browser-tab-close", project_id, tab_id)),
        Sense::click(),
    )
    .on_hover_cursor(egui::CursorIcon::PointingHand)
}

fn browser_tab_add_button(ui: &mut Ui, can_add_tab: bool) -> egui::Response {
    let add_button = egui::Button::new(RichText::new(format!("{}", icons::PLUS)).size(14.0).color(
        if can_add_tab {
            TEXT_PRIMARY
        } else {
            TEXT_MUTED
        },
    ))
    .frame(false);

    ui.add_sized(
        [BROWSER_ADD_TAB_BUTTON_WIDTH, BROWSER_TAB_HEIGHT],
        add_button,
    )
}

fn browser_tab_add_hover_rect(add_rect: egui::Rect) -> egui::Rect {
    add_rect
}

fn set_pointing_hand_cursor_on_hover_rect(ctx: &egui::Context, rect: egui::Rect) -> bool {
    let hover_pos = ctx.input(|input| input.pointer.hover_pos());
    if hover_pos.is_some_and(|hover_pos| rect.contains(hover_pos)) {
        ctx.set_cursor_icon(egui::CursorIcon::PointingHand);
        true
    } else {
        false
    }
}

fn browser_tab_label_rect(tab_rect: egui::Rect) -> egui::Rect {
    let close_rect = browser_tab_close_rect(tab_rect);
    egui::Rect::from_min_max(
        egui::pos2(
            tab_rect.left() + BROWSER_TAB_LABEL_LEFT_PADDING,
            tab_rect.top(),
        ),
        egui::pos2(
            (close_rect.left() - BROWSER_TAB_LABEL_RIGHT_GAP)
                .max(tab_rect.left() + BROWSER_TAB_LABEL_LEFT_PADDING),
            tab_rect.bottom(),
        ),
    )
}

fn window_close_button_hover_rect(window_rect: egui::Rect, style: &egui::Style) -> egui::Rect {
    let margin = style.spacing.window_margin;
    let heading_height = style
        .text_styles
        .get(&egui::TextStyle::Heading)
        .map(|font_id| font_id.size)
        .unwrap_or(style.spacing.interact_size.y);
    let title_bar_height = (heading_height + margin.top + margin.bottom).max(CONTROL_ROW_HEIGHT);
    let hover_width =
        (margin.right + style.spacing.icon_width + style.spacing.item_spacing.x * 2.0)
            .max(CONTROL_ROW_HEIGHT);

    egui::Rect::from_min_max(
        egui::pos2(
            (window_rect.right() - hover_width).max(window_rect.left()),
            window_rect.top(),
        ),
        egui::pos2(
            window_rect.right(),
            (window_rect.top() + title_bar_height).min(window_rect.bottom()),
        ),
    )
}

fn set_window_close_cursor_on_hover(ctx: &egui::Context, window_rect: egui::Rect) {
    let style = ctx.style();
    let close_rect = window_close_button_hover_rect(window_rect, &style);
    set_pointing_hand_cursor_on_hover_rect(ctx, close_rect);
}

fn percent_encode_file_url_path(value: &str) -> String {
    let mut encoded = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' | b'/' | b':' => {
                encoded.push(byte as char)
            }
            _ => encoded.push_str(&format!("%{byte:02X}")),
        }
    }
    encoded
}

/// Key for scoping browser instances - either project-wide or terminal-specific.
/// Terminal-scoped browsers provide isolation between multiple MCP sessions in the same project.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
enum BrowserScopeKey {
    /// Project-scoped browser (legacy behavior) - shared across all terminals in the project.
    Project(u64),
    /// Terminal-scoped browser - isolated instance for a specific terminal.
    Terminal { project_id: u64, terminal_id: u64 },
}

impl BrowserScopeKey {
    /// Returns the project_id associated with this scope.
    fn project_id(&self) -> u64 {
        match self {
            BrowserScopeKey::Project(pid) => *pid,
            BrowserScopeKey::Terminal { project_id, .. } => *project_id,
        }
    }

    /// Returns the terminal_id if this is a terminal scope, None otherwise.
    fn terminal_id(&self) -> Option<u64> {
        match self {
            BrowserScopeKey::Project(_) => None,
            BrowserScopeKey::Terminal { terminal_id, .. } => Some(*terminal_id),
        }
    }

    /// Returns true if this is a terminal-scoped key.
    fn is_terminal(&self) -> bool {
        matches!(self, BrowserScopeKey::Terminal { .. })
    }
}

impl From<u64> for BrowserScopeKey {
    fn from(project_id: u64) -> Self {
        BrowserScopeKey::Project(project_id)
    }
}

