/// Represents a single open file buffer in the built-in editor.
#[derive(Debug, Clone)]
struct OpenFileBuffer {
    /// Which project this file belongs to
    project_id: u64,
    /// Full path to the file
    path: PathBuf,
    /// Display name for UI
    display_name: String,
    /// Current text content
    text: String,
    /// Last saved text content (for dirty detection)
    saved_text: String,
    /// Whether the buffer has unsaved changes
    dirty: bool,
    /// Last modified time when loaded (for conflict detection)
    loaded_modified_at: Option<SystemTime>,
    /// Error message if file operations fail
    last_error: Option<String>,
}

impl OpenFileBuffer {
    fn new(project_id: u64, path: PathBuf, text: String, display_name: String) -> Self {
        Self {
            project_id,
            path,
            display_name,
            saved_text: text.clone(),
            text,
            dirty: false,
            loaded_modified_at: None,
            last_error: None,
        }
    }

    fn is_dirty(&self) -> bool {
        self.dirty || self.text != self.saved_text
    }

    fn mark_saved(&mut self) {
        self.saved_text = self.text.clone();
        self.dirty = false;
    }
}

/// State for the built-in file editor.
/// Manages the active file and navigation history.
#[derive(Debug, Clone)]
struct FileEditorState {
    /// Currently active file buffer
    active: Option<OpenFileBuffer>,
    /// Back stack for navigation (previously opened files)
    back_stack: Vec<OpenFileBuffer>,
    /// Forward stack for navigation (files navigated back from)
    forward_stack: Vec<OpenFileBuffer>,
    /// Maximum number of sessions to keep in history
    max_history: usize,
    /// Whether text selection drag is currently active (for edge autoscroll).
    /// Runtime-only state; not persisted across sessions.
    selection_drag_active: bool,
    /// Stored selection range for context menu (preserved before right-click collapses it).
    /// Runtime-only state; not persisted across sessions.
    context_menu_selection_range: Option<egui::text::CCursorRange>,
    /// Tracks whether context menu was open in previous frame (for detecting close transition).
    /// Runtime-only state; not persisted across sessions.
    context_menu_was_open: bool,
    /// Whether the editor is currently visible in the main area.
    /// When false, the editor is hidden but the active buffer is preserved.
    visible: bool,
}

impl Default for FileEditorState {
    fn default() -> Self {
        Self {
            active: None,
            back_stack: Vec::new(),
            forward_stack: Vec::new(),
            max_history: 20,
            selection_drag_active: false,
            context_menu_selection_range: None,
            context_menu_was_open: false,
            visible: false,
        }
    }
}

impl FileEditorState {
    /// Open a new file, pushing current to back stack if present.
    /// The editor becomes visible when a file is opened.
    fn open_file(&mut self, buffer: OpenFileBuffer) {
        // Clear forward stack when opening a new file
        self.forward_stack.clear();

        // Push current active to back stack if exists
        if let Some(current) = self.active.take() {
            self.push_to_back_stack(current);
        }

        // Set new buffer as active and make visible
        self.active = Some(buffer);
        self.visible = true;

        // Reset selection drag state when opening a new file
        self.selection_drag_active = false;
        // Clear any stored context menu selection from previous file
        self.context_menu_selection_range = None;
        self.context_menu_was_open = false;
    }

    /// Navigate back to previous file.
    fn navigate_back(&mut self) -> bool {
        if let Some(previous) = self.back_stack.pop() {
            // Push current to forward stack
            if let Some(current) = self.active.take() {
                self.push_to_forward_stack(current);
            }
            self.active = Some(previous);

            // Reset selection drag state when navigating
            self.selection_drag_active = false;
            // Clear stored context menu selection when navigating
            self.context_menu_selection_range = None;
            self.context_menu_was_open = false;
            true
        } else {
            false
        }
    }

    /// Navigate forward to next file.
    fn navigate_forward(&mut self) -> bool {
        if let Some(next) = self.forward_stack.pop() {
            // Push current to back stack
            if let Some(current) = self.active.take() {
                self.push_to_back_stack(current);
            }
            self.active = Some(next);

            // Reset selection drag state when navigating
            self.selection_drag_active = false;
            // Clear stored context menu selection when navigating
            self.context_menu_selection_range = None;
            self.context_menu_was_open = false;
            true
        } else {
            false
        }
    }

    /// Close the editor, clearing all state.
    fn close(&mut self) {
        self.active = None;
        self.back_stack.clear();
        self.forward_stack.clear();
        self.selection_drag_active = false;
        self.context_menu_selection_range = None;
        self.context_menu_was_open = false;
        self.visible = false;
    }

    /// Hide the editor (preserves active buffer for later restore).
    /// The file remains open but the editor is not shown in the main area.
    fn hide(&mut self) {
        self.visible = false;
        self.selection_drag_active = false;
        // Clear stored context menu selection when hiding editor
        self.context_menu_selection_range = None;
        self.context_menu_was_open = false;
    }

    /// Check if editor has an active file.
    fn is_open(&self) -> bool {
        self.active.is_some()
    }

    /// Check if editor is currently visible in the main area.
    fn is_visible(&self) -> bool {
        self.visible && self.active.is_some()
    }

    /// Check if there are files in back stack.
    fn can_go_back(&self) -> bool {
        !self.back_stack.is_empty()
    }

    /// Check if there are files in forward stack.
    fn can_go_forward(&self) -> bool {
        !self.forward_stack.is_empty()
    }

    fn push_to_back_stack(&mut self, buffer: OpenFileBuffer) {
        if self.back_stack.len() >= self.max_history {
            self.back_stack.remove(0);
        }
        self.back_stack.push(buffer);
    }

    fn push_to_forward_stack(&mut self, buffer: OpenFileBuffer) {
        if self.forward_stack.len() >= self.max_history {
            self.forward_stack.remove(0);
        }
        self.forward_stack.push(buffer);
    }
}

/// Pure helper to compute file editor selection drag state after handling input events.
/// Returns the new drag active state based on current state and input events.
fn file_editor_selection_drag_active_after_input(
    was_active: bool,
    primary_down: bool,
    drag_started: bool,
    dragged: bool,
    drag_stopped: bool,
) -> bool {
    if drag_stopped || !primary_down {
        false
    } else {
        was_active || drag_started || dragged
    }
}

/// Returns true if the given CCursorRange represents a non-empty selection.
fn file_editor_ccursor_range_has_selection(range: egui::text::CCursorRange) -> bool {
    range.primary != range.secondary
}

/// Detects if a copy action was requested for the file editor.
/// Checks for either egui's Event::Copy or Ctrl+C/Command+C key combination.
/// This is necessary because egui::TextEdit may consume the copy shortcut
/// and emit Event::Copy rather than letting the raw key event through.
fn file_editor_copy_requested(input: &egui::InputState) -> bool {
    // First check for the explicit Event::Copy (generated by TextEdit when it handles Ctrl+C)
    for event in input.events.iter() {
        if matches!(event, egui::Event::Copy) {
            return true;
        }
    }

    // Fallback: check for raw Ctrl+C / Command+C key press
    // This handles cases where TextEdit doesn't consume the event
    input.key_pressed(egui::Key::C) && (input.modifiers.ctrl || input.modifiers.command)
}

/// Extracts selected text from a CCursorRange using character indices.
/// Returns None if the range is empty or the selection produces no text.
fn selected_file_editor_text_from_char_range(
    text: &str,
    range: Option<egui::text::CCursorRange>,
) -> Option<String> {
    let range = range?;
    let [start, end] = range.sorted();

    if start.index >= end.index {
        return None;
    }

    let selected: String = text
        .chars()
        .enumerate()
        .take_while(|(index, _)| *index < end.index)
        .filter_map(|(index, ch)| (index >= start.index).then_some(ch))
        .collect();

    (!selected.is_empty()).then_some(selected)
}

/// Extracts text from a CCursorRange using character indices.
/// General-purpose variant for non-file-editor uses (e.g., browser URL input).
/// Returns None if the range is empty or produces no text.
fn extract_text_from_char_range(
    text: &str,
    range: Option<egui::text::CCursorRange>,
) -> Option<String> {
    let range = range?;
    let [start, end] = range.sorted();

    if start.index >= end.index {
        return None;
    }

    let extracted: String = text
        .chars()
        .enumerate()
        .take_while(|(index, _)| *index < end.index)
        .filter_map(|(index, ch)| (index >= start.index).then_some(ch))
        .collect();

    (!extracted.is_empty()).then_some(extracted)
}

fn replace_text_range_or_append(
    text: &mut String,
    range: Option<egui::text::CCursorRange>,
    replacement: &str,
) {
    let Some(range) = range else {
        text.push_str(replacement);
        return;
    };
    let [start, end] = range.sorted();
    if start.index >= end.index {
        text.push_str(replacement);
        return;
    }

    let mut new_text = String::new();
    let mut chars = text.chars();
    for _ in 0..start.index {
        if let Some(ch) = chars.next() {
            new_text.push(ch);
        }
    }
    for _ in start.index..end.index {
        chars.next();
    }
    new_text.push_str(replacement);
    for ch in chars {
        new_text.push(ch);
    }
    *text = new_text;
}

/// Determines the effective context menu selection range for the file editor.
/// Preserves the pre-click selection when secondary-click would collapse it.
fn file_editor_context_menu_selection_range(
    secondary_clicked: bool,
    pre_click_range: Option<egui::text::CCursorRange>,
    post_show_range: Option<egui::text::CCursorRange>,
) -> Option<egui::text::CCursorRange> {
    if secondary_clicked && pre_click_range.is_some_and(file_editor_ccursor_range_has_selection) {
        pre_click_range
    } else {
        post_show_range.filter(|range| file_editor_ccursor_range_has_selection(*range))
    }
}

