struct AiBadgeModel {
    tool: Option<AiCliTool>,
    status: AiCliStatus,
    /// Normalized Codex transport status for semantic UI differentiation
    codex_normalized_status: Option<CodexTransportStatus>,
    /// Normalized OpenCode transport status for semantic UI differentiation
    opencode_normalized_status: Option<OpenCodeTransportStatus>,
    /// Normalized Claude transport status for semantic UI differentiation
    claude_normalized_status: Option<ClaudeTransportStatus>,
    /// Pending attention flag for pulse/unread semantics (Orca-compatible)
    /// True when user needs to acknowledge attention (shown as pulse)
    codex_attention_pending: bool,
    /// Codex attention reason for badge visibility decisions
    codex_attention_reason: Option<CodexAttentionReason>,
    /// Pending attention flag for pulse/unread semantics (Orca-compatible)
    /// True when user needs to acknowledge attention (shown as pulse)
    opencode_attention_pending: bool,
    /// OpenCode attention reason for badge visibility decisions
    /// Used to hide badge for TurnComplete after acknowledge, keep for interactive reasons
    opencode_attention_reason: Option<OpenCodeAttentionReason>,
    tooltip_lines: Vec<String>,
}

impl AiBadgeModel {
    fn from_terminal(terminal: &TerminalEntry) -> Self {
        let tool = terminal.ai_session.tool;
        let status = terminal.ai_session.status;
        let tooltip_lines = ai_badge_tooltip_lines(
            tool,
            status,
            terminal.factory_droid_attention_reason,
            terminal.codex_attention_reason,
            terminal.opencode_attention_reason,
            terminal.claude_attention_reason,
        );
        Self {
            tool,
            status,
            codex_normalized_status: terminal.codex_normalized_status,
            opencode_normalized_status: terminal.opencode_normalized_status,
            claude_normalized_status: terminal.claude_normalized_status,
            codex_attention_pending: terminal.codex_attention_pending,
            codex_attention_reason: terminal.codex_attention_reason,
            opencode_attention_pending: terminal.opencode_attention_pending,
            opencode_attention_reason: terminal.opencode_attention_reason,
            tooltip_lines,
        }
    }
}

fn ai_badge_tooltip_lines(
    tool: Option<AiCliTool>,
    status: AiCliStatus,
    factory_droid_attention_reason: Option<FactoryDroidAttentionReason>,
    codex_attention_reason: Option<CodexAttentionReason>,
    opencode_attention_reason: Option<OpenCodeAttentionReason>,
    claude_attention_reason: Option<ClaudeAttentionReason>,
) -> Vec<String> {
    match tool {
        Some(AiCliTool::FactoryDroid) if status == AiCliStatus::Attention => {
            vec![factory_droid_attention_reason
                .map(|reason| reason.tooltip().to_owned())
                .unwrap_or_else(|| status.tooltip(AiCliTool::FactoryDroid))]
        }
        Some(AiCliTool::CodexCli) if status == AiCliStatus::Attention => {
            vec![codex_attention_reason
                .unwrap_or(CodexAttentionReason::UnknownNotify)
                .tooltip()
                .to_owned()]
        }
        Some(AiCliTool::OpenCode) if status == AiCliStatus::Attention => {
            vec![opencode_attention_reason
                .map(|reason| reason.tooltip().to_owned())
                .unwrap_or_else(|| status.tooltip(AiCliTool::OpenCode))]
        }
        Some(AiCliTool::Claude) if status == AiCliStatus::Attention => {
            vec![claude_attention_reason
                .map(|reason| reason.tooltip().to_owned())
                .unwrap_or_else(|| status.tooltip(AiCliTool::Claude))]
        }
        Some(tool) => vec![status.tooltip(tool)],
        None => vec!["AI: Not detected".to_owned()],
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AiBadgeVisual {
    Spinner(Color32),
    Pulse(Color32),
    Solid(Color32),
}

/// Determines badge visual based on status and semantic context
/// Orca-compatible mapping:
/// - Working -> Spinner (active work in progress)
/// - Permission/Question + pending -> Pulse (requires user interaction)
/// - Permission/Question + acknowledged -> Solid dot (calm state)
/// - Idle/TurnComplete + pending -> Pulse (turn complete notification)
/// - Idle/TurnComplete + pending -> Green pulse (turn complete notification)
/// - Idle/TurnComplete + acknowledged -> Hidden (turn complete done)
/// - Idle/PermissionAsked|QuestionAsked + acknowledged -> Amber solid (still needs action)
fn ai_badge_visual(
    status: AiCliStatus,
    codex_normalized_status: Option<CodexTransportStatus>,
    opencode_normalized_status: Option<OpenCodeTransportStatus>,
    claude_normalized_status: Option<ClaudeTransportStatus>,
    codex_attention_pending: bool,
    codex_attention_reason: Option<CodexAttentionReason>,
    opencode_attention_pending: bool,
    opencode_attention_reason: Option<OpenCodeAttentionReason>,
) -> Option<AiBadgeVisual> {
    match status {
        AiCliStatus::Inactive => None,
        AiCliStatus::Running => Some(AiBadgeVisual::Spinner(Color32::from_rgb(170, 170, 170))),
        AiCliStatus::Attention => {
            // Check Codex first - if it has normalized status, use Codex rules
            if let Some(codex_status) = codex_normalized_status {
                return match codex_status {
                    CodexTransportStatus::Working => {
                        Some(AiBadgeVisual::Spinner(Color32::from_rgb(170, 170, 170)))
                    }
                    CodexTransportStatus::Permission => {
                        // Permission: pulse if pending, solid if acknowledged
                        if codex_attention_pending {
                            Some(AiBadgeVisual::Pulse(Color32::from_rgb(210, 170, 80)))
                        } else {
                            Some(AiBadgeVisual::Solid(Color32::from_rgb(210, 170, 80)))
                        }
                    }
                    CodexTransportStatus::Idle => {
                        // Idle: pulse if pending, hidden if acknowledged
                        if codex_attention_pending {
                            Some(AiBadgeVisual::Pulse(Color32::from_rgb(90, 185, 90)))
                        } else if codex_attention_reason == Some(CodexAttentionReason::TurnComplete)
                        {
                            None
                        } else {
                            Some(AiBadgeVisual::Solid(Color32::from_rgb(90, 185, 90)))
                        }
                    }
                };
            }

            // Then check Claude
            if let Some(claude_status) = claude_normalized_status {
                return match claude_status {
                    ClaudeTransportStatus::Working => {
                        Some(AiBadgeVisual::Spinner(Color32::from_rgb(170, 170, 170)))
                    }
                    ClaudeTransportStatus::Permission => {
                        if codex_attention_pending {
                            Some(AiBadgeVisual::Pulse(Color32::from_rgb(210, 170, 80)))
                        } else {
                            Some(AiBadgeVisual::Solid(Color32::from_rgb(210, 170, 80)))
                        }
                    }
                    ClaudeTransportStatus::Idle => {
                        if codex_attention_pending {
                            Some(AiBadgeVisual::Pulse(Color32::from_rgb(90, 185, 90)))
                        } else {
                            Some(AiBadgeVisual::Solid(Color32::from_rgb(90, 185, 90)))
                        }
                    }
                };
            }

            // Fall back to OpenCode status
            match opencode_normalized_status {
                Some(OpenCodeTransportStatus::Permission) => {
                    // Permission/Question: pulse if pending, solid if acknowledged
                    if opencode_attention_pending {
                        Some(AiBadgeVisual::Pulse(Color32::from_rgb(210, 170, 80)))
                        // Amber pulse
                    } else {
                        Some(AiBadgeVisual::Solid(Color32::from_rgb(210, 170, 80)))
                        // Amber solid (acknowledged)
                    }
                }
                Some(OpenCodeTransportStatus::Idle) => {
                    // Idle/TurnComplete: pulse if pending, hidden if acknowledged
                    if opencode_attention_pending {
                        Some(AiBadgeVisual::Pulse(Color32::from_rgb(90, 185, 90)))
                        // Green pulse (turn complete notification)
                    } else {
                        // Hide badge for TurnComplete after acknowledge
                        // Keep badge for other Idle reasons (SessionError etc)
                        if opencode_attention_reason == Some(OpenCodeAttentionReason::TurnComplete)
                        {
                            None // Turn complete acknowledged - badge hidden
                        } else {
                            Some(AiBadgeVisual::Solid(Color32::from_rgb(90, 185, 90)))
                            // Green solid (non-TurnComplete Idle states)
                        }
                    }
                }
                Some(OpenCodeTransportStatus::Working) => {
                    // Shouldn't be attention + working, but handle gracefully
                    Some(AiBadgeVisual::Spinner(Color32::from_rgb(170, 170, 170)))
                }
                None => {
                    // No normalized status - use pending flag to decide
                    if codex_attention_pending || opencode_attention_pending {
                        Some(AiBadgeVisual::Pulse(Color32::from_rgb(200, 200, 200)))
                    } else {
                        Some(AiBadgeVisual::Solid(Color32::from_rgb(170, 170, 170)))
                    }
                }
            }
        }
    }
}

/// Returns the launcher icon key for a running AI CLI tool.
/// Only returns Some when the tool is in Running state (to show the logo at title start).
#[cfg(test)]
fn launcher_icon_for_ai_tool(
    tool: Option<AiCliTool>,
    status: AiCliStatus,
) -> Option<LauncherIconKey> {
    if status != AiCliStatus::Running {
        return None;
    }
    match tool {
        Some(AiCliTool::FactoryDroid) => Some(LauncherIconKey::Droid),
        Some(AiCliTool::CodexCli) => Some(LauncherIconKey::Codex),
        Some(AiCliTool::OpenCode) => Some(LauncherIconKey::OpenCode),
        Some(AiCliTool::Claude) => Some(LauncherIconKey::Claude),
        None => None,
    }
}

/// Returns the launcher icon key for an AI CLI session if it is still "alive".
/// Logo remains visible after the spinner stops (Attention state) as long as the
/// CLI session has not actually exited. It disappears only when the session ends
/// (e.g., after clear_*_process_tracking or clear_*_state).
fn ai_cli_logo_key_for_terminal(entry: &TerminalEntry) -> Option<LauncherIconKey> {
    // Map tool to icon key, but only show if session appears live per tool-specific tracking.
    match entry.ai_session.tool {
        Some(AiCliTool::FactoryDroid) => {
            // Session is live if: launch pending, session active, or process missing but not yet cleared.
            let is_live = entry.factory_droid_launch_pending_since.is_some()
                || entry.factory_droid_session_active
                || entry.factory_droid_process_missing_since.is_some();
            if is_live {
                Some(LauncherIconKey::Droid)
            } else {
                None
            }
        }
        Some(AiCliTool::CodexCli) => {
            // Session is live if: launch pending, session active, process present, or process missing but not yet cleared.
            let is_live = entry.codex_launch_pending_since.is_some()
                || entry.codex_session_active
                || entry.codex_process_identity.is_some()
                || entry.codex_process_missing_since.is_some();
            if is_live {
                Some(LauncherIconKey::Codex)
            } else {
                None
            }
        }
        Some(AiCliTool::OpenCode) => {
            // Session is live if: launch pending, session active, process present, or process missing but not yet cleared.
            let is_live = entry.opencode_launch_pending_since.is_some()
                || entry.opencode_session_active
                || entry.opencode_process_identity.is_some()
                || entry.opencode_process_missing_since.is_some();
            if is_live {
                Some(LauncherIconKey::OpenCode)
            } else {
                None
            }
        }
        Some(AiCliTool::Claude) => {
            // Session is live if: launch pending, session active, or any normalized status present.
            // This keeps the logo visible even after user acknowledges attention (status becomes Inactive).
            let is_live = entry.claude_launch_pending_since.is_some()
                || entry.claude_session_active
                || entry.claude_normalized_status.is_some();
            if is_live {
                Some(LauncherIconKey::Claude)
            } else {
                None
            }
        }
        None => None,
    }
}

fn draw_ai_badge(ui: &mut Ui, badge: &AiBadgeModel) -> egui::Response {
    let Some(visual) = ai_badge_visual(
        badge.status,
        badge.codex_normalized_status,
        badge.opencode_normalized_status,
        badge.claude_normalized_status,
        badge.codex_attention_pending,
        badge.codex_attention_reason,
        badge.opencode_attention_pending,
        badge.opencode_attention_reason,
    ) else {
        return ui.allocate_at_least(egui::vec2(0.0, 0.0), Sense::hover()).1;
    };

    let (rect, response) = ui.allocate_at_least(egui::vec2(16.0, 16.0), Sense::hover());

    if ui.is_rect_visible(rect) {
        // Spinner/pulse için 16x16 alan (solda)
        let spinner_rect = egui::Rect::from_min_size(rect.min, egui::vec2(16.0, 16.0));
        match visual {
            AiBadgeVisual::Spinner(color) => {
                ui.put(spinner_rect, egui::Spinner::new().color(color).size(14.0));
            }
            AiBadgeVisual::Pulse(color) => {
                let time_seconds = ui.ctx().input(|i| i.time);
                let center = spinner_rect.center();

                // Pulse animasyonu (büyüyüp küçülen daire)
                let pulse = ((time_seconds * 4.0).sin() + 1.0) * 0.25 + 2.5; // 2.5 - 5 arası yarıçap
                let radius = pulse as f32;
                let alpha = ((time_seconds * 4.0).sin() * 0.3 + 0.7) * 255.0;
                let color =
                    Color32::from_rgba_unmultiplied(color.r(), color.g(), color.b(), alpha as u8);

                ui.painter().circle(
                    center,
                    radius,
                    color,
                    egui::Stroke::new(0.0, Color32::TRANSPARENT),
                );

                ui.ctx().request_repaint_after(Duration::from_millis(250));
            }
            AiBadgeVisual::Solid(color) => {
                let center = spinner_rect.center();
                // Solid dot with fixed radius - no animation
                ui.painter().circle(
                    center,
                    3.5, // Fixed radius for solid dot
                    color,
                    egui::Stroke::new(0.0, Color32::TRANSPARENT),
                );
            }
        }
    }

    response.on_hover_ui(|ui| {
        for line in &badge.tooltip_lines {
            ui.label(line);
        }
    })
}

