#[derive(Debug, Clone)]
struct DirectoryNode {
    name: String,
    path: PathBuf,
    is_dir: bool,
    is_placeholder: bool,
    /// True if this directory was deferred during fast indexing and should be loaded on demand.
    is_deferred: bool,
    children: Vec<DirectoryNode>,
}

/// Snapshot flags for why the directory index was truncated or partial.
#[derive(Debug, Clone, Default)]
struct DirectoryIndexTruncationFlags {
    node_limit: bool,
    depth_limit: bool,
    time_budget: bool,
    deferred_directories: bool,
}

#[derive(Debug, Clone)]
struct DirectoryIndexSnapshot {
    root: DirectoryNode,
    loading: bool,
    last_error: Option<String>,
    partial_warning: Option<String>,
    truncation: DirectoryIndexTruncationFlags,
}

/// Directory index event for full or subtree results.
#[derive(Debug, Clone)]
enum DirectoryIndexEvent {
    /// Full project index result.
    Full {
        project_id: u64,
        generation: u64,
        snapshot: DirectoryIndexSnapshot,
    },
    /// Subtree result for a specific deferred directory.
    Subtree {
        project_id: u64,
        generation: u64,
        target_path: PathBuf,
        children: Vec<DirectoryNode>,
        last_error: Option<String>,
        partial_warning: Option<String>,
        truncation: DirectoryIndexTruncationFlags,
    },
}

/// Visible paths in a directory search result set.
/// Captures the current snapshot-derived view for rendering.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct DirectorySearchVisiblePaths {
    directories: BTreeSet<PathBuf>,
    files: BTreeSet<PathBuf>,
    /// Directories whose own names match the query (allowed to auto-hydrate descendants).
    self_matching_directories: BTreeSet<PathBuf>,
}

impl DirectorySearchVisiblePaths {
    fn has_results(&self) -> bool {
        !self.directories.is_empty() || !self.files.is_empty()
    }
}

