fn draw_source_control_file_row(ui: &mut Ui, status_icon: AppIcon, text: &str) -> egui::Response {
    let button_padding = ui.spacing().button_padding;
    let available_width = ui.available_width().max(0.0);
    let wrap_width = (sidebar_row_wrap_width(available_width, button_padding)
        - SOURCE_CONTROL_FILE_ICON_WIDTH
        - SOURCE_CONTROL_FILE_ICON_GAP)
        .max(0.0);
    let galley = WidgetText::from(RichText::new(text).monospace().small()).into_galley(
        ui,
        Some(TextWrapMode::Truncate),
        wrap_width,
        egui::TextStyle::Small,
    );
    let desired_height = sidebar_row_desired_height(ui, galley.size().y, button_padding);
    let desired_size = egui::vec2(available_width, desired_height);
    let (rect, response) = ui.allocate_exact_size(desired_size, Sense::click());

    if ui.is_rect_visible(rect) {
        if let Some(fill) = directory_file_row_hover_fill(
            response.hovered() || response.highlighted() || response.has_focus(),
        ) {
            ui.painter()
                .rect_filled(rect.shrink2(egui::vec2(1.0, 1.0)), 8.0, fill);
        }

        let content_rect = sidebar_row_content_rect(rect, button_padding);
        let icon_rect = egui::Rect::from_min_size(
            content_rect.min,
            egui::vec2(
                SOURCE_CONTROL_FILE_ICON_WIDTH.min(content_rect.width()),
                content_rect.height(),
            ),
        );
        ui.painter().text(
            icon_rect.center(),
            egui::Align2::CENTER_CENTER,
            status_icon.to_string(),
            egui::FontId::proportional(12.0),
            TEXT_MUTED,
        );

        let text_rect = egui::Rect::from_min_max(
            egui::pos2(
                (icon_rect.max.x + SOURCE_CONTROL_FILE_ICON_GAP).min(content_rect.max.x),
                content_rect.min.y,
            ),
            content_rect.max,
        );
        let text_pos = egui::pos2(
            text_rect.min.x,
            content_rect.center().y - (galley.size().y * 0.5),
        );
        ui.painter()
            .galley(text_pos, galley, ui.visuals().text_color());
    }

    let font_id = egui::TextStyle::Small.resolve(ui.style());
    with_truncation_tooltip(
        ui,
        response,
        text,
        &font_id,
        ui.visuals().text_color(),
        wrap_width,
    )
}

fn draw_source_control_worktree_row(
    ui: &mut Ui,
    label: &str,
    is_current: bool,
    tooltip: &str,
) -> egui::Response {
    let button_padding = ui.spacing().button_padding;
    let available_width = ui.available_width().max(0.0);
    let icon_width = SOURCE_CONTROL_FILE_ICON_WIDTH;
    let icon_gap = SOURCE_CONTROL_FILE_ICON_GAP;
    let wrap_width =
        (sidebar_row_wrap_width(available_width, button_padding) - icon_width - icon_gap).max(0.0);

    let text = label.to_owned();
    let galley = WidgetText::from(RichText::new(&text)).into_galley(
        ui,
        Some(TextWrapMode::Truncate),
        wrap_width,
        egui::TextStyle::Body,
    );
    let desired_height = sidebar_row_desired_height(ui, galley.size().y, button_padding);
    let desired_size = egui::vec2(available_width, desired_height);
    let (rect, response) = ui.allocate_exact_size(desired_size, Sense::click());

    if ui.is_rect_visible(rect) {
        if let Some(fill) = directory_file_row_hover_fill(
            response.hovered() || response.highlighted() || response.has_focus(),
        ) {
            ui.painter()
                .rect_filled(rect.shrink2(egui::vec2(1.0, 1.0)), 8.0, fill);
        }

        let content_rect = sidebar_row_content_rect(rect, button_padding);
        let icon_rect = egui::Rect::from_min_size(
            content_rect.min,
            egui::vec2(icon_width.min(content_rect.width()), content_rect.height()),
        );
        ui.painter().text(
            icon_rect.center(),
            egui::Align2::CENTER_CENTER,
            icons::GIT_BRANCH.to_string(),
            egui::FontId::proportional(10.0),
            TEXT_MUTED,
        );

        let text_rect = egui::Rect::from_min_max(
            egui::pos2(
                (icon_rect.max.x + icon_gap).min(content_rect.max.x),
                content_rect.min.y,
            ),
            content_rect.max,
        );
        let text_pos = egui::pos2(
            text_rect.min.x,
            content_rect.center().y - (galley.size().y * 0.5),
        );
        let text_color = if is_current { ACCENT } else { TEXT_PRIMARY };
        ui.painter().galley(text_pos, galley, text_color);
    }

    let font_id = egui::TextStyle::Body.resolve(ui.style());
    with_truncation_tooltip(ui, response, tooltip, &font_id, TEXT_PRIMARY, wrap_width)
}

/// Draw a worktree row inside the Terminal Manager under its parent project (BOM-style tree).
/// `action_kind` determines whether the row shows a foreground launcher menu or a background
/// spawn button, matching the active Terminal Manager filter.
fn worktree_row_text_color(is_selected: bool, has_live_terminal: bool) -> Color32 {
    if is_selected && has_live_terminal {
        TEXT_PRIMARY
    } else {
        with_alpha(ACCENT, 200)
    }
}

fn draw_terminal_manager_worktree_row(
    app: &mut AdeApp,
    ui: &mut Ui,
    label: &str,
    is_selected: bool,
    has_live_terminal: bool,
    tooltip: &str,
    foreground_launchers: &[LauncherEntry],
    action_kind: TerminalKind,
    diff_summary: &TerminalManagerDiffSummaryModel,
) -> (egui::Response, bool, Option<String>) {
    let button_padding = ui.spacing().button_padding;
    let available_width = ui.available_width().max(0.0);
    let actions_width = CONTROL_ROW_HEIGHT;
    let section_gap = ui.spacing().item_spacing.x;
    let label_width = (available_width - actions_width - section_gap).max(0.0);
    let wrap_width = sidebar_row_wrap_width(label_width, button_padding).max(0.0);

    let text = label.to_string();
    let galley = WidgetText::from(RichText::new(&text)).into_galley(
        ui,
        Some(TextWrapMode::Truncate),
        wrap_width,
        egui::TextStyle::Body,
    );
    let text_color = worktree_row_text_color(is_selected, has_live_terminal);
    let desired_height = sidebar_row_desired_height(ui, galley.size().y, button_padding);
    let desired_size = egui::vec2(available_width, desired_height);
    let (rect, _response) = ui.allocate_exact_size(desired_size, Sense::hover());

    // Separate body and action interaction areas
    let body_rect = egui::Rect::from_min_size(rect.min, egui::vec2(label_width, rect.height()));
    let actions_rect = egui::Rect::from_min_size(
        egui::pos2(rect.right() - actions_width, rect.top()),
        egui::vec2(actions_width, rect.height()),
    );

    let body_response = ui.interact(
        body_rect,
        ui.id().with(("worktree_row_body", label)),
        Sense::click(),
    );
    let body_response = body_response.on_hover_cursor(egui::CursorIcon::PointingHand);

    let mut spawn_clicked = false;
    let mut selected_launcher_id = None;

    if ui.is_rect_visible(rect) {
        if body_response.hovered() || body_response.highlighted() || body_response.has_focus() {
            if let Some(fill_color) = directory_file_row_hover_fill(true) {
                ui.painter()
                    .rect_filled(rect.shrink2(egui::vec2(1.0, 1.0)), 8.0, fill_color);
            }
        }

        // Draw title + diff summary like root project header
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(body_rect)
                .layout(Layout::left_to_right(Align::Center)),
            |ui| {
                let _ = draw_terminal_manager_title_and_diff_summary(
                    ui,
                    label,
                    text_color,
                    false,
                    rect.height(),
                    diff_summary,
                    true,
                    Some(tooltip),
                );
            },
        );

        // Action button on the right
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(actions_rect)
                .layout(Layout::centered_and_justified(egui::Direction::LeftToRight)),
            |ui| {
                if action_kind == TerminalKind::Foreground {
                    selected_launcher_id = styled_launcher_menu_button(
                        app,
                        ui,
                        icons::TERMINAL,
                        BTN_BLUE,
                        BTN_BLUE_HOVER,
                        BTN_ICON_ACTIVE,
                        "Open Foreground Launcher",
                        foreground_launchers,
                    );
                } else {
                    let (icon, bg, hover_bg, tooltip) =
                        project_group_header_action_spec(TerminalKind::Background);
                    if styled_icon_button(ui, icon, bg, hover_bg, BTN_ICON_ACTIVE, tooltip) {
                        spawn_clicked = true;
                    }
                }
            },
        );
    }

    let font_id = egui::TextStyle::Body.resolve(ui.style());
    let response = with_truncation_tooltip(
        ui,
        body_response,
        tooltip,
        &font_id,
        TEXT_PRIMARY,
        wrap_width,
    );
    (response, spawn_clicked, selected_launcher_id)
}

fn directory_file_row_hover_fill(is_hovered: bool) -> Option<Color32> {
    is_hovered.then(|| with_alpha(BTN_ICON_HOVER, 110))
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct TerminalHeaderChrome {
    fill: Color32,
    stroke: Stroke,
    title_color: Color32,
    detail_color: Color32,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct TerminalManagerRowChrome {
    fill: Option<Color32>,
    stroke: Stroke,
    title_color: Color32,
}

#[derive(Clone, Debug, PartialEq)]
struct SettingsNavigationLabelStyle {
    color: Color32,
    font_id: egui::FontId,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct SettingsTextEditChrome {
    fill: Color32,
    stroke: Stroke,
    focus_stroke: Stroke,
}

fn terminal_header_chrome(is_active: bool) -> TerminalHeaderChrome {
    if is_active {
        TerminalHeaderChrome {
            fill: Color32::from_rgb(30, 30, 30),
            stroke: Stroke::NONE,
            title_color: Color32::from_rgb(255, 255, 255),
            detail_color: with_alpha(TEXT_MUTED, 238),
        }
    } else {
        TerminalHeaderChrome {
            fill: Color32::from_rgb(22, 22, 22),
            stroke: Stroke::new(1.0, BORDER_COLOR),
            title_color: TEXT_PRIMARY,
            detail_color: with_alpha(TEXT_MUTED, 230),
        }
    }
}

fn terminal_manager_row_chrome(is_active: bool, is_hovered: bool) -> TerminalManagerRowChrome {
    if is_active {
        TerminalManagerRowChrome {
            fill: Some(Color32::from_rgb(38, 38, 38)),
            stroke: Stroke::new(1.0, with_alpha(Color32::from_rgb(100, 100, 100), 220)),
            title_color: Color32::from_rgb(255, 255, 255),
        }
    } else if is_hovered {
        TerminalManagerRowChrome {
            fill: Some(with_alpha(SURFACE_BG_SOFT, 180)),
            stroke: Stroke::new(1.0, with_alpha(BORDER_COLOR, 210)),
            title_color: with_alpha(TEXT_PRIMARY, 230),
        }
    } else {
        TerminalManagerRowChrome {
            fill: None,
            stroke: Stroke::NONE,
            title_color: with_alpha(TEXT_PRIMARY, 210),
        }
    }
}

fn settings_navigation_label_style(
    is_selected: bool,
    is_interacting: bool,
) -> SettingsNavigationLabelStyle {
    if is_selected {
        SettingsNavigationLabelStyle {
            color: TEXT_PRIMARY,
            font_id: egui::FontId::proportional(13.5),
        }
    } else if is_interacting {
        SettingsNavigationLabelStyle {
            color: with_alpha(TEXT_PRIMARY, 220),
            font_id: egui::FontId::proportional(13.0),
        }
    } else {
        SettingsNavigationLabelStyle {
            color: TEXT_MUTED,
            font_id: egui::FontId::proportional(13.0),
        }
    }
}

fn settings_text_edit_chrome() -> SettingsTextEditChrome {
    SettingsTextEditChrome {
        fill: with_alpha(SURFACE_BG, 236),
        stroke: Stroke::new(1.0, with_alpha(Color32::from_rgb(92, 92, 92), 230)),
        focus_stroke: Stroke::new(1.0, with_alpha(Color32::from_rgb(110, 110, 110), 230)),
    }
}

fn with_settings_text_edit_chrome<R>(ui: &mut Ui, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
    let chrome = settings_text_edit_chrome();
    ui.scope(|ui| {
        let style = ui.style_mut();
        style.visuals.extreme_bg_color = chrome.fill;
        style.visuals.selection.stroke = chrome.focus_stroke;
        style.visuals.widgets.inactive.bg_fill = chrome.fill;
        style.visuals.widgets.inactive.weak_bg_fill = chrome.fill;
        style.visuals.widgets.inactive.bg_stroke = chrome.stroke;
        style.visuals.widgets.hovered.bg_fill = chrome.fill;
        style.visuals.widgets.hovered.weak_bg_fill = chrome.fill;
        style.visuals.widgets.hovered.bg_stroke = chrome.focus_stroke;
        style.visuals.widgets.active.bg_fill = chrome.fill;
        style.visuals.widgets.active.weak_bg_fill = chrome.fill;
        style.visuals.widgets.active.bg_stroke = chrome.focus_stroke;
        style.visuals.widgets.open.bg_fill = chrome.fill;
        style.visuals.widgets.open.weak_bg_fill = chrome.fill;
        style.visuals.widgets.open.bg_stroke = chrome.focus_stroke;
        add_contents(ui)
    })
    .inner
}

fn capped_hover_text(text: &str, max_chars: usize) -> String {
    let mut result = String::new();
    for (index, ch) in text.chars().enumerate() {
        if index >= max_chars {
            result.push('…');
            break;
        }
        result.push(ch);
    }
    result
}

/// Draws a wrapped text label vertically clamped to `max_height`.
/// If the wrapped text exceeds `max_height`, a vertical scrollbar appears.
/// Returns a response anchored to the visible clamped area so that tooltips
/// and click sensing use the on-screen viewport rather than the full content rect.
fn draw_clamped_scrollable_label(
    ui: &mut Ui,
    text: &str,
    text_color: Color32,
    text_size: f32,
    max_height: f32,
    sense: egui::Sense,
    id_salt: impl std::hash::Hash,
) -> egui::Response {
    let output = egui::ScrollArea::vertical()
        .id_salt(ui.id().with(id_salt))
        .max_height(max_height)
        .auto_shrink([false, true])
        .show(ui, |ui| {
            ui.add(
                egui::Label::new(egui::RichText::new(text).color(text_color).size(text_size))
                    .wrap()
                    .sense(sense),
            )
        });

    // The inner Label's response spans the full unclamped content rect.
    // Patch it so that tooltip positioning and click sensing anchor to
    // the visible ScrollArea viewport instead of the off-screen content.
    // `output.inner_rect` is the initial allocated rect; apply auto-shrink
    // by clamping height to the actual content size.
    let visible_height = output.inner_rect.height().min(output.content_size.y);
    let visible_rect = egui::Rect::from_min_size(
        output.inner_rect.min,
        egui::vec2(output.inner_rect.width(), visible_height),
    );
    let mut response = output.inner;
    response.rect = visible_rect;
    response.interact_rect = ui.clip_rect().intersect(visible_rect);
    response
}

#[allow(dead_code)]
const RECENT_INPUTS_HOVER_MAX_CHARS: usize = 100;

/// Returns deduplicated recent inputs preserving newest-first order.
/// Identical strings appear only once (first occurrence wins).
#[allow(dead_code)]
fn deduplicated_recent_inputs(recent_inputs: &VecDeque<String>) -> Vec<&String> {
    let mut seen = HashSet::new();
    let mut result = Vec::with_capacity(recent_inputs.len());
    for input in recent_inputs.iter() {
        if seen.insert(input.as_str()) {
            result.push(input);
        }
    }
    result
}

fn terminal_history_message_estimated_height(message: &str, popup_width: f32) -> f32 {
    let message_width = (popup_width - CONTROL_ROW_HEIGHT - 18.0).max(80.0);
    let chars_per_line =
        (message_width / TERMINAL_HISTORY_POPUP_ESTIMATED_CHAR_WIDTH).max(1.0) as usize;
    let visual_lines = message
        .lines()
        .map(|line| {
            let chars = line.chars().count().max(1);
            chars.div_ceil(chars_per_line)
        })
        .sum::<usize>()
        .max(1);

    (visual_lines as f32 * TERMINAL_HISTORY_POPUP_ESTIMATED_LINE_HEIGHT)
        .max(CONTROL_ROW_HEIGHT)
        .min(TERMINAL_HISTORY_MESSAGE_MAX_HEIGHT)
}

fn terminal_history_popup_list_max_height(messages: &[&String], popup_width: f32) -> f32 {
    let visible_messages = messages
        .iter()
        .take(TERMINAL_HISTORY_POPUP_MAX_VISIBLE_ENTRIES);
    let mut visible_count = 0usize;
    let mut height = 0.0f32;
    for message in visible_messages {
        if visible_count > 0 {
            height += TERMINAL_HISTORY_POPUP_ROW_GAP;
        }
        height += terminal_history_message_estimated_height(message.as_str(), popup_width);
        visible_count += 1;
    }

    (height * TERMINAL_HISTORY_POPUP_HEIGHT_SCALE).min(TERMINAL_HISTORY_POPUP_MAX_HEIGHT)
}

#[allow(dead_code)]
fn recent_inputs_tooltip_text(recent_inputs: &VecDeque<String>) -> String {
    if recent_inputs.is_empty() {
        return String::new();
    }

    let unique = deduplicated_recent_inputs(recent_inputs);
    unique
        .into_iter()
        .map(|input| capped_hover_text(input, RECENT_INPUTS_HOVER_MAX_CHARS))
        .collect::<Vec<_>>()
        .join("\n")
}

fn with_truncation_tooltip(
    ui: &Ui,
    response: egui::Response,
    text: &str,
    _font_id: &FontId,
    _color: Color32,
    available_width: f32,
) -> egui::Response {
    if text.trim().is_empty() {
        return response;
    }

    // Check if text actually exceeds available width
    let galley = WidgetText::from(text.to_owned()).into_galley(
        ui,
        Some(TextWrapMode::Truncate),
        available_width,
        egui::TextStyle::Body,
    );

    if galley.size().x <= available_width {
        // Text fits without truncation, no tooltip needed
        return response;
    }

    // Use fixed width for consistent tooltip sizing
    let tooltip_width = TERMINAL_HOVER_WIDTH.min(ui.available_width().max(240.0));

    response.on_hover_ui(|ui| {
        ui.set_min_width(tooltip_width);
        ui.set_max_width(tooltip_width);
        ui.label(
            egui::RichText::new(capped_hover_text(text, DIRECTORY_ENTRY_TOOLTIP_MAX_CHARS))
                .color(TEXT_PRIMARY),
        );
    })
}

#[allow(dead_code)]
fn source_control_badge_color(state: SourceControlBadgeState) -> Color32 {
    match state {
        SourceControlBadgeState::Clean => Color32::from_rgb(94, 196, 130),
        SourceControlBadgeState::Error => Color32::from_rgb(224, 92, 92),
    }
}

fn source_control_snapshot_has_display_data(snapshot: &SourceControlSnapshot) -> bool {
    !snapshot.branch.is_empty()
        || snapshot.ahead > 0
        || snapshot.behind > 0
        || !snapshot.files.is_empty()
        || snapshot.added_lines.is_some()
        || snapshot.removed_lines.is_some()
}

fn source_control_branch_line(snapshot: &SourceControlSnapshot) -> Option<String> {
    if snapshot.branch.is_empty() {
        return None;
    }

    let mut branch_line = snapshot.branch.clone();
    if snapshot.ahead > 0 || snapshot.behind > 0 {
        branch_line.push_str(&format!(
            "  ahead:{} behind:{}",
            snapshot.ahead, snapshot.behind
        ));
    }
    Some(branch_line)
}

fn merge_source_control_refresh_result(
    current: Option<&SourceControlSnapshot>,
    incoming: SourceControlSnapshot,
) -> SourceControlSnapshot {
    if incoming.last_error.is_none() {
        return incoming;
    }

    match current {
        Some(current) if source_control_snapshot_has_display_data(current) => {
            let mut merged = current.clone();
            merged.loading = incoming.loading;
            merged.last_error = incoming.last_error;
            merged.partial_warning = incoming.partial_warning;
            merged
        }
        _ => incoming,
    }
}

fn terminal_manager_diff_summary_model(
    snapshot: Option<&SourceControlSnapshot>,
) -> TerminalManagerDiffSummaryModel {
    match snapshot {
        Some(snapshot) => match (snapshot.added_lines, snapshot.removed_lines) {
            (Some(added_lines), Some(removed_lines)) => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Ready,
                added_lines,
                removed_lines,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
            _ if snapshot.loading => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Loading,
                added_lines: 0,
                removed_lines: 0,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
            _ if snapshot.last_error.is_some() => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Error,
                added_lines: 0,
                removed_lines: 0,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
            _ => TerminalManagerDiffSummaryModel {
                state: TerminalManagerDiffSummaryState::Unknown,
                added_lines: 0,
                removed_lines: 0,
                tooltip_lines: source_control_tooltip_lines(
                    snapshot,
                    SOURCE_CONTROL_TOOLTIP_FILE_LIMIT,
                ),
            },
        },
        None => TerminalManagerDiffSummaryModel {
            state: TerminalManagerDiffSummaryState::Unknown,
            added_lines: 0,
            removed_lines: 0,
            tooltip_lines: vec!["Status pending".to_owned()],
        },
    }
}

#[allow(dead_code)]
fn terminal_manager_diff_summary_visual(
    summary: &TerminalManagerDiffSummaryModel,
) -> TerminalManagerDiffSummaryVisual {
    match summary.state {
        TerminalManagerDiffSummaryState::Ready => {
            // When there are no changes at all, show nothing instead of "+0 -0"
            if summary.added_lines == 0 && summary.removed_lines == 0 {
                TerminalManagerDiffSummaryVisual::Placeholder {
                    text: "",
                    color: Color32::TRANSPARENT,
                }
            } else {
                TerminalManagerDiffSummaryVisual::Totals {
                    added_text: format!("+{}", summary.added_lines),
                    removed_text: format!("-{}", summary.removed_lines),
                    added_color: source_control_badge_color(SourceControlBadgeState::Clean),
                    removed_color: source_control_badge_color(SourceControlBadgeState::Error),
                    separator_color: TEXT_MUTED,
                }
            }
        }
        TerminalManagerDiffSummaryState::Loading => TerminalManagerDiffSummaryVisual::Placeholder {
            text: "...",
            color: TEXT_MUTED,
        },
        TerminalManagerDiffSummaryState::Unknown | TerminalManagerDiffSummaryState::Error => {
            TerminalManagerDiffSummaryVisual::Placeholder {
                text: "--",
                color: TEXT_MUTED,
            }
        }
    }
}

fn source_control_tooltip_lines(snapshot: &SourceControlSnapshot, max_files: usize) -> Vec<String> {
    let has_display_data = source_control_snapshot_has_display_data(snapshot);
    let mut lines = Vec::with_capacity(max_files.saturating_add(4));

    if snapshot.loading {
        lines.push("Refreshing source control...".to_owned());
    }
    if let Some(error) = &snapshot.last_error {
        lines.push(error.clone());
    }
    if let Some(warning) = &snapshot.partial_warning {
        lines.push(warning.clone());
    }
    if !has_display_data {
        if lines.is_empty() {
            lines.push("Status pending".to_owned());
        }
        return lines;
    }

    if let Some(branch_line) = source_control_branch_line(snapshot) {
        lines.push(branch_line);
    }

    if snapshot.files.is_empty() {
        if snapshot.last_error.is_none() && !snapshot.loading {
            lines.push("Working tree is clean".to_owned());
        }
        return lines;
    }

    for file in snapshot.files.iter().take(max_files) {
        let staged = if file.staged { " [staged]" } else { "" };
        lines.push(format!("{}{}: {}", file.status, staged, file.path));
    }

    let remaining_files = snapshot
        .files
        .len()
        .saturating_sub(max_files)
        .saturating_add(snapshot.omitted_files);
    if remaining_files > 0 {
        lines.push(format!("+{} more", remaining_files));
    }

    lines
}

#[allow(dead_code)]
fn terminal_manager_diff_summary_layout_job(
    ui: &Ui,
    summary: &TerminalManagerDiffSummaryModel,
) -> LayoutJob {
    let visual = terminal_manager_diff_summary_visual(summary);
    let mut layout_job = LayoutJob::default();
    layout_job.wrap.max_width = f32::INFINITY;
    let font_id = egui::TextStyle::Small.resolve(ui.style());

    match visual {
        TerminalManagerDiffSummaryVisual::Totals {
            added_text,
            removed_text,
            added_color,
            removed_color,
            separator_color,
        } => {
            layout_job.append(
                &added_text,
                0.0,
                TextFormat {
                    font_id: font_id.clone(),
                    color: added_color,
                    ..TextFormat::default()
                },
            );
            layout_job.append(
                " ",
                0.0,
                TextFormat {
                    font_id: font_id.clone(),
                    color: separator_color,
                    ..TextFormat::default()
                },
            );
            layout_job.append(
                &removed_text,
                0.0,
                TextFormat {
                    font_id,
                    color: removed_color,
                    ..TextFormat::default()
                },
            );
        }
        TerminalManagerDiffSummaryVisual::Placeholder { text, color } => {
            layout_job.append(
                text,
                0.0,
                TextFormat {
                    font_id,
                    color,
                    ..TextFormat::default()
                },
            );
        }
    }

    layout_job
}

#[allow(dead_code)]
fn draw_terminal_manager_diff_summary(
    ui: &mut Ui,
    summary: &TerminalManagerDiffSummaryModel,
) -> egui::Response {
    let response = ui.add(
        egui::Label::new(WidgetText::from(terminal_manager_diff_summary_layout_job(
            ui, summary,
        )))
        .sense(Sense::hover()),
    );

    // Hover tooltip removed per design decision
    response
}

fn draw_terminal_manager_title_and_diff_summary(
    ui: &mut Ui,
    title: &str,
    text_color: Color32,
    is_active: bool,
    row_height: f32,
    #[allow(unused_variables)] diff_summary: &TerminalManagerDiffSummaryModel,
    show_pointing_cursor: bool,
    tooltip_text: Option<&str>,
) -> TerminalManagerTitleSummaryLayout {
    ui.allocate_ui_with_layout(
        egui::vec2(ui.available_width().max(0.0), row_height),
        Layout::left_to_right(Align::Center),
        |ui| {
            let font_id = egui::TextStyle::Body.resolve(ui.style());
            let title_label = egui::Label::new(RichText::new(title).color(text_color).strong())
                .truncate()
                .selectable(false)
                .sense(Sense::hover());
            let title_response = ui.add(title_label);
            {
                let info = WidgetInfo::selected(
                    WidgetType::SelectableLabel,
                    ui.is_enabled(),
                    is_active,
                    title,
                );
                title_response.widget_info(|| info.clone());
            }
            let title_response = if show_pointing_cursor {
                title_response.on_hover_cursor(egui::CursorIcon::PointingHand)
            } else {
                title_response
            };
            #[cfg(test)]
            let title_response = if let Some(tooltip) = tooltip_text {
                with_truncation_tooltip(
                    ui,
                    title_response,
                    tooltip,
                    &font_id,
                    text_color,
                    ui.available_width(),
                )
            } else {
                title_response.on_hover_text(title)
            };
            #[cfg(not(test))]
            let _title_response = if let Some(tooltip) = tooltip_text {
                with_truncation_tooltip(
                    ui,
                    title_response,
                    tooltip,
                    &font_id,
                    text_color,
                    ui.available_width(),
                )
            } else {
                title_response.on_hover_text(title)
            };

            ui.add_space(6.0);

            // Always render diff summary; bind response only in test builds for rect measurement
            #[cfg(test)]
            let diff_summary_response = draw_terminal_manager_diff_summary(ui, diff_summary);
            #[cfg(not(test))]
            let _ = draw_terminal_manager_diff_summary(ui, diff_summary);

            TerminalManagerTitleSummaryLayout {
                #[cfg(test)]
                title_rect: title_response.rect,
                #[cfg(test)]
                diff_summary_rect: diff_summary_response.rect,
            }
        },
    )
    .inner
}

fn paint_minimal_combo_icon(
    ui: &Ui,
    rect: egui::Rect,
    visuals: &egui::style::WidgetVisuals,
    is_open: bool,
    _above_or_below: egui::AboveOrBelow,
) {
    let center = rect.center();
    let stroke = Stroke::new(1.6, visuals.fg_stroke.color);
    let top = if is_open {
        egui::pos2(center.x - 4.0, center.y + 1.5)
    } else {
        egui::pos2(center.x - 4.0, center.y - 1.5)
    };
    let mid = if is_open {
        egui::pos2(center.x, center.y - 2.5)
    } else {
        egui::pos2(center.x, center.y + 2.5)
    };
    let bottom = if is_open {
        egui::pos2(center.x + 4.0, center.y + 1.5)
    } else {
        egui::pos2(center.x + 4.0, center.y - 1.5)
    };

    ui.painter().line_segment([top, mid], stroke);
    ui.painter().line_segment([mid, bottom], stroke);
}

fn with_minimal_button_chrome<R>(ui: &mut Ui, add_contents: impl FnOnce(&mut Ui) -> R) -> R {
    ui.scope(|ui| {
        let style = ui.style_mut();
        style.spacing.button_padding = egui::vec2(8.0, 5.0);
        let hover_fill = with_alpha(BTN_ICON_HOVER, 110);

        style.visuals.widgets.inactive.bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.inactive.weak_bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.inactive.bg_stroke = Stroke::NONE;
        style.visuals.widgets.inactive.fg_stroke = Stroke::new(1.0, with_alpha(TEXT_PRIMARY, 190));

        style.visuals.widgets.hovered.bg_fill = hover_fill;
        style.visuals.widgets.hovered.weak_bg_fill = hover_fill;
        style.visuals.widgets.hovered.bg_stroke = Stroke::NONE;
        style.visuals.widgets.hovered.fg_stroke = Stroke::new(1.0, TEXT_PRIMARY);

        style.visuals.widgets.active.bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.active.weak_bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.active.bg_stroke = Stroke::NONE;
        style.visuals.widgets.active.fg_stroke = Stroke::new(1.0, TEXT_PRIMARY);

        style.visuals.widgets.open.bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.open.weak_bg_fill = Color32::TRANSPARENT;
        style.visuals.widgets.open.bg_stroke = Stroke::NONE;
        style.visuals.widgets.open.fg_stroke = Stroke::new(1.0, TEXT_PRIMARY);

        add_contents(ui)
    })
    .inner
}

fn smart_input_status_text(terminal: &TerminalEntry) -> (&'static str, Color32) {
    if terminal.opencode_pending_question.is_some() {
        return (
            "OpenCode question - answer below",
            Color32::from_rgb(220, 170, 60),
        );
    }

    match terminal.opencode_normalized_status {
        Some(OpenCodeTransportStatus::Working) => {
            ("OpenCode working - queued tasks wait", TEXT_MUTED)
        }
        Some(OpenCodeTransportStatus::Permission) => (
            "OpenCode needs input - queue paused",
            Color32::from_rgb(220, 170, 60),
        ),
        Some(OpenCodeTransportStatus::Idle) => match terminal.opencode_attention_reason {
            Some(OpenCodeAttentionReason::TurnComplete) => (
                "Ready - next queued task will run",
                Color32::from_rgb(90, 185, 90),
            ),
            Some(OpenCodeAttentionReason::SessionError) => (
                "Session error - review before sending",
                Color32::from_rgb(210, 90, 90),
            ),
            _ => ("OpenCode idle", TEXT_MUTED),
        },
        None => ("OpenCode session starting", TEXT_MUTED),
    }
}

fn draw_smart_input_attachments(
    ui: &mut Ui,
    attachments: &mut Vec<SmartInputAttachment>,
) -> Vec<u64> {
    let mut removed = Vec::new();
    if attachments.is_empty() {
        return removed;
    }
    let chip_bg = Color32::from_rgb(44, 44, 48);
    let chip_stroke = Stroke::new(1.0, Color32::from_rgb(90, 90, 95));
    let chip_radius = 4.0;
    let mut to_remove: Vec<usize> = Vec::new();
    for (i, att) in attachments.iter().enumerate() {
        let chip = egui::Frame::none()
            .fill(chip_bg)
            .stroke(chip_stroke)
            .rounding(chip_radius)
            .inner_margin(egui::Margin::symmetric(5.0, 2.0))
            .show(ui, |ui| {
                ui.set_min_height(14.0);
                ui.horizontal(|ui| {
                    ui.spacing_mut().item_spacing = egui::vec2(4.0, 0.0);
                    ui.spacing_mut().button_padding = egui::Vec2::ZERO;
                    ui.label(RichText::new("Img:").small().color(TEXT_PRIMARY));
                    let fname = std::path::Path::new(&att.path)
                        .file_name()
                        .and_then(|s| s.to_str())
                        .unwrap_or(&att.path);
                    let short = capped_hover_text(fname, 24);
                    ui.label(RichText::new(short).small().color(TEXT_PRIMARY));
                    let (remove_rect, remove_response) = ui.allocate_exact_size(
                        egui::vec2(
                            SMART_INPUT_ATTACHMENT_REMOVE_BUTTON_SIZE,
                            SMART_INPUT_ATTACHMENT_REMOVE_BUTTON_SIZE,
                        ),
                        Sense::click(),
                    );
                    ui.painter().text(
                        remove_rect.center(),
                        egui::Align2::CENTER_CENTER,
                        "x",
                        egui::FontId::proportional(9.0),
                        Color32::from_rgb(232, 100, 100),
                    );
                    if remove_response.hovered() {
                        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
                    }
                    if remove_response.clicked() {
                        to_remove.push(i);
                    }
                });
            });
        ui.painter()
            .rect_stroke(chip.response.rect, chip_radius, chip_stroke);
    }
    for i in to_remove.iter().rev() {
        if *i < attachments.len() {
            removed.push(attachments.remove(*i).id);
        }
    }
    removed
}

fn draw_smart_input_attachments_wrapped(
    ui: &mut Ui,
    attachments: &mut Vec<SmartInputAttachment>,
    max_height: f32,
) -> Vec<u64> {
    if attachments.is_empty() {
        return Vec::new();
    }

    let mut removed = Vec::new();
    egui::ScrollArea::vertical()
        .max_height(max_height)
        .auto_shrink([false, true])
        .show(ui, |ui| {
            ui.set_max_width(ui.available_width());
            ui.horizontal_wrapped(|ui| {
                removed = draw_smart_input_attachments(ui, attachments);
            });
        });
    removed
}

fn push_smart_input_attachment(
    next_attachment_id: &mut u64,
    attachments: &mut Vec<SmartInputAttachment>,
    path: String,
) {
    let id = *next_attachment_id;
    *next_attachment_id += 1;
    attachments.push(SmartInputAttachment { id, path });
}

fn smart_input_visible_task_rows(state: &SmartInputState) -> usize {
    if !state.expanded {
        return 0;
    }
    state.tasks.len().min(SMART_INPUT_MAX_VISIBLE_TASK_ROWS)
}

fn smart_input_queue_slot_height(task_rows: usize) -> f32 {
    if task_rows == 0 {
        return 0.0;
    }
    task_rows as f32 * SMART_INPUT_TASK_ROW_HEIGHT + 4.0
}

fn smart_input_queue_top_gap(task_rows: usize) -> f32 {
    if task_rows == 0 {
        0.0
    } else {
        SMART_INPUT_QUEUE_TOP_GAP
    }
}

fn smart_input_queue_row_clip_rect(
    row_rect: egui::Rect,
    viewport_clip_rect: egui::Rect,
) -> egui::Rect {
    row_rect.intersect(viewport_clip_rect)
}

fn smart_input_drag_target_index(
    row_index: usize,
    row_rect: egui::Rect,
    pointer_pos: Option<egui::Pos2>,
) -> usize {
    let Some(pos) = pointer_pos else {
        return row_index;
    };
    if pos.y > row_rect.center().y {
        row_index.saturating_add(1)
    } else {
        row_index
    }
}

fn smart_input_question_extra_height(question: Option<&OpenCodeQuestionInfo>) -> f32 {
    let Some(question) = question else {
        return 0.0;
    };
    let choices = AdeApp::opencode_question_choice_count(question).max(1) as f32;
    SMART_INPUT_QUESTION_CARD_BASE_HEIGHT
        + choices * SMART_INPUT_QUESTION_OPTION_ROW_HEIGHT
        + if question.custom {
            SMART_INPUT_QUESTION_CUSTOM_INPUT_HEIGHT
        } else {
            0.0
        }
}

fn smart_input_draft_height(state: &SmartInputState) -> f32 {
    state
        .draft_user_height
        .unwrap_or(SMART_INPUT_DRAFT_DEFAULT_HEIGHT)
        .max(SMART_INPUT_DRAFT_MIN_HEIGHT)
}

fn smart_input_draft_extra_height(state: &SmartInputState) -> f32 {
    (smart_input_draft_height(state) - SMART_INPUT_DRAFT_DEFAULT_HEIGHT).max(0.0)
}

fn smart_input_max_footer_height(pane_height: f32, line_height: f32) -> f32 {
    (pane_height
        - TERMINAL_HEADER_HEIGHT
        - TERMINAL_HEADER_GAP
        - SMART_INPUT_FOOTER_GAP
        - line_height * 3.0)
        .max(0.0)
}

fn smart_input_safe_min_footer_height_without_draft_extra(state: &SmartInputState) -> f32 {
    let draft_extra = smart_input_draft_extra_height(state);
    (smart_input_safe_min_footer_height(state) - draft_extra).max(SMART_INPUT_MIN_FOOTER_HEIGHT)
}

fn smart_input_max_draft_height_for_footer(
    state: &SmartInputState,
    footer_height: f32,
    question_extra_height: f32,
) -> f32 {
    let safe_min_without_draft_extra =
        smart_input_safe_min_footer_height_without_draft_extra(state);
    (footer_height - question_extra_height - safe_min_without_draft_extra
        + SMART_INPUT_DRAFT_DEFAULT_HEIGHT)
        .max(SMART_INPUT_DRAFT_MIN_HEIGHT)
}

fn smart_input_clamp_draft_height_to_footer(
    state: &mut SmartInputState,
    footer_height: f32,
    question_extra_height: f32,
) {
    let Some(draft_user_height) = state.draft_user_height else {
        return;
    };
    let max_draft_height =
        smart_input_max_draft_height_for_footer(state, footer_height, question_extra_height);
    state.draft_user_height = Some(
        draft_user_height
            .max(SMART_INPUT_DRAFT_MIN_HEIGHT)
            .min(max_draft_height),
    );
}

fn smart_input_resize_footer_height(
    state: &mut SmartInputState,
    current_footer_height: f32,
    delta_y: f32,
    max_footer_height: f32,
    question_extra_height: f32,
) -> f32 {
    let min_footer =
        smart_input_safe_min_footer_height_without_draft_extra(state) + question_extra_height;
    let new_height = (current_footer_height - delta_y)
        .max(min_footer)
        .min(max_footer_height);
    smart_input_clamp_draft_height_to_footer(state, new_height, question_extra_height);
    new_height
}

fn smart_input_resize_draft_height(
    state: &mut SmartInputState,
    delta_y: f32,
    max_footer_height: f32,
    question_extra_height: f32,
) {
    let current_height = smart_input_draft_height(state);
    let max_draft_height =
        smart_input_max_draft_height_for_footer(state, max_footer_height, question_extra_height);

    state.draft_user_height = Some(
        (current_height + delta_y)
            .max(SMART_INPUT_DRAFT_MIN_HEIGHT)
            .min(max_draft_height),
    );
}

fn smart_input_desired_footer_height(state: &SmartInputState) -> f32 {
    let task_rows = smart_input_visible_task_rows(state);
    let queue_slot = smart_input_queue_slot_height(task_rows);
    SMART_INPUT_BASE_FOOTER_HEIGHT
        + queue_slot
        + smart_input_queue_top_gap(task_rows)
        + SMART_INPUT_DRAFT_TOP_GAP
        + smart_input_draft_extra_height(state)
        + if task_rows > 0 { 6.0 } else { 0.0 }
}

fn smart_input_safe_min_footer_height(state: &SmartInputState) -> f32 {
    let task_rows = smart_input_visible_task_rows(state);
    let queue_slot = smart_input_queue_slot_height(task_rows);
    let queue_top_gap = smart_input_queue_top_gap(task_rows);
    let draft_extra = smart_input_draft_extra_height(state);
    if task_rows > 0 {
        (SMART_INPUT_BASE_FOOTER_HEIGHT
            + queue_slot
            + queue_top_gap
            + SMART_INPUT_DRAFT_TOP_GAP
            + 60.0
            + draft_extra)
            .max(SMART_INPUT_MIN_FOOTER_HEIGHT)
    } else {
        (SMART_INPUT_BASE_FOOTER_HEIGHT + SMART_INPUT_DRAFT_TOP_GAP + draft_extra)
            .max(SMART_INPUT_MIN_FOOTER_HEIGHT)
    }
}

fn draw_smart_input_footer(
    ui: &mut Ui,
    terminal: &mut TerminalEntry,
    footer_size: Vec2,
    pane_height: f32,
    line_height: f32,
) -> SmartInputPaneAction {
    let terminal_id = terminal.id;
    let (status_text, status_color) = smart_input_status_text(terminal);
    let mut action = SmartInputPaneAction::default();

    egui::Frame::none()
        .fill(Color32::from_rgb(22, 22, 24))
        .stroke(Stroke::new(1.0, BORDER_COLOR))
        .rounding(8.0)
        .inner_margin(egui::Margin::symmetric(8.0, 6.0))
        .show(ui, |ui| {
            let inner_size = egui::vec2(
                (footer_size.x - 16.0).max(0.0),
                (footer_size.y - 12.0).max(0.0),
            );
            ui.set_min_size(inner_size);
            ui.set_max_width(inner_size.x);
            ui.spacing_mut().item_spacing = egui::vec2(6.0, 4.0);

            let has_queued_tasks = !terminal.smart_input.tasks.is_empty();
            ui.horizontal(|ui| {
                ui.label(
                    RichText::new(format!("{} Smart Input", icons::CHAT_TEXT))
                        .strong()
                        .color(TEXT_PRIMARY),
                );
                if has_queued_tasks {
                    ui.add_space(6.0);
                    ui.label(RichText::new(status_text).small().color(status_color));
                    ui.add_space(6.0);
                    ui.label(
                        RichText::new(format!("{} queued", terminal.smart_input.tasks.len()))
                            .small()
                            .color(TEXT_MUTED),
                    );
                }
                if has_queued_tasks {
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        ui.add_space(SMART_INPUT_HEADER_RIGHT_INSET);
                        let toggle_label = if terminal.smart_input.expanded {
                            "Hide"
                        } else {
                            "Show"
                        };
                        if ui
                            .button(RichText::new(toggle_label).small())
                            .on_hover_text("Collapse or expand queued task rows")
                            .clicked()
                        {
                            terminal.smart_input.expanded = !terminal.smart_input.expanded;
                            action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                        }
                    });
                }
            });

            // Render active OpenCode question card if present
            if let Some(question) = terminal.opencode_pending_question.clone() {
                AdeApp::normalize_opencode_question_focus_index(terminal);
                egui::Frame::none()
                    .fill(Color32::from_rgb(35, 30, 20))
                    .stroke(Stroke::new(1.0, Color32::from_rgb(220, 170, 60)))
                    .rounding(6.0)
                    .inner_margin(egui::Margin::symmetric(8.0, 6.0))
                    .show(ui, |ui| {
                        ui.horizontal(|ui| {
                            ui.label(
                                RichText::new(format!("{} OpenCode Question", icons::QUESTION))
                                    .strong()
                                    .color(Color32::from_rgb(220, 170, 60)),
                            );
                            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                                if ui
                                    .button(
                                        RichText::new("Reject")
                                            .small()
                                            .color(Color32::from_rgb(210, 90, 90)),
                                    )
                                    .on_hover_text("Reject this question")
                                    .clicked()
                                {
                                    action.reject_question = true;
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                            });
                        });

                        ui.label(RichText::new(&question.header).strong().color(TEXT_PRIMARY));
                        ui.label(RichText::new(&question.question).color(TEXT_PRIMARY));

                        for (index, opt) in question.options.iter().enumerate() {
                            let focused = terminal.opencode_question_focus_index == index;
                            let selected = terminal.opencode_question_selected.contains(&opt.label);
                            let row_height = if opt.description.trim().is_empty() {
                                28.0
                            } else {
                                SMART_INPUT_QUESTION_OPTION_ROW_HEIGHT
                            };
                            let (row_rect, row_response) = ui.allocate_exact_size(
                                egui::vec2(ui.available_width(), row_height),
                                Sense::click(),
                            );
                            let fill = if focused {
                                Color32::from_rgb(54, 44, 26)
                            } else if selected {
                                Color32::from_rgb(42, 38, 28)
                            } else {
                                Color32::TRANSPARENT
                            };
                            ui.painter().rect_filled(row_rect, 4.0, fill);
                            if focused {
                                ui.painter().rect_stroke(
                                    row_rect,
                                    4.0,
                                    Stroke::new(1.0, Color32::from_rgb(235, 185, 70)),
                                );
                            }
                            let mut row_ui = ui.new_child(
                                egui::UiBuilder::new()
                                    .max_rect(row_rect.shrink2(egui::vec2(6.0, 3.0)))
                                    .layout(egui::Layout::left_to_right(egui::Align::Min)),
                            );
                            row_ui.set_clip_rect(row_rect);
                            let marker = if focused { ">" } else { " " };
                            let check = if selected { "[x]" } else { "[ ]" };
                            row_ui.label(
                                RichText::new(format!("{marker} {}. {check}", index + 1))
                                    .small()
                                    .color(if focused {
                                        Color32::from_rgb(235, 185, 70)
                                    } else {
                                        TEXT_MUTED
                                    }),
                            );
                            row_ui.vertical(|ui| {
                                ui.label(RichText::new(&opt.label).small().color(TEXT_PRIMARY));
                                if !opt.description.trim().is_empty() {
                                    ui.label(
                                        RichText::new(&opt.description).small().color(TEXT_MUTED),
                                    );
                                }
                            });
                            if row_response.clicked() {
                                terminal.opencode_question_focus_index = index;
                                AdeApp::select_focused_opencode_question_choice(terminal);
                                action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                            }
                        }

                        if question.custom {
                            let index = question.options.len();
                            let focused = terminal.opencode_question_focus_index == index;
                            let has_custom = !terminal.opencode_question_custom.is_empty();
                            let (row_rect, row_response) = ui.allocate_exact_size(
                                egui::vec2(ui.available_width(), 28.0),
                                Sense::click(),
                            );
                            ui.painter().rect_filled(
                                row_rect,
                                4.0,
                                if focused {
                                    Color32::from_rgb(54, 44, 26)
                                } else {
                                    Color32::TRANSPARENT
                                },
                            );
                            if focused {
                                ui.painter().rect_stroke(
                                    row_rect,
                                    4.0,
                                    Stroke::new(1.0, Color32::from_rgb(235, 185, 70)),
                                );
                            }
                            let mut row_ui = ui.new_child(
                                egui::UiBuilder::new()
                                    .max_rect(row_rect.shrink2(egui::vec2(6.0, 3.0)))
                                    .layout(egui::Layout::left_to_right(egui::Align::Center)),
                            );
                            let marker = if focused { ">" } else { " " };
                            row_ui.label(
                                RichText::new(format!("{marker} {}. [ ]", index + 1))
                                    .small()
                                    .color(if focused {
                                        Color32::from_rgb(235, 185, 70)
                                    } else {
                                        TEXT_MUTED
                                    }),
                            );
                            row_ui.label(
                                RichText::new("Type your own answer")
                                    .small()
                                    .color(TEXT_PRIMARY),
                            );
                            if row_response.clicked() {
                                terminal.opencode_question_focus_index = index;
                                terminal.opencode_question_selected.clear();
                                action.request_keyboard_focus(
                                    SmartInputFocusTarget::QuestionCustom,
                                );
                            }

                            if focused || has_custom {
                                ui.horizontal(|ui| {
                                    ui.label(RichText::new("Custom:").small().color(TEXT_MUTED));
                                    let custom_id =
                                        AdeApp::smart_input_question_custom_input_id(terminal_id);
                                    let custom_response = ui.add_sized(
                                        egui::vec2((ui.available_width() - 8.0).max(120.0), 22.0),
                                        egui::TextEdit::singleline(
                                            &mut terminal.opencode_question_custom,
                                        )
                                        .id(custom_id),
                                    );
                                    if custom_response.clicked() || custom_response.gained_focus()
                                    {
                                        action.request_keyboard_focus(
                                            SmartInputFocusTarget::QuestionCustom,
                                        );
                                    }
                                });
                            }
                        }

                        let help_text = if question.multiple {
                            "Up/Down select   Space toggle   Enter submit   Esc dismiss"
                        } else {
                            "Up/Down select   Enter submit   Esc dismiss"
                        };
                        ui.label(RichText::new(help_text).small().color(TEXT_MUTED));

                        ui.horizontal(|ui| {
                            let can_submit = AdeApp::opencode_question_can_submit(terminal);
                            ui.add_enabled_ui(can_submit, |ui| {
                                if ui.button(RichText::new("Submit Answer").strong()).clicked() {
                                    action.submit_question = true;
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                            });
                        });
                    });
            }

            let question_extra_height =
                smart_input_question_extra_height(terminal.opencode_pending_question.as_ref());
            let state = &mut terminal.smart_input;

            // Queue area: allocate a slot sized to actual visible rows so the footer
            // height matches rendered content.
            let task_rows = smart_input_visible_task_rows(state);
            let queue_slot_height = smart_input_queue_slot_height(task_rows);
            if queue_slot_height > 0.0 {
                ui.add_space(smart_input_queue_top_gap(task_rows));
                let (queue_rect, _) = ui.allocate_exact_size(
                    egui::vec2(ui.available_width(), queue_slot_height),
                    egui::Sense::hover(),
                );
                let mut queue_ui = ui.new_child(
                    egui::UiBuilder::new()
                        .max_rect(queue_rect)
                        .layout(egui::Layout::top_down(egui::Align::Min)),
                );
                queue_ui.set_clip_rect(queue_rect);
                let mut row_action: Option<(u64, &'static str)> = None;
                let should_scroll_to_end =
                    state.queue_scroll_to_end && state.dragging_task_id.is_none();
                state.queue_scroll_to_end = false;
                egui::ScrollArea::vertical()
                    .id_salt(("smart_input_queue", terminal_id))
                    .max_height(queue_rect.height())
                    .auto_shrink([false, false])
                    .stick_to_bottom(should_scroll_to_end)
                    .show(&mut queue_ui, |ui| {
                        ui.set_min_width(queue_rect.width());
                        ui.set_max_width(queue_rect.width());
                        let pointer_pos =
                            ui.ctx().input(|input| input.pointer.interact_pos());
                        let primary_down =
                            ui.ctx().input(|input| input.pointer.primary_down());
                        if state.dragging_task_id.is_none() {
                            state.drag_hover_index = None;
                        }
                        let task_count = state.tasks.len();
                        let mut last_row_rect = None;
                        for index in 0..task_count {
                            let task_id = state.tasks[index].id;
                            let task_text = state.tasks[index].text.clone();
                            let is_editing = state.editing_task_id == Some(task_id);

                            let (row_rect, _) = ui.allocate_exact_size(
                                egui::vec2(queue_rect.width(), SMART_INPUT_TASK_ROW_HEIGHT),
                                egui::Sense::hover(),
                            );
                            let mut row_ui = ui.new_child(
                                egui::UiBuilder::new()
                                    .max_rect(row_rect)
                                    .layout(egui::Layout::left_to_right(egui::Align::Min)),
                            );
                            let row_clip_rect =
                                smart_input_queue_row_clip_rect(row_rect, ui.clip_rect());
                            row_ui.set_clip_rect(row_clip_rect);
                            last_row_rect = Some(row_rect);
                            if state.dragging_task_id.is_some()
                                && pointer_pos.is_some_and(|pos| row_clip_rect.contains(pos))
                            {
                                state.drag_hover_index =
                                    Some(smart_input_drag_target_index(index, row_rect, pointer_pos));
                            }
                            // Paint a subtle row background so the queue area is visible even
                            // when the task text is empty.
                            if index % 2 == 0 {
                                row_ui.painter().rect_filled(
                                    row_rect,
                                    0.0,
                                    Color32::from_rgb(28, 28, 30),
                                );
                            }
                            if state.dragging_task_id.is_some() {
                                let drag_line_color = Color32::from_rgb(95, 150, 255);
                                if state.drag_hover_index == Some(index) {
                                    row_ui.painter().line_segment(
                                        [row_rect.left_top(), row_rect.right_top()],
                                        Stroke::new(2.0, drag_line_color),
                                    );
                                }
                                if index + 1 == task_count
                                    && state.drag_hover_index == Some(task_count)
                                {
                                    row_ui.painter().line_segment(
                                        [row_rect.left_bottom(), row_rect.right_bottom()],
                                        Stroke::new(2.0, drag_line_color),
                                    );
                                }
                            }

                            let is_dragging_this = state.dragging_task_id == Some(task_id);
                            if !is_editing {
                                let (drag_rect, drag_response) = row_ui.allocate_exact_size(
                                    egui::vec2(
                                        SMART_INPUT_TASK_DRAG_HANDLE_WIDTH,
                                        SMART_INPUT_TASK_ROW_HEIGHT,
                                    ),
                                    Sense::drag(),
                                );
                                if row_ui.is_rect_visible(drag_rect) {
                                    let icon_color = if is_dragging_this
                                        || drag_response.is_pointer_button_down_on()
                                        || drag_response.hovered()
                                    {
                                        TEXT_PRIMARY
                                    } else {
                                        with_alpha(TEXT_PRIMARY, 150)
                                    };
                                    row_ui.painter().text(
                                        drag_rect.center(),
                                        egui::Align2::CENTER_CENTER,
                                        format!("{}", icons::GRIP_VERTICAL),
                                        egui::FontId::proportional(14.0),
                                        icon_color,
                                    );
                                }
                                if is_dragging_this || drag_response.dragged() {
                                    row_ui.ctx().set_cursor_icon(egui::CursorIcon::Grabbing);
                                } else if drag_response.hovered() {
                                    row_ui.ctx().set_cursor_icon(egui::CursorIcon::Grab);
                                }
                                if drag_response.drag_started_by(egui::PointerButton::Primary) {
                                    state.dragging_task_id = Some(task_id);
                                    state.drag_hover_index = Some(index);
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                                if state.dragging_task_id == Some(task_id)
                                    && (drag_response.dragged_by(egui::PointerButton::Primary)
                                        || primary_down)
                                {
                                    state.drag_hover_index = Some(smart_input_drag_target_index(
                                        index,
                                        row_rect,
                                        pointer_pos,
                                    ));
                                    row_ui.ctx().request_repaint_after(Duration::from_millis(16));
                                }
                            }

                            let index_text = format!("{}.", index + 1);
                            let (index_rect, _) = row_ui.allocate_exact_size(
                                egui::vec2(
                                    SMART_INPUT_TASK_INDEX_WIDTH,
                                    SMART_INPUT_TASK_ROW_HEIGHT,
                                ),
                                Sense::hover(),
                            );
                            if row_ui.is_rect_visible(index_rect) {
                                let index_galley =
                                    WidgetText::from(RichText::new(&index_text).color(TEXT_MUTED))
                                        .into_galley(
                                            &row_ui,
                                            Some(TextWrapMode::Truncate),
                                            index_rect.width(),
                                            egui::TextStyle::Body,
                                        );
                                let index_pos = egui::pos2(
                                    index_rect.left(),
                                    row_rect.center().y - (index_galley.size().y * 0.5),
                                );
                                row_ui.painter().galley(index_pos, index_galley, TEXT_MUTED);
                            }

                            if is_editing {
                                let edit_id =
                                    AdeApp::smart_input_task_edit_input_id(terminal_id, task_id);
                                let secondary_pressed = row_ui
                                    .ctx()
                                    .input(|input| input.pointer.secondary_pressed());
                                let pre_click_range =
                                    egui::text_edit::TextEditState::load(row_ui.ctx(), edit_id)
                                        .and_then(|s| s.cursor.char_range())
                                        .filter(|range| range.primary != range.secondary);
                                if secondary_pressed && pre_click_range.is_some() {
                                    state.edit_context_menu_selection_range = pre_click_range;
                                }
                                let edit_response =
                                    with_settings_text_edit_chrome(&mut row_ui, |ui| {
                                        let text_width =
                                            (ui.available_width() - 80.0).max(80.0);
                                        ui.add_sized(
                                            egui::vec2(text_width, 22.0),
                                            egui::TextEdit::singleline(&mut state.edit_draft)
                                                .id(edit_id)
                                                .hint_text("Edit queued task"),
                                        )
                                    });
                                if edit_response.clicked() || edit_response.gained_focus() {
                                    action.request_keyboard_focus(SmartInputFocusTarget::Edit(
                                        task_id,
                                    ));
                                }
                                let post_show_range =
                                    egui::text_edit::TextEditState::load(row_ui.ctx(), edit_id)
                                        .and_then(|s| s.cursor.char_range())
                                        .filter(|range| range.primary != range.secondary);
                                let effective_range = state
                                    .edit_context_menu_selection_range
                                    .or(post_show_range)
                                    .filter(|range| range.primary != range.secondary);
                                edit_response.context_menu(|ui| {
                                    with_minimal_button_chrome(ui, |ui| {
                                        let has_selection = effective_range.is_some();
                                        ui.add_enabled_ui(has_selection, |ui| {
                                            if ui.button(format!("{} Copy", icons::COPY)).clicked()
                                            {
                                                action.request_keyboard_focus(
                                                    SmartInputFocusTarget::Edit(task_id),
                                                );
                                                if let Some(range) = effective_range {
                                                    let copied = extract_text_from_char_range(
                                                        &state.edit_draft,
                                                        Some(range),
                                                    );
                                                    if let Some(text) = copied {
                                                        ui.ctx().copy_text(text);
                                                    }
                                                }
                                                ui.close_menu();
                                            }
                                        });
                                        if ui.button(format!("{} Paste", icons::PLUS)).clicked() {
                                            action.request_keyboard_focus(
                                                SmartInputFocusTarget::Edit(task_id),
                                            );
                                            if let Some(path) = AdeApp::clipboard_image_path() {
                                                push_smart_input_attachment(
                                                    &mut state.next_attachment_id,
                                                    &mut state.edit_attachments,
                                                    path,
                                                );
                                            } else if let Ok(mut clipboard) = Clipboard::new() {
                                                if let Ok(text) = clipboard.get_text() {
                                                    replace_text_range_or_append(
                                                        &mut state.edit_draft,
                                                        effective_range,
                                                        &text,
                                                    );
                                                }
                                            }
                                            ui.close_menu();
                                        }
                                    });
                                });
                                if let Some(stored_range) = state.edit_context_menu_selection_range
                                {
                                    if stored_range.primary != stored_range.secondary {
                                        if let Some(mut text_state) =
                                            egui::text_edit::TextEditState::load(
                                                row_ui.ctx(),
                                                edit_id,
                                            )
                                        {
                                            text_state.cursor.set_char_range(Some(stored_range));
                                            text_state.store(row_ui.ctx(), edit_id);
                                        }
                                    }
                                }
                                let removed_edit = draw_smart_input_attachments(
                                    &mut row_ui,
                                    &mut state.edit_attachments,
                                );
                                if !removed_edit.is_empty() {
                                    action.request_keyboard_focus(SmartInputFocusTarget::Edit(
                                        task_id,
                                    ));
                                }
                                if styled_icon_button(
                                    &mut row_ui,
                                    icons::CHECK_CIRCLE,
                                    BTN_SUBTLE,
                                    BTN_TEAL_HOVER,
                                    BTN_ICON_ACTIVE,
                                    "Save",
                                ) {
                                    row_action = Some((task_id, "save"));
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                                if styled_icon_button(
                                    &mut row_ui,
                                    icons::X,
                                    BTN_SUBTLE,
                                    BTN_RED_HOVER,
                                    Color32::from_rgb(170, 50, 50),
                                    "Cancel",
                                ) {
                                    row_action = Some((task_id, "cancel"));
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                            } else {
                                let text_color = if is_dragging_this {
                                    TEXT_MUTED
                                } else {
                                    TEXT_PRIMARY
                                };

                                let preview = if task_text.trim().is_empty() {
                                    "(Image attachment)".to_owned()
                                } else {
                                    capped_hover_text(&task_text, 72)
                                };
                                let action_reserved = CONTROL_ROW_HEIGHT * 4.0 + 48.0;
                                let text_width =
                                    (row_ui.available_width() - action_reserved).max(60.0);
                                let (text_rect, label_response) = row_ui.allocate_exact_size(
                                    egui::vec2(text_width, SMART_INPUT_TASK_ROW_HEIGHT),
                                    Sense::click(),
                                );
                                if row_ui.is_rect_visible(text_rect) {
                                    let galley =
                                        WidgetText::from(RichText::new(&preview).color(text_color))
                                            .into_galley(
                                                &row_ui,
                                                Some(TextWrapMode::Truncate),
                                                text_rect.width(),
                                                egui::TextStyle::Body,
                                            );
                                    let text_pos = egui::pos2(
                                        text_rect.left(),
                                        row_rect.center().y - (galley.size().y * 0.5),
                                    );
                                    row_ui.painter().galley(text_pos, galley, text_color);
                                }
                                let label_response =
                                    label_response.on_hover_text(if task_text.trim().is_empty() {
                                        "Queued image attachment".to_owned()
                                    } else {
                                        capped_hover_text(
                                            &task_text,
                                            SMART_INPUT_TOOLTIP_MAX_CHARS,
                                        )
                                    });
                                if label_response.clicked() {
                                    row_ui.ctx().copy_text(task_text.clone());
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                                let task_attachments = &mut state.tasks[index].attachments;
                                let removed =
                                    draw_smart_input_attachments(&mut row_ui, task_attachments);
                                if !removed.is_empty() {
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }

                                row_ui.add_space(8.0);

                                if styled_icon_button(
                                    &mut row_ui,
                                    icons::ARROW_RIGHT,
                                    BTN_SUBTLE,
                                    BTN_BLUE_HOVER,
                                    BTN_ICON_ACTIVE,
                                    "Send task now",
                                ) {
                                    let atts = state.tasks[index].attachments.clone();
                                    action.send_task_now = Some((task_id, atts));
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                                if styled_icon_button(
                                    &mut row_ui,
                                    icons::COPY,
                                    BTN_SUBTLE,
                                    BTN_BLUE_HOVER,
                                    BTN_ICON_ACTIVE,
                                    "Copy prompt",
                                ) {
                                    row_ui.ctx().copy_text(task_text.clone());
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                                if styled_icon_button(
                                    &mut row_ui,
                                    icons::CODE,
                                    BTN_SUBTLE,
                                    BTN_TEAL_HOVER,
                                    BTN_ICON_ACTIVE,
                                    "Edit",
                                ) {
                                    row_action = Some((task_id, "edit"));
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                                if styled_icon_button(
                                    &mut row_ui,
                                    icons::TRASH,
                                    BTN_SUBTLE,
                                    BTN_RED_HOVER,
                                    Color32::from_rgb(170, 50, 50),
                                    "Delete",
                                ) {
                                    row_action = Some((task_id, "delete"));
                                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                }
                            }
                        }
                        if let Some(dragging_task_id) = state.dragging_task_id {
                            if let Some(pos) = pointer_pos {
                                if pos.x >= queue_rect.left() && pos.x <= queue_rect.right() {
                                    if pos.y < queue_rect.top() {
                                        state.drag_hover_index = Some(0);
                                    } else if last_row_rect
                                        .is_some_and(|last_rect| pos.y > last_rect.bottom())
                                    {
                                        state.drag_hover_index = Some(state.tasks.len());
                                    }
                                }
                            }
                            if primary_down {
                                let autoscroll_delta = selection_edge_autoscroll_delta(
                                    pointer_pos,
                                    queue_rect,
                                    SMART_INPUT_TASK_ROW_HEIGHT,
                                );
                                if autoscroll_delta != 0.0 {
                                    ui.scroll_with_delta(egui::vec2(0.0, autoscroll_delta));
                                    ui.ctx().request_repaint_after(Duration::from_millis(16));
                                }
                                if state.tasks.iter().all(|task| task.id != dragging_task_id) {
                                    state.clear_drag_state();
                                }
                            }
                        }
                        if should_scroll_to_end {
                            ui.scroll_to_cursor(Some(egui::Align::BOTTOM));
                        }
                    });

                let primary_down = ui.ctx().input(|input| input.pointer.primary_down());
                if !primary_down {
                    let dragging_task_id = state.dragging_task_id;
                    let drag_hover_index = state.drag_hover_index;
                    state.clear_drag_state();
                    if let (Some(task_id), Some(target_index)) =
                        (dragging_task_id, drag_hover_index)
                    {
                        if state.reorder_task_to_index(task_id, target_index) {
                            action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                        }
                    }
                }

                if let Some((task_id, row_action)) = row_action {
                    match row_action {
                        "save" => {
                            let _ = state.save_edit(task_id);
                        }
                        "cancel" => state.cancel_edit(),
                        "edit" => {
                            action.status_message = Some(
                                match state.move_task_to_draft_for_edit(task_id) {
                                    SmartInputDraftEditResult::Moved => {
                                        "Smart Input queued task moved to draft".to_owned()
                                    }
                                    SmartInputDraftEditResult::DraftOccupied => {
                                        "Draft dolu; düzenlemeden önce inputu boşalt veya kuyruğa ekle"
                                            .to_owned()
                                    }
                                    SmartInputDraftEditResult::Missing => {
                                        "Smart Input queued task no longer exists".to_owned()
                                    }
                                },
                            );
                        }
                        "delete" => {
                            let _ = state.remove_task(task_id);
                        }
                        _ => {}
                    }
                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                }
            }

            ui.add_space(SMART_INPUT_DRAFT_TOP_GAP);

            // Draft input: keep its user resize separate from the full Smart Input footer resize.
            ui.horizontal(|ui| {
                let draft_id = AdeApp::smart_input_draft_input_id(terminal_id);
                let input_height = smart_input_draft_height(state);
                let input_width = (ui.available_width() - 44.0).max(120.0);
                // Preserve selection before right-click collapses it
                let secondary_pressed = ui.ctx().input(|input| input.pointer.secondary_pressed());
                let pre_click_range = egui::text_edit::TextEditState::load(ui.ctx(), draft_id)
                    .and_then(|s| s.cursor.char_range())
                    .filter(|range| range.primary != range.secondary);
                if secondary_pressed && pre_click_range.is_some() {
                    state.draft_context_menu_selection_range = pre_click_range;
                }
                let chrome = settings_text_edit_chrome();
                let draft_has_focus = ui.ctx().memory(|mem| mem.has_focus(draft_id));
                let draft_stroke = if draft_has_focus {
                    chrome.focus_stroke
                } else {
                    chrome.stroke
                };
                let (draft_frame_rect, _) =
                    ui.allocate_exact_size(egui::vec2(input_width, input_height), Sense::hover());
                ui.painter()
                    .rect_filled(draft_frame_rect, 2.0, chrome.fill);
                ui.painter()
                    .rect_stroke(draft_frame_rect, 2.0, draft_stroke);
                let content_rect = draft_frame_rect.shrink2(egui::vec2(
                    SMART_INPUT_DRAFT_INNER_MARGIN_X,
                    SMART_INPUT_DRAFT_INNER_MARGIN_Y,
                ));
                let attachment_space = if state.draft_attachments.is_empty() {
                    0.0
                } else {
                    SMART_INPUT_DRAFT_ATTACHMENT_STRIP_HEIGHT
                };
                let attachment_gap = if state.draft_attachments.is_empty() {
                    0.0
                } else {
                    4.0
                };
                let text_height =
                    (content_rect.height() - attachment_space - attachment_gap).max(18.0);
                let text_rect = egui::Rect::from_min_size(
                    content_rect.min,
                    egui::vec2(content_rect.width(), text_height.min(content_rect.height())),
                );
                let mut draft_ui = ui.new_child(
                    egui::UiBuilder::new()
                        .max_rect(text_rect)
                        .layout(Layout::top_down(Align::Min)),
                );
                draft_ui.set_clip_rect(text_rect);
                draft_ui.set_min_size(text_rect.size());
                draft_ui.set_max_width(text_rect.width());
                let inner_width = text_rect.width().max(60.0);
                let draft_response = draft_ui.add_sized(
                    egui::vec2(inner_width, text_height),
                    egui::TextEdit::multiline(&mut state.draft)
                        .id(draft_id)
                        .desired_width(inner_width)
                        .frame(false)
                        .hint_text(
                            RichText::new("Task for after done (Enter queues, Ctrl+Enter newline)")
                                .color(TEXT_MUTED),
                        )
                        .return_key(egui::KeyboardShortcut::new(
                            egui::Modifiers::CTRL,
                            egui::Key::Enter,
                        )),
                );
                if draft_response.clicked() || draft_response.gained_focus() {
                    action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                }
                if !state.draft_attachments.is_empty() {
                    let attachment_rect = egui::Rect::from_min_size(
                        egui::pos2(content_rect.left(), content_rect.bottom() - attachment_space),
                        egui::vec2(content_rect.width(), attachment_space),
                    );
                    let mut attachment_ui = ui.new_child(
                        egui::UiBuilder::new()
                            .max_rect(attachment_rect)
                            .layout(Layout::top_down(Align::Min)),
                    );
                    attachment_ui.set_clip_rect(attachment_rect);
                    attachment_ui.set_min_size(attachment_rect.size());
                    attachment_ui.set_max_width(attachment_rect.width());
                    let removed_draft = draw_smart_input_attachments_wrapped(
                        &mut attachment_ui,
                        &mut state.draft_attachments,
                        attachment_space,
                    );
                    if !removed_draft.is_empty() {
                        action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                    }
                }
                // Determine effective selection for context menu
                let post_show_range = egui::text_edit::TextEditState::load(ui.ctx(), draft_id)
                    .and_then(|s| s.cursor.char_range())
                    .filter(|range| range.primary != range.secondary);
                let effective_range = state
                    .draft_context_menu_selection_range
                    .or(post_show_range)
                    .filter(|range| range.primary != range.secondary);
                draft_response.context_menu(|ui| {
                    with_minimal_button_chrome(ui, |ui| {
                        let has_selection = effective_range.is_some();

                        ui.add_enabled_ui(has_selection, |ui| {
                            if ui.button(format!("{} Copy", icons::COPY)).clicked() {
                                action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                                if let Some(range) = effective_range {
                                    let copied =
                                        extract_text_from_char_range(&state.draft, Some(range));
                                    if let Some(text) = copied {
                                        ui.ctx().copy_text(text);
                                    }
                                }
                                ui.close_menu();
                            }
                        });

                        if ui.button(format!("{} Paste", icons::PLUS)).clicked() {
                            action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                            if let Some(path) = AdeApp::clipboard_image_path() {
                                push_smart_input_attachment(
                                    &mut state.next_attachment_id,
                                    &mut state.draft_attachments,
                                    path,
                                );
                            } else if let Ok(mut clipboard) = Clipboard::new() {
                                if let Ok(text) = clipboard.get_text() {
                                    replace_text_range_or_append(
                                        &mut state.draft,
                                        effective_range,
                                        &text,
                                    );
                                }
                            }
                            ui.close_menu();
                        }
                    });
                });
                // Restore stored selection so it remains visible while menu is open
                if let Some(stored_range) = state.draft_context_menu_selection_range {
                    if stored_range.primary != stored_range.secondary {
                        if let Some(mut text_state) =
                            egui::text_edit::TextEditState::load(ui.ctx(), draft_id)
                        {
                            text_state.cursor.set_char_range(Some(stored_range));
                            text_state.store(ui.ctx(), draft_id);
                        }
                    }
                }

                let can_submit =
                    !state.draft.trim().is_empty() || !state.draft_attachments.is_empty();
                ui.add_enabled_ui(can_submit, |ui| {
                    if styled_icon_button(
                        ui,
                        icons::SEND_HORIZONTAL,
                        BTN_BLUE,
                        BTN_BLUE_HOVER,
                        BTN_ICON_ACTIVE,
                        "Submit draft",
                    ) {
                        let _ = state.enqueue_draft();
                        action.request_keyboard_focus(SmartInputFocusTarget::Draft);
                    }
                });

                // Draggable resize grip at the bottom-right of the draft text area.
                // Dragging is allowed again but clamped to a safe minimum so the queue
                // and draft input are never crushed.
                let grip_size = 12.0;
                let grip_rect = egui::Rect::from_min_size(
                    egui::pos2(
                        draft_frame_rect.right() - grip_size,
                        draft_frame_rect.bottom() - grip_size,
                    ),
                    egui::vec2(grip_size, grip_size),
                );
                let grip_response =
                    ui.interact(grip_rect, ui.id().with("draft_resize"), Sense::drag());
                let grip_color = if grip_response.hovered() || grip_response.dragged() {
                    Color32::from_rgb(160, 160, 160)
                } else {
                    Color32::from_rgb(100, 100, 100)
                };
                let x0 = grip_rect.left() + 3.0;
                let y0 = grip_rect.top() + 3.0;
                let x1 = grip_rect.right() - 3.0;
                let y1 = grip_rect.bottom() - 3.0;
                ui.painter().line_segment(
                    [egui::pos2(x0, y1), egui::pos2(x1, y0)],
                    Stroke::new(1.5, grip_color),
                );
                ui.painter().line_segment(
                    [egui::pos2(x0 + 3.0, y1), egui::pos2(x1, y0 + 3.0)],
                    Stroke::new(1.5, grip_color),
                );
                if grip_response.hovered() || grip_response.dragged() {
                    ui.ctx().set_cursor_icon(egui::CursorIcon::ResizeVertical);
                }
                if grip_response.dragged() {
                    let delta = ui.ctx().input(|i| i.pointer.delta().y);
                    let max_footer = smart_input_max_footer_height(pane_height, line_height);
                    smart_input_resize_draft_height(
                        state,
                        delta,
                        max_footer,
                        question_extra_height,
                    );
                    ui.ctx().request_repaint();
                }
            });

            // Clear stored context menu selections when menu closes
            let is_menu_open = ui.ctx().is_context_menu_open();
            if state.draft_context_menu_was_open && !is_menu_open {
                state.draft_context_menu_selection_range = None;
            }
            if state.edit_context_menu_was_open && !is_menu_open {
                state.edit_context_menu_selection_range = None;
            }
            state.draft_context_menu_was_open = is_menu_open;
            state.edit_context_menu_was_open = is_menu_open;
        });

    action
}

fn draw_terminal_saved_message_menu_button(
    ui: &mut Ui,
    saved_messages: &[String],
    send_message: &mut Option<String>,
) -> egui::Response {
    let message_menu = with_minimal_button_chrome(ui, |ui| {
        ui.menu_button(format!("{}", icons::CHAT_TEXT), |ui| {
            with_minimal_button_chrome(ui, |ui| {
                if saved_messages.is_empty() {
                    ui.label(RichText::new("No saved messages").color(TEXT_MUTED));
                    return;
                }

                for message in saved_messages {
                    if ui.button(message).clicked() {
                        *send_message = Some(message.clone());
                        ui.close_menu();
                    }
                }
            });
        })
    });
    let response = message_menu
        .response
        .on_hover_text("Send saved message")
        .on_hover_cursor(egui::CursorIcon::PointingHand);
    if response.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    response
}

/// Draw the foreground message menu button with queue management.
/// Returns (send_message, edit_index, delete_index, add_new_clicked)
fn draw_terminal_foreground_message_menu_button(
    ui: &mut Ui,
    foreground_messages: &[String],
) -> (Option<String>, Option<usize>, Option<usize>, bool) {
    let mut send_message: Option<String> = None;
    let mut edit_index: Option<usize> = None;
    let mut delete_index: Option<usize> = None;
    let mut add_new_clicked = false;

    let icon_color = if foreground_messages.is_empty() {
        with_alpha(TEXT_PRIMARY, 190)
    } else {
        Color32::from_rgb(90, 185, 90)
    };

    let message_menu = with_minimal_button_chrome(ui, |ui| {
        ui.menu_button(
            RichText::new(format!("{}", icons::CHAT_TEXT)).color(icon_color),
            |ui| {
                with_minimal_button_chrome(ui, |ui| {
                    if foreground_messages.is_empty() {
                        ui.label(RichText::new("No tasks in queue").color(TEXT_MUTED));
                    } else {
                        ui.label(
                            RichText::new("Click to send (removes from queue)")
                                .small()
                                .color(TEXT_MUTED),
                        );
                        ui.add_space(4.0);

                        // Fixed menu width to prevent infinite expansion
                        // Use set_min_width on the menu button wrapper to constrain layout
                        let menu_fixed_width = 160.0f32;
                        // Fixed width for action buttons area (2 icon buttons + gap)
                        let action_button_width = CONTROL_ROW_HEIGHT * 2.0 + 4.0;
                        let message_width =
                            (menu_fixed_width - action_button_width - 8.0).max(80.0);

                        // Wrap task list in ScrollArea to prevent overflow with many/long tasks
                        egui::ScrollArea::vertical()
                            .id_salt("foreground_tasks_menu_scroll")
                            .max_height(FOREGROUND_TASKS_MENU_MAX_HEIGHT)
                            .auto_shrink([false, false])
                            .show(ui, |ui| {
                                for (index, message) in foreground_messages.iter().enumerate() {
                                    ui.horizontal(|ui| {
                                        // Constrain horizontal layout to fixed width
                                        ui.set_min_width(menu_fixed_width);
                                        ui.set_max_width(menu_fixed_width);

                                        // Message button - sends and removes from queue (fixed width)
                                        let msg_button = ui
                                            .add_sized(
                                                egui::vec2(message_width, CONTROL_ROW_HEIGHT),
                                                egui::Button::new(RichText::new(
                                                    capped_hover_text(message, 35),
                                                ))
                                                .sense(egui::Sense::click()),
                                            )
                                            .on_hover_text(capped_hover_text(
                                                message,
                                                FOREGROUND_TASK_TOOLTIP_MAX_CHARS,
                                            ))
                                            .on_hover_cursor(egui::CursorIcon::PointingHand);
                                        if msg_button.clicked() {
                                            send_message = Some(message.clone());
                                            ui.close_menu();
                                        }

                                        ui.add_space(4.0);

                                        // Edit button (fixed position on right)
                                        if styled_icon_button(
                                            ui,
                                            AppIcon::Code,
                                            BTN_SUBTLE,
                                            BTN_BLUE_HOVER,
                                            BTN_ICON_ACTIVE,
                                            "Edit",
                                        ) {
                                            edit_index = Some(index);
                                            ui.close_menu();
                                        }

                                        // Delete button (fixed position on right)
                                        if styled_icon_button(
                                            ui,
                                            AppIcon::Trash,
                                            BTN_SUBTLE,
                                            BTN_RED_HOVER,
                                            Color32::from_rgb(170, 50, 50),
                                            "Delete",
                                        ) {
                                            delete_index = Some(index);
                                            ui.close_menu();
                                        }
                                    });
                                }
                            });
                    }

                    ui.add_space(8.0);
                    ui.separator();
                    ui.add_space(4.0);

                    // Add new button
                    if ui
                        .button(format!("{} Add New", icons::PLUS))
                        .on_hover_text("Add new task to queue")
                        .on_hover_cursor(egui::CursorIcon::PointingHand)
                        .clicked()
                    {
                        add_new_clicked = true;
                        ui.close_menu();
                    }
                });
            },
        )
    });

    let response = message_menu
        .response
        .on_hover_text("Foreground tasks")
        .on_hover_cursor(egui::CursorIcon::PointingHand);
    if response.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }

    (send_message, edit_index, delete_index, add_new_clicked)
}

fn project_group_header_actions_width(action_kind: TerminalKind, _section_gap: f32) -> f32 {
    match action_kind {
        TerminalKind::Foreground => CONTROL_ROW_HEIGHT * 2.0,
        TerminalKind::Background => CONTROL_ROW_HEIGHT,
    }
}

fn project_group_header_action_spec(
    action_kind: TerminalKind,
) -> (AppIcon, Color32, Color32, &'static str) {
    match action_kind {
        TerminalKind::Foreground => (
            icons::TERMINAL,
            BTN_BLUE,
            BTN_BLUE_HOVER,
            "Open Foreground Launcher",
        ),
        TerminalKind::Background => (
            icons::LIST,
            BTN_TEAL,
            BTN_TEAL_HOVER,
            "New Background Terminal",
        ),
    }
}

fn terminal_manager_filter_label(filter: TerminalManagerFilter) -> &'static str {
    match filter {
        TerminalManagerFilter::Foreground => "Foreground",
        TerminalManagerFilter::Background => "Background",
    }
}

fn terminal_manager_filter_color(filter: TerminalManagerFilter) -> Color32 {
    match filter {
        TerminalManagerFilter::Foreground => ACCENT,
        TerminalManagerFilter::Background => TEXT_MUTED,
    }
}

fn terminal_manager_filter_row_height(base_height: f32) -> f32 {
    base_height + TERMINAL_MANAGER_FILTER_ROW_HEIGHT_EXTRA
}

#[derive(Clone, Copy, Debug)]
struct TerminalManagerFilterLayout {
    foreground_slot_rect: egui::Rect,
    background_slot_rect: egui::Rect,
    foreground_label_rect: egui::Rect,
    background_label_rect: egui::Rect,
}

fn terminal_manager_filter_label_size(ui: &Ui, filter: TerminalManagerFilter) -> Vec2 {
    WidgetText::from(RichText::new(terminal_manager_filter_label(filter)).strong())
        .into_galley(
            ui,
            Some(TextWrapMode::Truncate),
            f32::INFINITY,
            egui::TextStyle::Body,
        )
        .size()
}

fn terminal_manager_filter_label_rect(slot_rect: egui::Rect, label_size: Vec2) -> egui::Rect {
    let label_width = label_size.x.min(slot_rect.width().max(0.0));
    let label_x = slot_rect.center().x - (label_width * 0.5);

    egui::Rect::from_min_size(
        egui::pos2(
            label_x,
            slot_rect.top() + TERMINAL_MANAGER_FILTER_TOP_PADDING,
        ),
        egui::vec2(label_width, label_size.y),
    )
}

fn terminal_manager_filter_slot_rects(row_rect: egui::Rect) -> (egui::Rect, egui::Rect) {
    let inner_left = row_rect.left() + TERMINAL_MANAGER_FILTER_SIDE_PADDING;
    let inner_right = (row_rect.right() - TERMINAL_MANAGER_FILTER_SIDE_PADDING).max(inner_left);
    let inner_width = (inner_right - inner_left).max(0.0);
    let center_gap = TERMINAL_MANAGER_FILTER_CENTER_GAP.min(inner_width);
    let slot_width = ((inner_width - center_gap).max(0.0)) * 0.5;

    let foreground_slot_rect = egui::Rect::from_min_max(
        egui::pos2(inner_left, row_rect.top()),
        egui::pos2(inner_left + slot_width, row_rect.bottom()),
    );
    let background_slot_rect = egui::Rect::from_min_max(
        egui::pos2(foreground_slot_rect.right() + center_gap, row_rect.top()),
        egui::pos2(inner_right, row_rect.bottom()),
    );

    (foreground_slot_rect, background_slot_rect)
}

fn terminal_manager_filter_layout(
    row_rect: egui::Rect,
    foreground_label_size: Vec2,
    background_label_size: Vec2,
) -> TerminalManagerFilterLayout {
    let (foreground_slot_rect, background_slot_rect) = terminal_manager_filter_slot_rects(row_rect);

    TerminalManagerFilterLayout {
        foreground_slot_rect,
        background_slot_rect,
        foreground_label_rect: terminal_manager_filter_label_rect(
            foreground_slot_rect,
            foreground_label_size,
        ),
        background_label_rect: terminal_manager_filter_label_rect(
            background_slot_rect,
            background_label_size,
        ),
    }
}

fn terminal_manager_filter_underline_rect(label_rect: egui::Rect) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(
            label_rect.left(),
            label_rect.bottom() + TERMINAL_MANAGER_FILTER_UNDERLINE_GAP,
        ),
        egui::pos2(
            label_rect.right(),
            label_rect.bottom()
                + TERMINAL_MANAGER_FILTER_UNDERLINE_GAP
                + TERMINAL_MANAGER_FILTER_UNDERLINE_HEIGHT,
        ),
    )
}

fn draw_terminal_manager_filter_tabs(
    ui: &mut Ui,
    selected_filter: &mut TerminalManagerFilter,
) -> bool {
    let mut changed = false;

    let row_size = egui::vec2(
        ui.available_width(),
        terminal_manager_filter_row_height(ui.spacing().interact_size.y),
    );
    let (row_rect, _) = ui.allocate_exact_size(row_size, Sense::hover());
    let layout = terminal_manager_filter_layout(
        row_rect,
        terminal_manager_filter_label_size(ui, TerminalManagerFilter::Foreground),
        terminal_manager_filter_label_size(ui, TerminalManagerFilter::Background),
    );

    for (filter, slot_rect, label_rect) in [
        (
            TerminalManagerFilter::Foreground,
            layout.foreground_slot_rect,
            layout.foreground_label_rect,
        ),
        (
            TerminalManagerFilter::Background,
            layout.background_slot_rect,
            layout.background_label_rect,
        ),
    ] {
        let is_selected = *selected_filter == filter;
        let slot_response = ui.interact(
            slot_rect,
            ui.make_persistent_id((
                "terminal-manager-filter-slot",
                terminal_manager_filter_label(filter),
            )),
            Sense::click(),
        );

        let label_response = ui.put(
            label_rect,
            egui::Label::new(
                RichText::new(terminal_manager_filter_label(filter))
                    .strong()
                    .color(if is_selected {
                        terminal_manager_filter_color(filter)
                    } else {
                        with_alpha(TEXT_MUTED, 180)
                    }),
            )
            .truncate()
            .selectable(false)
            .sense(Sense::click()),
        );

        let response = slot_response
            .union(label_response)
            .on_hover_cursor(egui::CursorIcon::PointingHand);

        if is_selected {
            ui.painter().rect_filled(
                terminal_manager_filter_underline_rect(label_rect),
                2.0,
                terminal_manager_filter_color(filter),
            );
        }

        if response.clicked() && !is_selected {
            *selected_filter = filter;
            changed = true;
        }
    }

    changed
}

fn draw_input_history_filter_tabs(ui: &mut Ui, selected_filter: &mut InputHistoryFilter) -> bool {
    let mut changed = false;
    let available_width = ui.available_width();
    let gap = 8.0;
    let tab_count = 3.0;
    let tab_width = ((available_width - gap * (tab_count - 1.0)) / tab_count).max(40.0);

    ui.horizontal(|ui| {
        ui.spacing_mut().item_spacing.x = gap;
        for filter in [
            InputHistoryFilter::All,
            InputHistoryFilter::Foreground,
            InputHistoryFilter::Background,
        ] {
            let is_selected = *selected_filter == filter;
            let text = filter.label();
            let (rect, response) =
                ui.allocate_exact_size(egui::vec2(tab_width, CONTROL_ROW_HEIGHT), Sense::click());
            let response = response.on_hover_cursor(egui::CursorIcon::PointingHand);

            // Background for selected tab
            if is_selected {
                ui.painter().rect_filled(rect.shrink(1.0), 6.0, BTN_ICON);
            } else if response.hovered() {
                ui.painter()
                    .rect_filled(rect.shrink(1.0), 6.0, with_alpha(BTN_ICON_HOVER, 80));
            }

            // Text
            ui.painter().text(
                rect.center(),
                egui::Align2::CENTER_CENTER,
                text,
                egui::FontId::proportional(13.0),
                if is_selected {
                    TEXT_PRIMARY
                } else {
                    TEXT_MUTED
                },
            );

            if response.clicked() && !is_selected {
                *selected_filter = filter;
                changed = true;
            }
        }
    });

    changed
}

fn format_relative_time(timestamp: u64) -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let diff = now.saturating_sub(timestamp);

    if diff < 60 {
        "just now".to_owned()
    } else if diff < 3600 {
        format!("{}m ago", diff / 60)
    } else if diff < 86400 {
        format!("{}h ago", diff / 3600)
    } else if diff < 604800 {
        format!("{}d ago", diff / 86400)
    } else if diff < 2592000 {
        format!("{}w ago", diff / 604800)
    } else {
        format!("{}mo ago", diff / 2592000)
    }
}

fn terminal_ids_for_project_kind(
    terminals: &BTreeMap<u64, TerminalEntry>,
    project_id: u64,
    kind: TerminalKind,
) -> Vec<u64> {
    terminals
        .iter()
        .filter(|(_, terminal)| terminal.project_id == project_id && terminal.kind == kind)
        .map(|(id, _)| *id)
        .collect()
}

fn project_group_header_row_layout(
    action_kind: TerminalKind,
    total_width: f32,
    section_gap: f32,
) -> (f32, f32) {
    let total_width = total_width.max(0.0);
    let section_gap = section_gap.max(0.0);
    let actions_width =
        project_group_header_actions_width(action_kind, section_gap).min(total_width);
    let label_width = (total_width - actions_width - section_gap).max(0.0);
    (label_width, actions_width)
}

fn draw_project_group_header(
    app: &mut AdeApp,
    ui: &mut Ui,
    _project_id: u64,
    project_name: &str,
    open: bool,
    can_expand: bool,
    action_kind: TerminalKind,
    foreground_launchers: &[LauncherEntry],
    diff_summary: &TerminalManagerDiffSummaryModel,
    has_live_terminal: bool,
    create_worktree_clicked: &mut bool,
) -> (egui::Response, bool, Option<String>, bool) {
    let row_width = ui.available_width();
    let section_gap = ui.spacing().item_spacing.x;
    let (_label_width, actions_width) =
        project_group_header_row_layout(action_kind, row_width, section_gap);
    let row_height = CONTROL_ROW_HEIGHT;

    // Allocate the full row for visual layout, but we'll create separate interactions
    let (_, row_rect) = ui.allocate_space(egui::vec2(row_width, row_height));

    // Calculate action buttons rect
    let actions_rect = egui::Rect::from_min_size(
        egui::pos2(row_rect.right() - actions_width, row_rect.top()),
        egui::vec2(actions_width, row_height),
    );
    let _action_hover_response = ui
        .interact(
            actions_rect,
            ui.id().with(("project_group_action", project_name)),
            Sense::hover(),
        )
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    // Create interaction area for the non-button portion of the row (for click)
    let body_rect = egui::Rect::from_min_size(
        row_rect.min,
        egui::vec2(row_width - actions_width, row_height),
    );

    let body_response = ui.interact(
        body_rect,
        ui.id().with(("project_group_body", project_name)),
        Sense::click(),
    );

    // Set hover cursor based on expandability
    let body_response = if can_expand {
        body_response.on_hover_cursor(egui::CursorIcon::PointingHand)
    } else {
        body_response
    };

    // Project header is bright only when it has at least one live (non-exited) terminal.
    // When all terminals are closed/exited, the project header dims back to muted color.
    let text_color = if has_live_terminal {
        TEXT_PRIMARY
    } else if body_response.hovered() {
        with_alpha(TEXT_MUTED, 180)
    } else {
        with_alpha(TEXT_MUTED, 180)
    };

    let mut spawn_clicked = false;
    let mut selected_launcher_id = None;

    // Draw label content
    let label_rect = egui::Rect::from_min_size(
        body_rect.min,
        egui::vec2(body_rect.width().max(0.0), row_height),
    );
    if label_rect.width() > 0.0 && ui.is_rect_visible(label_rect) {
        ui.scope_builder(
            egui::UiBuilder::new()
                .max_rect(label_rect)
                .layout(Layout::left_to_right(Align::Center)),
            |ui| {
                let label = project_name.to_string();
                let _ = draw_terminal_manager_title_and_diff_summary(
                    ui,
                    &label,
                    text_color,
                    open,
                    row_height,
                    diff_summary,
                    can_expand,
                    Some(project_name),
                );
            },
        );
    }

    // Draw action buttons in separate scope
    ui.scope_builder(
        egui::UiBuilder::new()
            .max_rect(actions_rect)
            .layout(Layout::right_to_left(Align::Center)),
        |ui| {
            let (icon, bg, hover_bg, tooltip) = project_group_header_action_spec(action_kind);
            if action_kind == TerminalKind::Foreground {
                selected_launcher_id = styled_launcher_menu_button(
                    app,
                    ui,
                    icon,
                    bg,
                    hover_bg,
                    BTN_ICON_ACTIVE,
                    tooltip,
                    foreground_launchers,
                );
                if styled_icon_button(
                    ui,
                    icons::FOLDER_PLUS,
                    BTN_TEAL,
                    BTN_TEAL_HOVER,
                    BTN_ICON_ACTIVE,
                    "Create Worktree",
                ) {
                    *create_worktree_clicked = true;
                }
            } else if styled_icon_button(ui, icon, bg, hover_bg, BTN_ICON_ACTIVE, tooltip) {
                spawn_clicked = true;
            }
        },
    );

    // Determine header click - only if body was clicked and no action was taken
    let header_clicked = body_response.clicked()
        && !spawn_clicked
        && selected_launcher_id.is_none()
        && !*create_worktree_clicked;

    (
        body_response,
        spawn_clicked,
        selected_launcher_id,
        header_clicked,
    )
}

fn styled_icon_button(
    ui: &mut Ui,
    icon: AppIcon,
    _bg: Color32,
    _hover_bg: Color32,
    _active_bg: Color32,
    tooltip: &str,
) -> bool {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );
    let response = response
        .on_hover_text(tooltip)
        .on_hover_cursor(egui::CursorIcon::PointingHand);

    if response.hovered() {
        ui.painter()
            .rect_filled(rect.shrink(2.0), 8.0, with_alpha(BTN_ICON_HOVER, 110));
    }

    let icon_color = if response.is_pointer_button_down_on() || response.hovered() {
        TEXT_PRIMARY
    } else {
        with_alpha(TEXT_PRIMARY, 178)
    };
    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{icon}"),
        egui::FontId::proportional(14.0),
        icon_color,
    );

    response.clicked()
}

/// Browser toolbar icon button with tooltip shown centered above the button.
/// Unlike standard tooltips that appear below (which can overlap WebView),
/// this helper positions the tooltip centered above to avoid z-order issues.
fn browser_toolbar_icon_button(ui: &mut Ui, icon: AppIcon, tooltip: &str) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );

    // Show custom tooltip centered above the button when hovered
    if response.hovered() {
        ui.painter()
            .rect_filled(rect.shrink(1.0), 8.0, with_alpha(BTN_ICON_HOVER, 110));

        let tooltip_id = ui.make_persistent_id(("browser_toolbar_tooltip", response.id));
        let tooltip_anchor = rect.center_top() + egui::vec2(0.0, -BROWSER_TOOLBAR_TOOLTIP_GAP);

        // Use Area with CENTER_BOTTOM pivot so tooltip is centered horizontally above the anchor
        let ctx = ui.ctx();
        egui::Area::new(tooltip_id)
            .kind(egui::UiKind::Tooltip)
            .order(egui::Order::Tooltip)
            .pivot(egui::Align2::CENTER_BOTTOM)
            .fixed_pos(tooltip_anchor)
            .default_width(ctx.style().spacing.tooltip_width)
            .sense(egui::Sense::hover())
            .show(ctx, |ui| {
                egui::Frame::popup(&ctx.style()).show(ui, |ui| {
                    ui.style_mut().interaction.selectable_labels = false;
                    ui.label(tooltip);
                });
            });
    }

    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{icon}"),
        egui::FontId::proportional(15.0),
        if response.is_pointer_button_down_on() || response.hovered() {
            TEXT_PRIMARY
        } else {
            with_alpha(TEXT_PRIMARY, 178)
        },
    );

    response
}

fn apply_browser_url_selection_visuals(style: &mut egui::Style) {
    style.visuals.selection.bg_fill = BROWSER_URL_SELECTION_BG;
    style.visuals.selection.stroke = Stroke::new(1.0, BROWSER_URL_SELECTION_STROKE);
    style.visuals.override_text_color = Some(TEXT_PRIMARY);
}

/// Browser toolbar toggle button with tooltip shown centered above.
/// Supports ON/OFF state visualization like Design Inspect toggle.
fn browser_toolbar_toggle_button(
    ui: &mut Ui,
    selected: bool,
    icon: AppIcon,
    tooltip: &str,
) -> egui::Response {
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(CONTROL_ROW_HEIGHT, CONTROL_ROW_HEIGHT),
        Sense::click(),
    );

    // Show custom tooltip centered above the button when hovered
    if response.hovered() {
        ui.painter()
            .rect_filled(rect.shrink(1.0), 8.0, with_alpha(BTN_ICON_HOVER, 110));

        let tooltip_id = ui.make_persistent_id(("browser_toolbar_tooltip", response.id));
        let tooltip_anchor = rect.center_top() + egui::vec2(0.0, -BROWSER_TOOLBAR_TOOLTIP_GAP);

        // Use Area with CENTER_BOTTOM pivot so tooltip is centered horizontally above the anchor
        let ctx = ui.ctx();
        egui::Area::new(tooltip_id)
            .kind(egui::UiKind::Tooltip)
            .order(egui::Order::Tooltip)
            .pivot(egui::Align2::CENTER_BOTTOM)
            .fixed_pos(tooltip_anchor)
            .default_width(ctx.style().spacing.tooltip_width)
            .sense(egui::Sense::hover())
            .show(ctx, |ui| {
                egui::Frame::popup(&ctx.style()).show(ui, |ui| {
                    ui.style_mut().interaction.selectable_labels = false;
                    ui.label(tooltip);
                });
            });
    }

    let icon_color = if selected || response.hovered() || response.is_pointer_button_down_on() {
        TEXT_PRIMARY
    } else {
        with_alpha(TEXT_PRIMARY, 170)
    };
    ui.painter().text(
        rect.center(),
        egui::Align2::CENTER_CENTER,
        format!("{icon}"),
        egui::FontId::proportional(14.0),
        icon_color,
    );

    response
}

/// Show a tooltip centered above the given widget response.
/// Helper for custom buttons that need tooltip positioning centered above the widget.
fn show_tooltip_above(ui: &mut Ui, response: &egui::Response, tooltip: &str) {
    show_tooltip_above_at(ui, response.id, response.rect, tooltip, response.hovered());
}

fn show_tooltip_above_at(ui: &mut Ui, id: egui::Id, rect: egui::Rect, tooltip: &str, show: bool) {
    if !show {
        return;
    }

    let tooltip_id = ui.make_persistent_id(("browser_tooltip_above", id));
    let tooltip_anchor = rect.center_top() + egui::vec2(0.0, -BROWSER_TOOLBAR_TOOLTIP_GAP);

    // Use Area with CENTER_BOTTOM pivot so tooltip is centered horizontally above the anchor.
    // No .sense() is set so the tooltip does not capture hover; this prevents flicker
    // caused by the tooltip stealing hover from the underlying widget.
    let ctx = ui.ctx();
    egui::Area::new(tooltip_id)
        .kind(egui::UiKind::Tooltip)
        .order(egui::Order::Tooltip)
        .pivot(egui::Align2::CENTER_BOTTOM)
        .fixed_pos(tooltip_anchor)
        .default_width(ctx.style().spacing.tooltip_width)
        .show(ctx, |ui| {
            egui::Frame::popup(&ctx.style()).show(ui, |ui| {
                ui.style_mut().interaction.selectable_labels = false;
                ui.label(tooltip);
            });
        });
}

/// Variant of `styled_icon_button` that returns the full Response for hover tracking.
