fn show_settings_card<R>(
    ui: &mut Ui,
    icon: AppIcon,
    title: &str,
    description: &str,
    add_contents: impl FnOnce(&mut Ui) -> R,
) -> R {
    settings_surface_frame(with_alpha(SURFACE_BG_SOFT, 228), 12.0)
        .show(ui, |ui| {
            ui.label(
                RichText::new(format!("{icon} {title}"))
                    .strong()
                    .size(15.0)
                    .color(TEXT_PRIMARY),
            );
            if !description.is_empty() {
                ui.label(RichText::new(description).small().color(TEXT_MUTED));
                ui.add_space(10.0);
            }
            add_contents(ui)
        })
        .inner
}

fn sanitize_design_inspect_value(value: &str, max_chars: usize) -> String {
    let mut result = String::new();
    let mut pending_space = false;
    let mut chars_written = 0usize;

    for ch in value.chars() {
        let normalized = if ch.is_control() { ' ' } else { ch };
        if normalized.is_whitespace() {
            pending_space = !result.is_empty();
            continue;
        }

        if pending_space {
            if chars_written >= max_chars {
                result.push_str("...");
                return result;
            }
            result.push(' ');
            chars_written += 1;
            pending_space = false;
        }

        if chars_written >= max_chars {
            result.push_str("...");
            return result;
        }
        result.push(normalized);
        chars_written += 1;
    }

    result
}

fn design_inspect_element_label(info: &web_browser::DesignElementInfo) -> String {
    let tag = sanitize_design_inspect_value(&info.tag, 40).to_lowercase();
    let id = sanitize_design_inspect_value(&info.id, 80);
    let classes = info
        .classes
        .iter()
        .take(4)
        .map(|class_name| sanitize_design_inspect_value(class_name, 60))
        .filter(|class_name| !class_name.is_empty())
        .map(|class_name| format!(".{class_name}"))
        .collect::<String>();

    if id.is_empty() {
        format!("{tag}{classes}")
    } else {
        format!("{tag}#{id}{classes}")
    }
}

fn design_inspect_styles_text(styles: &BTreeMap<String, String>) -> String {
    const STYLE_KEYS: [&str; 11] = [
        "display",
        "position",
        "margin",
        "padding",
        "font",
        "color",
        "background-color",
        "border",
        "border-radius",
        "z-index",
        "transform",
    ];

    STYLE_KEYS
        .iter()
        .filter_map(|key| {
            styles.get(*key).map(|value| {
                format!(
                    "{key}: {}",
                    sanitize_design_inspect_value(value, DESIGN_INSPECT_MAX_FIELD_CHARS)
                )
            })
        })
        .collect::<Vec<_>>()
        .join("; ")
}

fn design_inspect_delivery_signature(info: &web_browser::DesignElementInfo) -> String {
    // Use mcp_ref for deduplication when available, otherwise fall back to selector
    let unique_key = if info.mcp_ref.is_empty() {
        &info.selector
    } else {
        &info.mcp_ref
    };
    format!("{}|{}|{}", info.page_url, info.url, unique_key)
}

fn design_inspect_matches_current_page(
    current_url: &str,
    info: &web_browser::DesignElementInfo,
) -> bool {
    let observed_page_url = if info.page_url.is_empty() {
        info.url.as_str()
    } else {
        info.page_url.as_str()
    };
    current_url == observed_page_url
}

fn design_inspect_should_deliver(
    last: Option<&DesignInspectDeliveryState>,
    signature: &str,
    now: Instant,
) -> bool {
    !last.is_some_and(|last| {
        last.signature == signature
            && now.saturating_duration_since(last.delivered_at)
                < Duration::from_millis(DESIGN_INSPECT_DELIVERY_DEDUPE_MS)
    })
}

fn format_design_inspect_terminal_text(info: &web_browser::DesignElementInfo) -> String {
    let element = design_inspect_element_label(info);
    let selector = sanitize_design_inspect_value(&info.selector, DESIGN_INSPECT_MAX_FIELD_CHARS);
    let text = sanitize_design_inspect_value(&info.text, DESIGN_INSPECT_MAX_TEXT_CHARS);
    let styles = design_inspect_styles_text(&info.styles);
    let url = sanitize_design_inspect_value(&info.url, DESIGN_INSPECT_MAX_FIELD_CHARS);
    let page_url = sanitize_design_inspect_value(&info.page_url, DESIGN_INSPECT_MAX_FIELD_CHARS);
    let url = if !page_url.is_empty() && page_url != url {
        format!("{url}; page={page_url}")
    } else {
        url
    };
    // Use MCP ref if available, otherwise indicate selector should be used
    let ref_hint = if info.mcp_ref.is_empty() {
        format!("selector=\"{selector}\"")
    } else {
        format!("ref=\"{}\"", info.mcp_ref)
    };

    format!(
        "Design inspect: element=\"{element}\" {ref_hint} text=\"{text}\" styles=\"{styles}\" url=\"{url}\" | Use browser_click {ref_hint} | Change request: ",
    )
}

/// Normalize user input into a valid browser URL.
/// - Adds https:// for regular domains
/// - Uses http:// for localhost/127.0.0.1/0.0.0.0/[::1]
/// - Rejects unsupported schemes (file:, data:, javascript:)
/// - Returns empty string for invalid input
fn normalize_browser_url(input: &str) -> String {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return String::new();
    }

    // Check for unsupported schemes
    let lower = trimmed.to_lowercase();
    if lower.starts_with("file:")
        || lower.starts_with("data:")
        || lower.starts_with("javascript:")
        || lower.starts_with("ftp:")
    {
        return String::new();
    }

    // Already has http:// or https://
    if lower.starts_with("http://") || lower.starts_with("https://") {
        return trimmed.to_owned();
    }

    // Check exact localhost/IP hosts - use http
    let is_local = browser_url_input_host(trimmed).is_some_and(|host| {
        matches!(
            host.to_lowercase().as_str(),
            "localhost" | "127.0.0.1" | "0.0.0.0" | "[::1]" | "[::]"
        )
    });

    if is_local {
        format!("http://{trimmed}")
    } else {
        // Regular domain - use https
        format!("https://{trimmed}")
    }
}

fn browser_url_input_host(input: &str) -> Option<&str> {
    let authority = input
        .split(['/', '?', '#'])
        .next()
        .filter(|authority| !authority.is_empty())?;
    if authority.starts_with('[') {
        let close_idx = authority.find(']')?;
        let host_end = close_idx + 1;
        let remainder = &authority[host_end..];
        if remainder.is_empty() || remainder.starts_with(':') {
            return Some(&authority[..host_end]);
        }
        return Some(authority);
    }

    Some(authority.split(':').next().unwrap_or(authority))
}

fn resolve_ctrl_c_action(can_copy_selection: bool) -> CtrlCAction {
    if can_copy_selection {
        CtrlCAction::CopySelection
    } else {
        CtrlCAction::SendInterrupt
    }
}

fn terminal_secondary_click_action(
    has_selection: bool,
    can_paste: bool,
) -> TerminalSecondaryClickAction {
    if has_selection {
        TerminalSecondaryClickAction::OpenCopyMenu
    } else if can_paste {
        TerminalSecondaryClickAction::PasteImmediately
    } else {
        TerminalSecondaryClickAction::None
    }
}

fn primary_shortcut_modifier(modifiers: egui::Modifiers) -> bool {
    modifiers.ctrl || modifiers.command
}

fn terminal_link_activation_modifiers(modifiers: egui::Modifiers) -> bool {
    primary_shortcut_modifier(modifiers) && !modifiers.alt && !modifiers.shift
}

fn terminal_link_rules() -> &'static [Rule] {
    static RULES: OnceLock<Vec<Rule>> = OnceLock::new();
    RULES
        .get_or_init(|| {
            vec![
                Rule::new(CLOSING_PARENTHESIS_HYPERLINK_PATTERN, "$0")
                    .expect("valid closing-parenthesis terminal hyperlink regex"),
                Rule::new(GENERIC_HYPERLINK_PATTERN, "$0")
                    .expect("valid generic terminal hyperlink regex"),
            ]
        })
        .as_slice()
}

fn terminal_link_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<String> {
    terminal_explicit_link_at_point(snapshot, point)
        .or_else(|| terminal_text_link_at_point(snapshot, point))
}

fn terminal_explicit_link_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<String> {
    terminal_selection_hyperlink_at_point(snapshot, point)
        .filter(|uri| terminal_link_uri_allowed(uri))
        .map(str::to_owned)
}

fn terminal_text_link_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<String> {
    let logical_line = terminal_logical_line(snapshot, point.row)?;
    let byte_index = terminal_logical_line_byte_index(&logical_line, point)?;
    Rule::match_hyperlinks(&logical_line.text, terminal_link_rules())
        .into_iter()
        .find(|matched| {
            matched.range.contains(&byte_index) && terminal_link_uri_allowed(matched.link.uri())
        })
        .map(|matched| matched.link.uri().to_owned())
}

fn terminal_link_uri_allowed(uri: &str) -> bool {
    terminal_link_has_ascii_case_insensitive_prefix(uri, "http://")
        || terminal_link_has_ascii_case_insensitive_prefix(uri, "https://")
}

fn terminal_link_has_ascii_case_insensitive_prefix(uri: &str, prefix: &str) -> bool {
    uri.get(..prefix.len())
        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(prefix))
}

fn terminal_selection_hyperlink_at_point(
    snapshot: &TerminalSelectionSnapshot,
    point: TerminalSelectionPoint,
) -> Option<&str> {
    snapshot
        .lines
        .get(point.row)?
        .hyperlinks
        .iter()
        .find(|hyperlink| {
            point.column >= hyperlink.start_column && point.column < hyperlink.end_column
        })
        .map(|hyperlink| hyperlink.uri.as_str())
}

fn should_resolve_terminal_link(
    link_activation_modifiers_active: bool,
    primary_pressed_on_terminal: bool,
    has_pending_link_click: bool,
) -> bool {
    link_activation_modifiers_active || primary_pressed_on_terminal || has_pending_link_click
}

fn terminal_logical_line(
    snapshot: &TerminalSelectionSnapshot,
    row: usize,
) -> Option<TerminalLogicalLine> {
    let (start_row, end_row) = terminal_logical_line_row_range(snapshot, row)?;
    let mut logical_line = TerminalLogicalLine::default();

    for row in start_row..=end_row {
        append_terminal_logical_line_row(
            &mut logical_line.text,
            &mut logical_line.segments,
            row,
            &snapshot.lines[row],
        );
    }

    Some(logical_line)
}

fn terminal_logical_line_row_range(
    snapshot: &TerminalSelectionSnapshot,
    row: usize,
) -> Option<(usize, usize)> {
    if row >= snapshot.lines.len() {
        return None;
    }

    let mut start_row = row;
    while start_row > 0 && snapshot.lines[start_row - 1].wraps_to_next {
        start_row -= 1;
    }

    let mut end_row = row;
    while end_row + 1 < snapshot.lines.len() && snapshot.lines[end_row].wraps_to_next {
        end_row += 1;
    }

    Some((start_row, end_row))
}

fn append_terminal_logical_line_row(
    text: &mut String,
    segments: &mut Vec<TerminalLinkSegment>,
    row: usize,
    line: &TerminalSelectionLine,
) {
    let mut column = 0;

    for cell in &line.cells {
        if cell.column > column {
            append_terminal_logical_segment(
                text,
                segments,
                row,
                column,
                cell.column.min(line.width),
                &" ".repeat(cell.column.min(line.width).saturating_sub(column)),
            );
            column = cell.column.min(line.width);
        }

        let end_column = cell
            .column
            .saturating_add(cell.display_width.max(1))
            .min(line.width);
        if end_column <= cell.column {
            continue;
        }

        append_terminal_logical_segment(
            text,
            segments,
            row,
            cell.column,
            end_column,
            &cell.rendered_text(),
        );
        column = end_column;
    }

    if column < line.width {
        append_terminal_logical_segment(
            text,
            segments,
            row,
            column,
            line.width,
            &" ".repeat(line.width - column),
        );
    }
}

fn append_terminal_logical_segment(
    text: &mut String,
    segments: &mut Vec<TerminalLinkSegment>,
    row: usize,
    start_column: usize,
    end_column: usize,
    segment_text: &str,
) {
    if end_column <= start_column || segment_text.is_empty() {
        return;
    }

    let byte_start = text.len();
    text.push_str(segment_text);
    segments.push(TerminalLinkSegment {
        row,
        start_column,
        end_column,
        byte_range: byte_start..text.len(),
    });
}

fn terminal_logical_line_byte_index(
    logical_line: &TerminalLogicalLine,
    point: TerminalSelectionPoint,
) -> Option<usize> {
    let segment = logical_line.segments.iter().find(|segment| {
        segment.row == point.row
            && point.column >= segment.start_column
            && point.column < segment.end_column
    })?;
    let segment_text = &logical_line.text[segment.byte_range.clone()];
    let byte_offset =
        byte_index_for_display_column(segment_text, point.column - segment.start_column);
    Some(segment.byte_range.start + byte_offset)
}

fn byte_index_for_display_column(text: &str, column_offset: usize) -> usize {
    if column_offset == 0 {
        return 0;
    }

    let mut seen_columns = 0;
    for (byte_index, ch) in text.char_indices() {
        if seen_columns >= column_offset {
            return byte_index;
        }

        let width = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if width == 0 {
            continue;
        }

        let next_columns = seen_columns.saturating_add(width);
        if next_columns > column_offset {
            return byte_index;
        }

        seen_columns = next_columns;
    }

    text.len()
}

fn terminal_selection_point_from_pointer(
    pointer_pos: Option<egui::Pos2>,
    origin: egui::Pos2,
    snapshot: &TerminalSelectionSnapshot,
    char_width: f32,
    galley: &Galley,
) -> Option<TerminalSelectionPoint> {
    let pointer_pos = pointer_pos?;
    if snapshot.lines.is_empty() || galley.rows.is_empty() || char_width <= 0.0 {
        return None;
    }

    let max_row = snapshot
        .lines
        .len()
        .saturating_sub(1)
        .min(galley.rows.len().saturating_sub(1));
    let cursor = galley.cursor_from_pos(pointer_pos - origin);
    let row = cursor.rcursor.row.min(max_row);
    let line_width = terminal_selection_line_width(&snapshot.lines[row]);
    let column =
        (((pointer_pos.x - origin.x).max(0.0) / char_width).floor() as usize).min(line_width);

    Some(TerminalSelectionPoint { row, column })
}

fn terminal_selection_row_rect(
    galley: &Galley,
    origin: egui::Pos2,
    row: usize,
) -> Option<egui::Rect> {
    galley
        .rows
        .get(row)
        .map(|galley_row| galley_row.rect.translate(origin.to_vec2()))
}

fn terminal_cell_metric(metric: f32) -> f32 {
    if metric.is_finite() {
        metric.max(1.0)
    } else {
        1.0
    }
}

fn average_terminal_cell_width(sample_width: f32, sample_cells: usize) -> f32 {
    let sample_cells = sample_cells.max(1) as f32;
    terminal_cell_metric(sample_width / sample_cells)
}

fn terminal_font_family() -> FontFamily {
    FontFamily::Name(TERMINAL_FONT_FAMILY_NAME.into())
}

fn terminal_font_id(style: &egui::Style) -> FontId {
    let mut font_id = egui::TextStyle::Monospace.resolve(style);
    font_id.family = terminal_font_family();
    font_id
}

fn terminal_line_height(ui: &Ui, font_id: &FontId) -> f32 {
    terminal_cell_metric(ui.fonts(|fonts| fonts.row_height(font_id)))
}

fn terminal_char_width(ui: &Ui, font_id: &FontId) -> f32 {
    let sample_width = ui.fonts(|fonts| {
        let mut layout_job = LayoutJob::default();
        layout_job.wrap.max_width = f32::INFINITY;
        layout_job.append(
            &"W".repeat(TERMINAL_CHAR_WIDTH_SAMPLE_CELLS),
            0.0,
            TextFormat {
                font_id: font_id.clone(),
                ..TextFormat::default()
            },
        );
        fonts.layout_job(layout_job).size().x
    });
    average_terminal_cell_width(sample_width, TERMINAL_CHAR_WIDTH_SAMPLE_CELLS)
}

fn configure_terminal_font_family(fonts: &mut egui::FontDefinitions) {
    let fallback_font_names = load_terminal_fallback_font_names(fonts);
    install_terminal_font_family(fonts, &fallback_font_names);
}

fn install_terminal_font_family(fonts: &mut egui::FontDefinitions, fallback_font_names: &[String]) {
    let icon_font_names = icon_fonts()
        .iter()
        .map(|asset| asset.family.to_owned())
        .collect::<HashSet<_>>();
    let mut terminal_family = Vec::new();
    let mut seen_font_names = HashSet::new();

    for font_name in fallback_font_names.iter().chain(
        fonts
            .families
            .get(&FontFamily::Monospace)
            .into_iter()
            .flatten(),
    ) {
        if icon_font_names.contains(font_name) || !fonts.font_data.contains_key(font_name) {
            continue;
        }

        if seen_font_names.insert(font_name.clone()) {
            terminal_family.push(font_name.clone());
        }
    }

    fonts
        .families
        .insert(terminal_font_family(), terminal_family);
}

#[cfg(target_os = "windows")]
fn windows_terminal_font_candidates() -> &'static [(&'static str, &'static str)] {
    &WINDOWS_TERMINAL_FONT_CANDIDATES
}

#[cfg(target_os = "windows")]
fn load_terminal_fallback_font_names(fonts: &mut egui::FontDefinitions) -> Vec<String> {
    let fonts_dir = std::env::var_os("WINDIR")
        .map(PathBuf::from)
        .map(|windir| windir.join("Fonts"))
        .unwrap_or_else(|| PathBuf::from(r"C:\Windows\Fonts"));
    let mut loaded_font_names = Vec::new();

    // Load embedded Nerd Font for terminal icon support
    fonts.font_data.insert(
        NERD_FONT_NAME.to_owned(),
        FontData::from_owned(NERD_FONT_DATA.to_vec()),
    );
    loaded_font_names.push(NERD_FONT_NAME.to_owned());

    for (font_name, file_name) in windows_terminal_font_candidates() {
        let font_path = fonts_dir.join(file_name);
        let Ok(font_bytes) = fs::read(&font_path) else {
            continue;
        };

        fonts
            .font_data
            .insert((*font_name).to_owned(), FontData::from_owned(font_bytes));
        loaded_font_names.push((*font_name).to_owned());
    }

    loaded_font_names
}

#[cfg(not(target_os = "windows"))]
fn load_terminal_fallback_font_names(_fonts: &mut egui::FontDefinitions) -> Vec<String> {
    Vec::new()
}

fn terminal_grid_dimensions(output_size: Vec2, char_width: f32, line_height: f32) -> (u16, u16) {
    let char_width = terminal_cell_metric(char_width);
    let line_height = terminal_cell_metric(line_height);
    let cols = ((output_size.x.max(0.0) / char_width).floor() as u16).max(8);
    let lines = ((output_size.y.max(0.0) / line_height).floor() as u16).max(3);
    (cols, lines)
}

fn force_terminal_pane_width(ui: &mut Ui, pane_width: f32) -> f32 {
    let pane_width = pane_width.max(0.0);
    let pane_right = ui.max_rect().left() + pane_width;
    ui.set_width(pane_width);
    ui.set_min_width(pane_width);
    ui.expand_to_include_x(pane_right);
    pane_right
}

fn terminal_output_viewport_size(output_size: Vec2) -> Vec2 {
    egui::vec2(output_size.x.max(0.0), output_size.y.max(0.0))
}

fn terminal_output_surface_size(output_size: Vec2, content_height: f32) -> Vec2 {
    egui::vec2(
        output_size.x.max(0.0),
        output_size.y.max(content_height.max(0.0)),
    )
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct TerminalOutputScrollBehavior {
    vertical_offset: Option<f32>,
    stick_to_bottom: bool,
    keep_activation_alignment_pending: bool,
}

fn terminal_output_scroll_behavior(
    terminal: &TerminalEntry,
    line_height: f32,
    viewport_height: f32,
) -> TerminalOutputScrollBehavior {
    let has_content = !terminal.render_cache.lines.is_empty();
    let activation_offset = terminal
        .activation_scroll_align_pending
        .then(|| {
            terminal_activation_scroll_offset(
                &terminal.render_cache,
                terminal.stable_input_cursor_row,
                line_height,
                viewport_height,
            )
        })
        .flatten();
    let prompt_anchor_offset = activation_offset.or_else(|| {
        terminal_prompt_scroll_anchor_enabled(terminal)
            .then(|| {
                terminal_activation_scroll_offset(
                    &terminal.render_cache,
                    terminal.stable_input_cursor_row,
                    line_height,
                    viewport_height,
                )
            })
            .flatten()
    });

    // Disable stick_to_bottom while selection drag is active to allow autoscroll.
    // Also disable it for OpenCode when the user has manually scrolled away from bottom.
    let selection_drag_active = terminal.selection_drag_active;
    let opencode_manual_scroll = terminal.ai_session.tool == Some(AiCliTool::OpenCode)
        && terminal.opencode_manual_scroll_detached;

    TerminalOutputScrollBehavior {
        vertical_offset: prompt_anchor_offset,
        stick_to_bottom: has_content
            && prompt_anchor_offset.is_none()
            && !selection_drag_active
            && !opencode_manual_scroll,
        keep_activation_alignment_pending: terminal.activation_scroll_align_pending && !has_content,
    }
}

fn terminal_prompt_scroll_anchor_enabled(terminal: &TerminalEntry) -> bool {
    terminal.ai_session.tool == Some(AiCliTool::CodexCli)
        && !terminal.prompt_scroll_anchor_detached
        && (terminal.codex_session_active
            || terminal.codex_launch_pending_since.is_some()
            || terminal.ai_session.status != AiCliStatus::Inactive)
}

fn reset_terminal_prompt_scroll_anchor(terminal: &mut TerminalEntry) {
    terminal.prompt_scroll_anchor_detached = false;
}

fn detach_terminal_prompt_scroll_anchor_on_manual_scroll(terminal: &mut TerminalEntry) {
    if terminal_prompt_scroll_anchor_enabled(terminal) {
        terminal.prompt_scroll_anchor_detached = true;
    }
}

fn reset_opencode_manual_scroll_detached(terminal: &mut TerminalEntry) {
    terminal.opencode_manual_scroll_detached = false;
}

fn opencode_terminal_wheel_fallback_enabled(terminal: &TerminalEntry) -> bool {
    terminal.ai_session.tool == Some(AiCliTool::OpenCode)
        && terminal.ai_session.status == AiCliStatus::Running
}

fn terminal_activation_scroll_offset(
    snapshot: &TerminalSnapshot,
    stable_input_cursor_row: Option<usize>,
    line_height: f32,
    viewport_height: f32,
) -> Option<f32> {
    if snapshot.lines.is_empty() {
        return None;
    }

    let max_row = snapshot.lines.len().saturating_sub(1);
    let clamped_target_row =
        terminal_scroll_anchor_row(snapshot, stable_input_cursor_row)?.min(max_row);
    let content_height = snapshot.lines.len() as f32 * line_height.max(0.0);
    let max_offset = (content_height - viewport_height.max(0.0)).max(0.0);
    let visible_rows = if line_height > 0.0 {
        (viewport_height.max(0.0) / line_height).floor().max(1.0) as usize
    } else {
        1
    };
    let preferred_top_row = clamped_target_row
        .saturating_add(1)
        .saturating_sub(visible_rows);
    Some((preferred_top_row as f32 * line_height.max(0.0)).clamp(0.0, max_offset))
}

fn terminal_scroll_anchor_row(
    snapshot: &TerminalSnapshot,
    stable_input_cursor_row: Option<usize>,
) -> Option<usize> {
    if snapshot.lines.is_empty() {
        return None;
    }

    let max_row = snapshot.lines.len().saturating_sub(1);
    let prompt_row = stable_input_cursor_row
        .filter(|row| *row <= max_row)
        .or_else(|| {
            snapshot
                .cursor
                .map(|cursor| cursor.y)
                .filter(|row| *row <= max_row)
        });
    let last_non_empty_row = terminal_last_non_empty_row(snapshot);

    match (prompt_row, last_non_empty_row) {
        (Some(prompt_row), Some(last_non_empty_row)) => Some(prompt_row.max(last_non_empty_row)),
        (Some(prompt_row), None) => Some(prompt_row),
        (None, Some(last_non_empty_row)) => Some(last_non_empty_row),
        (None, None) => stable_input_cursor_row
            .or_else(|| snapshot.cursor.map(|cursor| cursor.y))
            .map(|row| row.min(max_row)),
    }
}

/// Calculates autoscroll delta for selection drag when pointer is near viewport edges.
/// This is a generic helper used by both terminal and file editor selection workflows.
///
/// Returns positive value to scroll up (content moves up, revealing content above)
/// or negative value to scroll down (content moves down, revealing content below).
/// Returns 0.0 when pointer is in the safe zone.
fn selection_edge_autoscroll_delta(
    pointer_pos: Option<egui::Pos2>,
    viewport_rect: egui::Rect,
    line_height: f32,
) -> f32 {
    let Some(pos) = pointer_pos else {
        return 0.0;
    };

    if !line_height.is_finite() || line_height <= 0.0 {
        return 0.0;
    }

    // Safety zone margin from viewport edges
    const SAFETY_ZONE_LINES: f32 = 1.5;
    let safety_margin = line_height * SAFETY_ZONE_LINES;

    // Check if pointer is above the top edge (outside viewport)
    let distance_above = viewport_rect.min.y - pos.y;
    if distance_above > 0.0 {
        // Pointer is above the viewport - scroll up (positive delta)
        let proximity = safety_margin + distance_above;
        return selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Check if pointer is near the top edge (within safety margin inside viewport)
    let distance_from_top = pos.y - viewport_rect.min.y;
    if distance_from_top < safety_margin {
        // Pointer is near the top edge inside viewport - scroll up (positive delta)
        let proximity = safety_margin - distance_from_top;
        return selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Check if pointer is below the bottom edge (outside viewport)
    let distance_below = pos.y - viewport_rect.max.y;
    if distance_below > 0.0 {
        // Pointer is below the viewport - scroll down (negative delta)
        let proximity = safety_margin + distance_below;
        return -selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Check if pointer is near the bottom edge (within safety margin inside viewport)
    let distance_from_bottom = viewport_rect.max.y - pos.y;
    if distance_from_bottom < safety_margin {
        // Pointer is near the bottom edge inside viewport - scroll down (negative delta)
        let proximity = safety_margin - distance_from_bottom;
        return -selection_edge_autoscroll_speed(proximity, line_height);
    }

    // Pointer is in the safe zone (neither near top nor bottom)
    0.0
}

/// Calculates autoscroll speed based on pointer proximity to viewport edge.
/// Returns speed in pixels per frame (to be applied via scroll_with_delta).
/// Distance is measured from the edge of the safety zone outward.
fn selection_edge_autoscroll_speed(proximity: f32, line_height: f32) -> f32 {
    // Minimum speed: 1 line per frame
    let min_speed = line_height;
    // Maximum speed: 8 lines per frame
    let max_speed = line_height * 8.0;

    // Calculate speed factor based on proximity (pixels beyond safety zone)
    // Starts slow at the edge, gets faster as pointer moves further away
    let speed_factor = (proximity / line_height).clamp(0.0, 6.0);

    // Interpolate between min and max speed
    let speed = min_speed + (max_speed - min_speed) * (speed_factor / 6.0);

    speed.clamp(min_speed, max_speed)
}

/// Helper to calculate terminal selection autoscroll delta (wrapper for generic helper).
fn terminal_selection_autoscroll_delta(
    pointer_pos: Option<egui::Pos2>,
    viewport_rect: egui::Rect,
    line_height: f32,
) -> f32 {
    selection_edge_autoscroll_delta(pointer_pos, viewport_rect, line_height)
}

/// Helper to calculate terminal selection autoscroll speed (wrapper for generic helper).
fn terminal_selection_autoscroll_speed(proximity: f32, line_height: f32) -> f32 {
    selection_edge_autoscroll_speed(proximity, line_height)
}

fn terminal_last_non_empty_row(snapshot: &TerminalSnapshot) -> Option<usize> {
    snapshot.lines.iter().rposition(|line| {
        line.runs
            .iter()
            .any(|run| !run.text.trim_end_matches(' ').is_empty())
    })
}

/// Returns the number of fully blank rows at the start of the snapshot.
/// These rows often appear after OpenCode clears the display and redraws,
/// leaving empty scrollback history above the actual TUI content.
fn terminal_leading_blank_rows(snapshot: &TerminalSnapshot) -> usize {
    snapshot
        .lines
        .iter()
        .position(|line| {
            line.runs
                .iter()
                .any(|run| !run.text.trim_end_matches(' ').is_empty())
        })
        .unwrap_or(snapshot.lines.len())
}

/// Extracts the text of the last non-empty line from a terminal snapshot.
fn terminal_last_line_text(snapshot: &TerminalSnapshot) -> Option<String> {
    let row = terminal_last_non_empty_row(snapshot)?;
    let line = snapshot.lines.get(row)?;
    let mut text = String::new();
    for run in &line.runs {
        text.push_str(&run.text);
    }
    let trimmed = text.trim_end_matches(' ').trim();
    if trimmed.is_empty() {
        return None;
    }
    Some(trimmed.to_lowercase())
}

/// Detects Windows batch "Terminate batch job (Y/N)?" prompt in terminal output.
/// Returns true if the last non-empty line of the snapshot contains the prompt.
fn terminal_has_windows_batch_terminate_prompt(snapshot: &TerminalSnapshot) -> bool {
    let last_line = match terminal_last_line_text(snapshot) {
        Some(line) => line,
        None => return false,
    };
    last_line.contains("terminate batch job") && last_line.contains("(y/n)")
}

fn allocate_terminal_output_surface(
    ui: &mut Ui,
    output_size: Vec2,
    content_height: f32,
    sense: Sense,
) -> (egui::Rect, egui::Response) {
    ui.allocate_exact_size(
        terminal_output_surface_size(output_size, content_height),
        sense,
    )
}

fn terminal_selection_text(
    snapshot: &TerminalSelectionSnapshot,
    selection: Option<&TerminalSelection>,
) -> Option<String> {
    let selection = selection?;
    if !selection.has_selection() || snapshot.lines.is_empty() {
        return None;
    }

    let (start, end) = selection.normalized();
    let last_row = snapshot.lines.len().saturating_sub(1);
    let start_row = start.row.min(last_row);
    let end_row = end.row.min(last_row);

    let mut rendered = String::new();
    for row in start_row..=end_row {
        let line = &snapshot.lines[row];
        let line_width = terminal_selection_line_width(line);
        let start_column = if row == start_row {
            start.column.min(line_width)
        } else {
            0
        };
        let end_column = if row == end_row {
            end.column.min(line_width)
        } else {
            line_width
        };
        if row > start_row && !snapshot.lines[row - 1].wraps_to_next {
            rendered.push('\n');
        }
        rendered.push_str(&slice_terminal_line_columns(line, start_column, end_column));
    }

    Some(rendered)
}

fn terminal_selection_line_width(line: &TerminalSelectionLine) -> usize {
    line.width
}

fn slice_terminal_line_columns(line: &TerminalSelectionLine, start: usize, end: usize) -> String {
    if end <= start {
        return String::new();
    }

    let mut rendered = String::new();
    let mut column = start;

    for cell in &line.cells {
        let cell_end = cell.column.saturating_add(cell.display_width.max(1));
        if cell_end <= start {
            continue;
        }
        if cell.column >= end {
            break;
        }

        if cell.column > column {
            rendered.push_str(&" ".repeat(cell.column.min(end).saturating_sub(column)));
        }

        rendered.push_str(&cell.rendered_text());
        column = cell_end;
    }

    if column < end {
        rendered.push_str(&" ".repeat(end - column));
    }

    rendered
}

fn paint_terminal_selection(
    ui: &mut Ui,
    origin: egui::Pos2,
    snapshot: &TerminalSelectionSnapshot,
    selection: Option<&TerminalSelection>,
    char_width: f32,
    galley: &Galley,
) {
    if snapshot.lines.is_empty() || galley.rows.is_empty() {
        return;
    }

    let Some(selection) = selection.filter(|selection| selection.has_selection()) else {
        return;
    };

    let (start, end) = selection.normalized();
    let fill = with_alpha(ui.visuals().selection.bg_fill, 92);

    let max_row = end
        .row
        .min(snapshot.lines.len().saturating_sub(1))
        .min(galley.rows.len().saturating_sub(1));

    for row in start.row.min(max_row)..=max_row {
        let line_width = terminal_selection_line_width(&snapshot.lines[row]);
        let start_column = if row == start.row {
            start.column.min(line_width)
        } else {
            0
        };
        let end_column = if row == end.row {
            end.column.min(line_width)
        } else {
            line_width
        };

        if end_column <= start_column {
            continue;
        }

        let Some(row_rect) = terminal_selection_row_rect(galley, origin, row) else {
            continue;
        };
        let rect = egui::Rect::from_min_size(
            egui::pos2(origin.x + start_column as f32 * char_width, row_rect.top()),
            egui::vec2(
                (end_column - start_column) as f32 * char_width,
                row_rect.height(),
            ),
        );
        ui.painter().rect_filled(rect, 2.0, fill);
    }
}

fn build_terminal_render(
    snapshot: &TerminalSnapshot,
    font_id: &FontId,
    terminal_exited: bool,
    shell: ShellKind,
    stable_input_cursor_row: Option<usize>,
    time_seconds: f64,
) -> TerminalRenderModel {
    let visible_cursor = visible_terminal_cursor(
        snapshot.cursor,
        terminal_exited,
        shell,
        stable_input_cursor_row,
        time_seconds,
    );
    let cursor_overlay =
        visible_cursor.and_then(|cursor| build_terminal_cursor_overlay(snapshot, cursor));
    let mut job = LayoutJob::default();
    job.wrap.max_width = f32::INFINITY;

    for (line_index, line) in snapshot.lines.iter().enumerate() {
        let block_cursor = visible_cursor
            .filter(|cursor| cursor.y == line_index && cursor.shape == TerminalCursorShape::Block);

        if let (Some(cursor), Some(cursor_line)) = (block_cursor, snapshot.cursor_line.as_ref()) {
            if cursor_line.row == line_index {
                for cell in &cursor_line.cells {
                    let style = if cell.covers_column(cursor.x) {
                        invert_terminal_style(cell.style)
                    } else {
                        cell.style
                    };
                    append_terminal_text(&mut job, &cell.rendered_text(), style, font_id);
                }
            } else {
                for run in &line.runs {
                    append_terminal_text(&mut job, &run.text, run.style, font_id);
                }
            }
        } else if let Some(cursor_line) = snapshot.cursor_line.as_ref() {
            if cursor_line.row == line_index {
                for cell in &cursor_line.cells {
                    append_terminal_text(&mut job, &cell.rendered_text(), cell.style, font_id);
                }
            } else {
                for run in &line.runs {
                    append_terminal_text(&mut job, &run.text, run.style, font_id);
                }
            }
        } else {
            for run in &line.runs {
                append_terminal_text(&mut job, &run.text, run.style, font_id);
            }
        }

        if line_index + 1 < snapshot.lines.len() {
            job.append(
                "\n",
                0.0,
                TextFormat {
                    font_id: font_id.clone(),
                    ..TextFormat::default()
                },
            );
        }
    }

    TerminalRenderModel {
        layout_job: job,
        cursor_overlay,
    }
}

fn build_terminal_cursor_overlay(
    snapshot: &TerminalSnapshot,
    cursor: TerminalCursor,
) -> Option<TerminalCursorOverlay> {
    if cursor.shape == TerminalCursorShape::Block {
        return None;
    }

    let color = snapshot
        .cursor_line
        .as_ref()
        .filter(|line| line.row == cursor.y)
        .and_then(|line| line.cell_covering_column(cursor.x))
        .map(|cell| to_egui_color(cell.style.fg))
        .unwrap_or(TEXT_PRIMARY);

    Some(TerminalCursorOverlay {
        shape: cursor.shape,
        row: cursor.y,
        column: cursor.x,
        width_columns: 1,
        color,
    })
}

fn visible_terminal_cursor(
    cursor: Option<TerminalCursor>,
    terminal_exited: bool,
    shell: ShellKind,
    stable_input_cursor_row: Option<usize>,
    time_seconds: f64,
) -> Option<TerminalCursor> {
    cursor.filter(|cursor| {
        !terminal_exited
            && !cursor_hidden_by_row_filter(shell, stable_input_cursor_row, cursor.y)
            && (!cursor.blinking || terminal_cursor_blink_phase_visible(time_seconds))
    })
}

fn terminal_cursor_blink_phase_visible(time_seconds: f64) -> bool {
    ((time_seconds / CURSOR_BLINK_STEP_SECS).floor() as u64) % 2 == 0
}

fn cursor_hidden_by_row_filter(
    shell: ShellKind,
    stable_input_cursor_row: Option<usize>,
    cursor_row: usize,
) -> bool {
    shell == ShellKind::PowerShell && stable_input_cursor_row != Some(cursor_row)
}

fn sync_terminal_cursor_row_state(terminal: &mut TerminalEntry, time_seconds: f64) {
    let current_cursor_row = terminal.render_cache.cursor.map(|cursor| cursor.y);

    if terminal.shell != ShellKind::PowerShell {
        terminal.last_cursor_row = current_cursor_row;
        terminal.last_cursor_row_changed_at = None;
        terminal.stable_input_cursor_row = current_cursor_row;
        return;
    }

    update_stable_cursor_row(
        &mut terminal.last_cursor_row,
        &mut terminal.last_cursor_row_changed_at,
        &mut terminal.stable_input_cursor_row,
        current_cursor_row,
        time_seconds,
    );
}

fn update_stable_cursor_row(
    last_cursor_row: &mut Option<usize>,
    last_cursor_row_changed_at: &mut Option<f64>,
    stable_input_cursor_row: &mut Option<usize>,
    current_cursor_row: Option<usize>,
    time_seconds: f64,
) {
    if current_cursor_row != *last_cursor_row {
        *last_cursor_row = current_cursor_row;
        *last_cursor_row_changed_at = Some(time_seconds);
    }

    let Some(current_cursor_row) = current_cursor_row else {
        *stable_input_cursor_row = None;
        return;
    };

    if *stable_input_cursor_row == Some(current_cursor_row) {
        return;
    }

    if last_cursor_row_changed_at.is_some_and(|changed_at| {
        time_seconds >= changed_at
            && (time_seconds - changed_at) >= POWERSHELL_CURSOR_ROW_STABLE_SECS
    }) {
        *stable_input_cursor_row = Some(current_cursor_row);
    }
}

fn invert_terminal_style(style: crate::terminal::TerminalStyle) -> crate::terminal::TerminalStyle {
    crate::terminal::TerminalStyle {
        fg: style.bg,
        bg: style.fg,
        ..style
    }
}

fn append_terminal_text(
    job: &mut LayoutJob,
    text: &str,
    style: crate::terminal::TerminalStyle,
    font_id: &FontId,
) {
    let fg = to_egui_color(style.fg);
    let mut format = TextFormat {
        font_id: font_id.clone(),
        color: fg,
        background: normalize_terminal_background(style.bg),
        italics: style.italic,
        ..TextFormat::default()
    };

    if style.underline {
        format.underline = Stroke::new(1.0, fg);
    }
    if style.strike {
        format.strikethrough = Stroke::new(1.0, fg);
    }

    job.append(text, 0.0, format);
}

fn paint_terminal_cursor(
    ui: &mut Ui,
    origin: egui::Pos2,
    char_width: f32,
    line_height: f32,
    overlay: TerminalCursorOverlay,
) {
    if overlay.shape == TerminalCursorShape::Block {
        return;
    }

    let rect = terminal_cursor_overlay_rect(origin, char_width, line_height, overlay);
    ui.painter().rect_filled(rect, 0.0, overlay.color);
}

fn terminal_cursor_overlay_rect(
    origin: egui::Pos2,
    char_width: f32,
    line_height: f32,
    overlay: TerminalCursorOverlay,
) -> egui::Rect {
    let x = origin.x + (overlay.column as f32 * char_width);
    let y = origin.y + (overlay.row as f32 * line_height);
    let width = (overlay.width_columns.max(1) as f32 * char_width).max(1.0);

    match overlay.shape {
        TerminalCursorShape::Bar => egui::Rect::from_min_size(
            egui::pos2(x, y),
            egui::vec2(CURSOR_BAR_WIDTH_PX.min(width), line_height),
        ),
        TerminalCursorShape::Underline => {
            let height = CURSOR_UNDERLINE_HEIGHT_PX.min(line_height.max(1.0));
            egui::Rect::from_min_size(
                egui::pos2(x, y + line_height - height),
                egui::vec2(width, height),
            )
        }
        TerminalCursorShape::Block => {
            egui::Rect::from_min_size(egui::pos2(x, y), egui::vec2(width, line_height))
        }
    }
}

fn to_egui_color(color: TerminalColor) -> Color32 {
    Color32::from_rgb(color.r, color.g, color.b)
}

fn normalize_terminal_background(color: TerminalColor) -> Color32 {
    let mapped = to_egui_color(color);
    if color.r <= 6 && color.g <= 6 && color.b <= 6 {
        TERMINAL_OUTPUT_BG
    } else {
        mapped
    }
}

