    fn shape_contains_filled_circle(shape: &egui::epaint::Shape, fill: Color32) -> bool {
        match shape {
            egui::epaint::Shape::Circle(circle) => circle.fill == fill,
            egui::epaint::Shape::Vec(shapes) => shapes
                .iter()
                .any(|shape| shape_contains_filled_circle(shape, fill)),
            _ => false,
        }
    }

    fn frame_contains_filled_circle(output: &egui::FullOutput, fill: Color32) -> bool {
        output
            .shapes
            .iter()
            .any(|shape| shape_contains_filled_circle(&shape.shape, fill))
    }

    fn shape_contains_rect_filled(shape: &egui::epaint::Shape, fill: Color32) -> bool {
        match shape {
            egui::epaint::Shape::Rect(rect_shape) => rect_shape.fill == fill,
            egui::epaint::Shape::Vec(shapes) => shapes
                .iter()
                .any(|shape| shape_contains_rect_filled(shape, fill)),
            _ => false,
        }
    }

    fn frame_contains_rect_filled(output: &egui::FullOutput, fill: Color32) -> bool {
        output
            .shapes
            .iter()
            .any(|shape| shape_contains_rect_filled(&shape.shape, fill))
    }

    fn shape_contains_rect_matching(
        shape: &egui::epaint::Shape,
        matches: &mut impl FnMut(&egui::epaint::RectShape) -> bool,
    ) -> bool {
        match shape {
            egui::epaint::Shape::Rect(rect_shape) => matches(rect_shape),
            egui::epaint::Shape::Vec(shapes) => shapes
                .iter()
                .any(|shape| shape_contains_rect_matching(shape, matches)),
            _ => false,
        }
    }

    fn frame_contains_rect_matching(
        output: &egui::FullOutput,
        mut matches: impl FnMut(&egui::epaint::RectShape) -> bool,
    ) -> bool {
        output
            .shapes
            .iter()
            .any(|shape| shape_contains_rect_matching(&shape.shape, &mut matches))
    }

    fn collect_shape_rects_matching(
        shape: &egui::epaint::Shape,
        matches: &mut impl FnMut(&egui::epaint::RectShape) -> bool,
        rects: &mut Vec<egui::Rect>,
    ) {
        match shape {
            egui::epaint::Shape::Rect(rect_shape) if matches(rect_shape) => {
                rects.push(rect_shape.rect);
            }
            egui::epaint::Shape::Vec(shapes) => {
                for shape in shapes {
                    collect_shape_rects_matching(shape, matches, rects);
                }
            }
            _ => {}
        }
    }

    fn collect_rects_matching(
        output: &egui::FullOutput,
        mut matches: impl FnMut(&egui::epaint::RectShape) -> bool,
    ) -> Vec<egui::Rect> {
        let mut rects = Vec::new();
        for shape in &output.shapes {
            collect_shape_rects_matching(&shape.shape, &mut matches, &mut rects);
        }
        rects
    }

