    #[test]
    fn directory_search_query_stable_respects_debounce() {
        // Regression test: Query stability check must respect debounce duration
        use super::{directory_search_query_stable, DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS};

        let now = 10.0;
        let changed_at = now - DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS + 0.01;

        // Just under debounce threshold - should NOT be stable
        assert!(
            !directory_search_query_stable(now, changed_at),
            "Query should not be stable just before debounce threshold"
        );

        let changed_at_stable = now - DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS - 0.01;

        // Past debounce threshold - should be stable
        assert!(
            directory_search_query_stable(now, changed_at_stable),
            "Query should be stable after debounce threshold"
        );

        // Zero changed_at means no change yet - should be considered stable
        assert!(
            directory_search_query_stable(now, 0.0),
            "Zero changed_at should be considered stable (no change yet)"
        );
    }

    #[test]
    fn directory_search_should_load_deferred_checks_min_length() {
        // Regression test: Short queries should not trigger deferred loading
        use super::{
            directory_search_should_load_deferred, DIRECTORY_SEARCH_MIN_DEFERRED_QUERY_CHARS,
        };

        let now = 10.0;
        let stable_time = now - 1.0; // Well past debounce

        // Empty query - should not load deferred
        assert!(
            !directory_search_should_load_deferred("", now, stable_time),
            "Empty query should not trigger deferred loading"
        );

        // Single char query - should not load deferred (below min)
        assert!(
            !directory_search_should_load_deferred("a", now, stable_time),
            "Single char query should not trigger deferred loading"
        );

        // Query at minimum length - should load if stable
        let min_query = "ab";
        assert_eq!(min_query.len(), DIRECTORY_SEARCH_MIN_DEFERRED_QUERY_CHARS);
        assert!(
            directory_search_should_load_deferred(min_query, now, stable_time),
            "Query at min length and stable should trigger deferred loading"
        );

        // Longer query - should load if stable
        assert!(
            directory_search_should_load_deferred("search", now, stable_time),
            "Longer stable query should trigger deferred loading"
        );
    }

    #[test]
    fn directory_search_should_load_deferred_respects_debounce() {
        // Regression test: Query must be stable before deferred loading triggers
        use super::{
            directory_search_query_stable, directory_search_should_load_deferred,
            DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS,
        };

        let now = 10.0;

        // Just changed - not stable yet
        let just_changed = now;
        assert!(
            !directory_search_query_stable(now, just_changed),
            "Just-changed query should not be stable"
        );
        assert!(
            !directory_search_should_load_deferred("search", now, just_changed),
            "Unstable query should not trigger deferred loading"
        );

        // Partially stable - within debounce window
        let partially_stable = now - DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS / 2.0;
        assert!(
            !directory_search_query_stable(now, partially_stable),
            "Partially stable query should not pass debounce"
        );
        assert!(
            !directory_search_should_load_deferred("search", now, partially_stable),
            "Query within debounce window should not trigger deferred loading"
        );

        // Fully stable - past debounce window
        let fully_stable = now - DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS - 0.1;
        assert!(
            directory_search_query_stable(now, fully_stable),
            "Fully stable query should pass debounce"
        );
        assert!(
            directory_search_should_load_deferred("search", now, fully_stable),
            "Stable query past debounce should trigger deferred loading"
        );
    }

    #[test]
    fn directory_search_deferred_load_debounce_remaining_waits_until_threshold() {
        // Regression test: Helper should return remaining time during debounce window
        use super::{
            directory_search_deferred_load_debounce_remaining,
            DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS,
        };

        let now = 10.0;
        let query = "search";

        // Just changed - should have close to full debounce remaining
        let just_changed = now;
        let remaining = directory_search_deferred_load_debounce_remaining(query, now, just_changed);
        assert!(
            remaining.is_some(),
            "Should return remaining time immediately after change"
        );
        let remaining_secs = remaining.unwrap();
        assert!(
            remaining_secs > DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS * 0.9,
            "Remaining time should be close to full debounce duration"
        );

        // Partially through debounce
        let partially_elapsed = now - DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS / 2.0;
        let remaining =
            directory_search_deferred_load_debounce_remaining(query, now, partially_elapsed);
        assert!(
            remaining.is_some(),
            "Should return remaining time during debounce window"
        );
        let remaining_secs = remaining.unwrap();
        assert!(
            (remaining_secs - DIRECTORY_SEARCH_DEFERRED_LOAD_DEBOUNCE_SECS / 2.0).abs() < 0.01,
            "Remaining time should be approximately half the debounce duration"
        );
    }

    #[test]
    fn directory_search_deferred_load_debounce_remaining_none_after_threshold() {
        // Regression test: Helper should return None when debounce has expired
        use super::directory_search_deferred_load_debounce_remaining;

        let now = 10.0;
        let query = "search";

        // Past debounce threshold - should return None
        let past_threshold = now - 0.3; // 300ms ago (debounce is 250ms)
        let remaining =
            directory_search_deferred_load_debounce_remaining(query, now, past_threshold);
        assert!(
            remaining.is_none(),
            "Should return None when debounce has expired"
        );

        // Zero changed_at (no change yet) - should return None
        let remaining = directory_search_deferred_load_debounce_remaining(query, now, 0.0);
        assert!(
            remaining.is_none(),
            "Should return None when changed_at is 0 (no change yet)"
        );
    }

    #[test]
    fn directory_search_deferred_load_debounce_remaining_ignores_short_queries() {
        // Regression test: Helper should return None for short queries (below min length)
        use super::{
            directory_search_deferred_load_debounce_remaining,
            DIRECTORY_SEARCH_MIN_DEFERRED_QUERY_CHARS,
        };

        let now = 10.0;
        let just_changed = now;

        // Empty query - should return None
        let remaining = directory_search_deferred_load_debounce_remaining("", now, just_changed);
        assert!(remaining.is_none(), "Should return None for empty query");

        // Single char query - should return None (below min)
        let remaining = directory_search_deferred_load_debounce_remaining("a", now, just_changed);
        assert!(
            remaining.is_none(),
            "Should return None for single char query"
        );

        // Query at minimum length - should return remaining time
        let min_query = "ab";
        assert_eq!(
            min_query.chars().count(),
            DIRECTORY_SEARCH_MIN_DEFERRED_QUERY_CHARS
        );
        let remaining =
            directory_search_deferred_load_debounce_remaining(min_query, now, just_changed);
        assert!(
            remaining.is_some(),
            "Should return remaining time for query at min length"
        );
    }

    #[test]
    fn directory_search_should_load_deferred_counts_chars_not_bytes() {
        // Regression test: Unicode queries should use character count, not byte count
        use super::directory_search_should_load_deferred;

        let now = 10.0;
        let stable_time = now - 1.0; // Well past debounce

        // Single Unicode character (2 bytes in UTF-8) - should NOT load (1 char < 2 min)
        let turkish_char = "ğ";
        assert_eq!(turkish_char.len(), 2); // 2 bytes
        assert_eq!(turkish_char.chars().count(), 1); // 1 character
        assert!(
            !directory_search_should_load_deferred(turkish_char, now, stable_time),
            "Single Unicode char should NOT trigger deferred loading (char count < min)"
        );

        // Two Unicode characters (4 bytes in UTF-8) - should load (2 chars >= 2 min)
        let turkish_two = "ğü";
        assert_eq!(turkish_two.len(), 4); // 4 bytes
        assert_eq!(turkish_two.chars().count(), 2); // 2 characters
        assert!(
            directory_search_should_load_deferred(turkish_two, now, stable_time),
            "Two Unicode chars should trigger deferred loading (char count >= min)"
        );

        // Mixed ASCII and Unicode
        let mixed = "ağ"; // 3 bytes, 2 chars
        assert_eq!(mixed.len(), 3);
        assert_eq!(mixed.chars().count(), 2);
        assert!(
            directory_search_should_load_deferred(mixed, now, stable_time),
            "Mixed ASCII/Unicode should use char count for threshold"
        );
    }

    #[test]
    fn directory_search_visible_paths_distinguishes_parent_visibility_from_self_match() {
        // Regression test: A parent directory shown because it contains a matching file
        // should NOT make unrelated sibling files visible
        use super::{collect_directory_search_visible_paths, DirectoryNode};
        use std::path::PathBuf;

        // Create a src folder with user.rs and main.rs (unrelated sibling)
        let user_rs = DirectoryNode {
            name: "user.rs".to_owned(),
            path: PathBuf::from("/project/src/user.rs"),
            is_dir: false,
            is_placeholder: false,
            is_deferred: false,
            children: vec![],
        };
        let main_rs = DirectoryNode {
            name: "main.rs".to_owned(),
            path: PathBuf::from("/project/src/main.rs"),
            is_dir: false,
            is_placeholder: false,
            is_deferred: false,
            children: vec![],
        };
        let src = DirectoryNode {
            name: "src".to_owned(),
            path: PathBuf::from("/project/src"),
            is_dir: true,
            is_placeholder: false,
            is_deferred: false,
            children: vec![user_rs, main_rs],
        };
        let root = DirectoryNode {
            name: "project".to_owned(),
            path: PathBuf::from("/project"),
            is_dir: true,
            is_placeholder: false,
            is_deferred: false,
            children: vec![src],
        };

        let visible = collect_directory_search_visible_paths(&root, "user");

        // src is visible because it contains the match
        assert!(
            visible.directories.contains(&PathBuf::from("/project/src")),
            "Parent directory containing match should be visible"
        );
        // user.rs is visible because it matches
        assert!(
            visible
                .files
                .contains(&PathBuf::from("/project/src/user.rs")),
            "Matching file should be visible"
        );
        // main.rs is NOT visible (sibling of match, not forced by parent's visibility)
        assert!(
            !visible.files.contains(&PathBuf::from("/project/src/main.rs")),
            "Unmatched sibling file should not be visible when parent is visible due to containing a match"
        );
    }

