    #[test]
    fn browser_mcp_tool_allowlist_rejects_hidden_coordinate_tools() {
        // Public tools should be allowed
        assert!(AdeApp::is_browser_mcp_tool_allowed("browser_click"));
        assert!(AdeApp::is_browser_mcp_tool_allowed("browser_page_summary"));
        assert!(AdeApp::is_browser_mcp_tool_allowed("browser_evaluate"));
        assert!(AdeApp::is_browser_mcp_tool_allowed("browser_navigate"));
        // Hidden coordinate tools should be rejected even if client knows the name
        assert!(!AdeApp::is_browser_mcp_tool_allowed(
            "browser_mouse_click_xy"
        ));
        assert!(!AdeApp::is_browser_mcp_tool_allowed(
            "browser_mouse_move_xy"
        ));
        assert!(!AdeApp::is_browser_mcp_tool_allowed(
            "browser_mouse_drag_xy"
        ));
        assert!(!AdeApp::is_browser_mcp_tool_allowed("browser_mouse_down"));
        assert!(!AdeApp::is_browser_mcp_tool_allowed("browser_mouse_up"));
        assert!(!AdeApp::is_browser_mcp_tool_allowed("browser_mouse_wheel"));
        // Unknown tools should also be rejected
        assert!(!AdeApp::is_browser_mcp_tool_allowed("browser_hack"));
        assert!(!AdeApp::is_browser_mcp_tool_allowed(
            "browser_run_code_unsafe"
        ));
    }

    #[test]
    fn browser_mcp_rejects_cross_project_request_before_ui_mutation() {
        let ctx = Context::default();
        let mut app = test_app([(1, test_terminal_entry(1, 7))], Some(1));
        app.projects
            .insert(7, test_project(7, "Allowed", "C:/allowed", &[], &[]));
        app.projects
            .insert(8, test_project(8, "Blocked", "C:/blocked", &[], &[]));
        let request = crate::browser_mcp_service::BrowserMcpIpcRequest {
            request_id: "request".to_owned(),
            terminal_id: Some(1),
            project_id: Some(8),
            session_id: None,
            tool: "browser_navigate".to_owned(),
            params: serde_json::json!({ "url": "https://blocked.example" }),
        };
        let scope = crate::browser_mcp_service::BrowserMcpAuthScope {
            terminal_id: 1,
            project_id: Some(7),
            session_id: None,
        };

        let response = app.handle_browser_mcp_request(&ctx, request, scope);

        assert!(response.is_error);
        assert_eq!(response.text, "Browser MCP project authorization mismatch");
        assert!(!app.browser_panel_open_projects.contains(&8));
        assert!(!app
            .embedded_browsers_by_scope
            .contains_key(&BrowserScopeKey::Project(8)));
        assert_eq!(app.projects.get(&8).unwrap().browser_last_url, None);
    }

