    #[test]
    fn browser_tab_close_rect_stays_inside_tab_top_right() {
        let tab_rect = egui::Rect::from_min_size(
            egui::pos2(20.0, 40.0),
            egui::vec2(super::BROWSER_TAB_WIDTH, super::BROWSER_TAB_HEIGHT),
        );

        let close_rect = super::browser_tab_close_rect(tab_rect);
        let close_hover_rect = super::browser_tab_close_hover_rect(tab_rect);
        let label_rect = super::browser_tab_label_rect(tab_rect);

        assert!(tab_rect.contains(close_rect.min));
        assert!(tab_rect.contains(close_rect.max));
        assert!(tab_rect.contains(close_hover_rect.min));
        assert!(tab_rect.contains(close_hover_rect.max));
        assert!(close_hover_rect.contains(close_rect.center()));
        assert_eq!(
            close_rect.right(),
            tab_rect.right() - super::BROWSER_TAB_CLOSE_MARGIN
        );
        // Close button is centered vertically: top = tab_rect.top() + ((tab_rect.height() - close_size) / 2)
        let expected_top = tab_rect.top()
            + ((tab_rect.height() - super::BROWSER_TAB_CLOSE_SIZE.min(tab_rect.height())) / 2.0)
                .max(0.0);
        assert_eq!(close_rect.top(), expected_top);
        assert!(label_rect.right() <= close_rect.left() - super::BROWSER_TAB_LABEL_RIGHT_GAP);
        assert!(!label_rect.intersects(close_rect));
    }

    #[test]
    fn browser_tab_close_hover_uses_pointing_hand_cursor() {
        let ctx = Context::default();
        ctx.set_fonts(FontDefinitions::default());
        let tab_rect = egui::Rect::from_min_size(
            egui::pos2(20.0, 40.0),
            egui::vec2(super::BROWSER_TAB_WIDTH, super::BROWSER_TAB_HEIGHT),
        );
        let close_rect = super::browser_tab_close_hover_rect(tab_rect);

        let mut observed_close_rect = None;
        let _ = ctx.run(RawInput::default(), |ctx| {
            egui::CentralPanel::default()
                .frame(egui::Frame::none())
                .show(ctx, |ui| {
                    ui.allocate_space(egui::vec2(260.0, 120.0));
                    let response = super::browser_tab_close_interaction(ui, 1, 2, close_rect);
                    observed_close_rect = Some(response.rect);
                });
        });
        let hover_pos = observed_close_rect
            .expect("browser tab close response rect")
            .center();

        let output = ctx.run(
            RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::pos2(0.0, 0.0),
                    egui::vec2(260.0, 120.0),
                )),
                events: vec![Event::PointerMoved(hover_pos)],
                ..RawInput::default()
            },
            |ctx| {
                egui::CentralPanel::default()
                    .frame(egui::Frame::none())
                    .show(ctx, |ui| {
                        ui.allocate_space(egui::vec2(260.0, 120.0));
                        let response = super::browser_tab_close_interaction(ui, 1, 2, close_rect);
                        super::set_pointing_hand_cursor_on_hover_rect(ctx, close_rect);
                        assert!(response.hovered());
                    });
            },
        );

        assert_eq!(
            output.platform_output.cursor_icon,
            egui::CursorIcon::PointingHand,
            "hovering the browser tab close x should show a clickable cursor"
        );
    }

    #[derive(Clone, Copy)]
    struct BrowserTabTooltipTestRects {
        tab_rect: egui::Rect,
        close_hover_rect: egui::Rect,
        add_rect: egui::Rect,
    }

    fn output_contains_text(output: &egui::FullOutput, needle: &str) -> bool {
        output.shapes.iter().any(|shape| {
            let egui::epaint::Shape::Text(text_shape) = &shape.shape else {
                return false;
            };
            text_shape.galley.text().contains(needle)
        })
    }

    fn draw_browser_tab_tooltip_test_ui(
        ctx: &Context,
        hover_pos: Option<egui::Pos2>,
        can_add_tab: bool,
    ) -> (egui::FullOutput, BrowserTabTooltipTestRects) {
        const TAB_TOOLTIP: &str = "https://tooltip.example/browser-tab";

        let mut raw_input = RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(320.0, 140.0),
            )),
            ..RawInput::default()
        };
        if let Some(pos) = hover_pos {
            raw_input.events.push(Event::PointerMoved(pos));
        }

        let mut rects = None;
        let output = ctx.run(raw_input, |ctx| {
            egui::CentralPanel::default()
                .frame(egui::Frame::none())
                .show(ctx, |ui| {
                    ui.allocate_space(egui::vec2(20.0, 40.0));
                    ui.horizontal(|ui| {
                        let (tab_rect, tab_response) = ui.allocate_exact_size(
                            egui::vec2(super::BROWSER_TAB_WIDTH, super::BROWSER_TAB_HEIGHT),
                            egui::Sense::click(),
                        );
                        let close_hover_rect = super::browser_tab_close_hover_rect(tab_rect);
                        let close_response =
                            super::browser_tab_close_interaction(ui, 1, 2, close_hover_rect);
                        let close_hovered = close_response.hovered()
                            || super::set_pointing_hand_cursor_on_hover_rect(ctx, close_hover_rect);
                        if !close_hovered {
                            let tab_body_tooltip_hovered = ctx
                                .input(|input| input.pointer.hover_pos())
                                .is_some_and(|pos| {
                                    tab_rect.contains(pos) && !close_hover_rect.contains(pos)
                                });
                            super::show_tooltip_above_at(
                                ui,
                                tab_response.id,
                                tab_rect,
                                TAB_TOOLTIP,
                                tab_body_tooltip_hovered,
                            );
                        }

                        ui.add_space(4.0);
                        let add_response = super::browser_tab_add_button(ui, can_add_tab);
                        if can_add_tab {
                            super::set_pointing_hand_cursor_on_hover_rect(
                                ctx,
                                super::browser_tab_add_hover_rect(add_response.rect),
                            );
                        }

                        rects = Some(BrowserTabTooltipTestRects {
                            tab_rect,
                            close_hover_rect,
                            add_rect: add_response.rect,
                        });
                    });
                });
        });

        (output, rects.expect("browser tab tooltip test rects"))
    }

